impl NativeArrayValueOperation {
    fn from_tag(tag: u8) -> Option<Self> {
        match tag {
            value if value == Self::Values as u8 => Some(Self::Values),
            value if value == Self::Keys as u8 => Some(Self::Keys),
            value if value == Self::FirstKey as u8 => Some(Self::FirstKey),
            value if value == Self::LastKey as u8 => Some(Self::LastKey),
            value if value == Self::Current as u8 => Some(Self::Current),
            value if value == Self::IsList as u8 => Some(Self::IsList),
            _ => None,
        }
    }

    fn callable(self) -> &'static str {
        match self {
            Self::Values => "array_values()",
            Self::Keys => "array_keys()",
            Self::FirstKey => "array_key_first()",
            Self::LastKey => "array_key_last()",
            Self::Current => "current()",
            Self::IsList => "array_is_list()",
        }
    }
}

impl NativeArrayQueryOperation {
    fn from_tag(tag: u8) -> Option<Self> {
        match tag {
            value if value == Self::KeysMatching as u8 => Some(Self::KeysMatching),
            value if value == Self::Contains as u8 => Some(Self::Contains),
            value if value == Self::Search as u8 => Some(Self::Search),
            value if value == Self::Flip as u8 => Some(Self::Flip),
            value if value == Self::CountValues as u8 => Some(Self::CountValues),
            value if value == Self::Sum as u8 => Some(Self::Sum),
            value if value == Self::Product as u8 => Some(Self::Product),
            value if value == Self::FillKeys as u8 => Some(Self::FillKeys),
            value if value == Self::Combine as u8 => Some(Self::Combine),
            _ => None,
        }
    }

    fn callable(self) -> &'static str {
        match self {
            Self::KeysMatching => "array_keys()",
            Self::Contains => "in_array()",
            Self::Search => "array_search()",
            Self::Flip => "array_flip()",
            Self::CountValues => "array_count_values()",
            Self::Sum => "array_sum()",
            Self::Product => "array_product()",
            Self::FillKeys => "array_fill_keys()",
            Self::Combine => "array_combine()",
        }
    }

    fn requires_operand(self) -> bool {
        matches!(
            self,
            Self::KeysMatching | Self::Contains | Self::Search | Self::FillKeys | Self::Combine
        )
    }

    fn accepts_flags(self) -> bool {
        matches!(self, Self::KeysMatching | Self::Contains | Self::Search)
    }
}

impl NativeArrayTransformOperation {
    fn from_tag(tag: u8) -> Option<Self> {
        match tag {
            value if value == Self::Reverse as u8 => Some(Self::Reverse),
            value if value == Self::Slice as u8 => Some(Self::Slice),
            value if value == Self::Chunk as u8 => Some(Self::Chunk),
            value if value == Self::Pad as u8 => Some(Self::Pad),
            value if value == Self::Merge as u8 => Some(Self::Merge),
            value if value == Self::Replace as u8 => Some(Self::Replace),
            value if value == Self::ChangeKeyCase as u8 => Some(Self::ChangeKeyCase),
            value if value == Self::IntersectKey as u8 => Some(Self::IntersectKey),
            value if value == Self::DiffKey as u8 => Some(Self::DiffKey),
            value if value == Self::DiffValues as u8 => Some(Self::DiffValues),
            value if value == Self::IntersectValues as u8 => Some(Self::IntersectValues),
            value if value == Self::Unique as u8 => Some(Self::Unique),
            value if value == Self::FilterTruthy as u8 => Some(Self::FilterTruthy),
            _ => None,
        }
    }

    fn callable(self) -> &'static str {
        match self {
            Self::Reverse => "array_reverse()",
            Self::Slice => "array_slice()",
            Self::Chunk => "array_chunk()",
            Self::Pad => "array_pad()",
            Self::Merge => "array_merge()",
            Self::Replace => "array_replace()",
            Self::ChangeKeyCase => "array_change_key_case()",
            Self::IntersectKey => "array_intersect_key()",
            Self::DiffKey => "array_diff_key()",
            Self::DiffValues => "array_diff()",
            Self::IntersectValues => "array_intersect()",
            Self::Unique => "array_unique()",
            Self::FilterTruthy => "array_filter()",
        }
    }

    fn requires_operand(self) -> bool {
        matches!(
            self,
            Self::Pad
                | Self::Merge
                | Self::Replace
                | Self::IntersectKey
                | Self::DiffKey
                | Self::DiffValues
                | Self::IntersectValues
        )
    }

    fn accepted_flags(self) -> u8 {
        match self {
            Self::Reverse | Self::Chunk => NATIVE_ARRAY_TRANSFORM_PRESERVE_KEYS,
            Self::Slice => NATIVE_ARRAY_TRANSFORM_PRESERVE_KEYS | NATIVE_ARRAY_TRANSFORM_HAS_LENGTH,
            Self::Pad
            | Self::Merge
            | Self::Replace
            | Self::ChangeKeyCase
            | Self::IntersectKey
            | Self::DiffKey
            | Self::DiffValues
            | Self::IntersectValues
            | Self::Unique
            | Self::FilterTruthy => 0,
        }
    }
}

