impl NativeRequestState {
    fn empty() -> Self {
        Self {
            superglobals: HashMap::new(),
        }
    }

    fn cli_seed() -> Self {
        Self::cli_seed_from(NativeRequestSeed::from_environment())
    }

    fn cli_seed_from(seed: NativeRequestSeed) -> Self {
        let mut request_state = Self::empty();
        request_state.insert_superglobal_value(
            NativeRequestStateBag::Server,
            b"SCRIPT_NAME",
            b"/index.php".to_vec(),
        );

        if let Some(request_method) = seed.request_method.as_deref() {
            request_state.insert_superglobal_value(
                NativeRequestStateBag::Server,
                b"REQUEST_METHOD",
                request_method,
            );
        }
        if let Some(query_string) = seed.query_string.as_deref() {
            request_state.insert_superglobal_value(
                NativeRequestStateBag::Server,
                b"QUERY_STRING",
                query_string,
            );
            request_state.insert_urlencoded_scalar_bag(
                NativeRequestStateBag::Get,
                query_string,
                true,
            );
        }
        if let Some(content_type) = seed.content_type.as_deref() {
            request_state.insert_superglobal_value(
                NativeRequestStateBag::Server,
                b"CONTENT_TYPE",
                content_type,
            );
        }
        if let Some(request_body) = seed.request_body.as_deref() {
            request_state.insert_superglobal_value(
                NativeRequestStateBag::Server,
                b"CONTENT_LENGTH",
                request_body.len().to_string().into_bytes(),
            );
            if seed
                .content_type
                .as_deref()
                .is_some_and(is_form_urlencoded_content_type)
            {
                request_state.insert_urlencoded_scalar_bag(
                    NativeRequestStateBag::Post,
                    request_body,
                    true,
                );
            }
        }
        if let Some(cookie_header) = seed.cookie_header.as_deref() {
            request_state.insert_superglobal_value(
                NativeRequestStateBag::Server,
                b"HTTP_COOKIE",
                cookie_header,
            );
            request_state.insert_cookie_scalar_bag(cookie_header);
        }

        request_state
    }

    fn insert_superglobal_value(
        &mut self,
        bag: NativeRequestStateBag,
        key: impl AsRef<[u8]>,
        value: impl Into<Vec<u8>>,
    ) {
        self.superglobals
            .entry(bag)
            .or_default()
            .insert(key.as_ref().to_vec(), value.into());
    }

    fn superglobal_value(&self, bag: NativeRequestStateBag, key: &[u8]) -> Option<&[u8]> {
        self.superglobals
            .get(&bag)
            .and_then(|values| values.get(key))
            .map(Vec::as_slice)
    }

    fn superglobal_runtime_value(&self, bag: NativeRequestStateBag, key: &[u8]) -> Value {
        value_from_php_string_bytes(
            self.superglobal_value(bag, key)
                .map(<[u8]>::to_vec)
                .unwrap_or_default(),
        )
    }

    fn superglobal_array(&self, bag: NativeRequestStateBag) -> PhpArray {
        let mut array = PhpArray::new();
        if let Some(values) = self.superglobals.get(&bag) {
            for (key, value) in values {
                array.insert(
                    ArrayKey::string_bytes(key.clone()),
                    value_from_php_string_bytes(value.clone()),
                );
            }
        }
        array
    }

    fn insert_urlencoded_scalar_bag(
        &mut self,
        bag: NativeRequestStateBag,
        input: &[u8],
        mirror_request: bool,
    ) {
        for pair in input.split(|byte| *byte == b'&') {
            if pair.is_empty() {
                continue;
            }

            let (raw_key, raw_value) = split_once_byte(pair, b'=').unwrap_or((pair, &[]));
            let Some(key) = request_scalar_root_key_from_urlencoded(raw_key) else {
                continue;
            };
            let value = url_decode_form_component(raw_value);
            self.insert_superglobal_value(bag, &key, value.clone());
            if mirror_request {
                self.insert_superglobal_value(NativeRequestStateBag::Request, key, value);
            }
        }
    }

    fn insert_cookie_scalar_bag(&mut self, cookie_header: &[u8]) {
        for pair in cookie_header.split(|byte| *byte == b';') {
            let pair = trim_ascii_whitespace(pair);
            if pair.is_empty() {
                continue;
            }

            let Some((raw_key, raw_value)) = split_once_byte(pair, b'=') else {
                continue;
            };
            let Some(key) = request_scalar_root_key_from_urlencoded(raw_key) else {
                continue;
            };
            self.insert_superglobal_value(
                NativeRequestStateBag::Cookie,
                key,
                url_decode_form_component(raw_value),
            );
        }
    }
}

impl NativeRequestSeed {
    fn from_environment() -> Self {
        Self {
            query_string: environment_bytes("PHPC_QUERY_STRING"),
            request_body: environment_bytes("PHPC_REQUEST_BODY"),
            request_method: environment_bytes("PHPC_REQUEST_METHOD"),
            content_type: environment_bytes("PHPC_CONTENT_TYPE"),
            cookie_header: environment_bytes("PHPC_COOKIE"),
        }
    }
}

fn environment_bytes(name: &str) -> Option<Vec<u8>> {
    std::env::var_os(name).map(|value| value.to_string_lossy().into_owned().into_bytes())
}

fn split_once_byte(value: &[u8], needle: u8) -> Option<(&[u8], &[u8])> {
    let index = value.iter().position(|byte| *byte == needle)?;
    Some((&value[..index], &value[index + 1..]))
}

fn trim_ascii_whitespace(mut value: &[u8]) -> &[u8] {
    while value.first().is_some_and(u8::is_ascii_whitespace) {
        value = &value[1..];
    }
    while value.last().is_some_and(u8::is_ascii_whitespace) {
        value = &value[..value.len() - 1];
    }
    value
}

fn request_scalar_root_key_from_urlencoded(raw_key: &[u8]) -> Option<Vec<u8>> {
    let mut key = url_decode_form_component(raw_key);
    if key.iter().any(|byte| *byte == b'[') {
        return None;
    }
    for byte in &mut key {
        if matches!(*byte, b'.' | b' ') {
            *byte = b'_';
        }
    }
    Some(key)
}

fn request_state_lossless_float_key_bytes(value: f64) -> Option<Vec<u8>> {
    if !value.is_finite() || value.fract() != 0.0 {
        return None;
    }

    let max_exclusive = 2.0_f64.powi(63);
    if !(i64::MIN as f64..max_exclusive).contains(&value) {
        return None;
    }

    let integer = value as i64;
    if integer as f64 == value {
        Some(integer.to_string().into_bytes())
    } else {
        None
    }
}

fn request_state_key_bytes_from_scalar(
    value: NativeScalarValue,
) -> Result<Vec<u8>, NativeRequestStateOperationStatus> {
    match value.tag {
        NativeScalarTag::Null => Ok(Vec::new()),
        NativeScalarTag::Bool => Ok(if value.bool_value != 0 {
            b"1".to_vec()
        } else {
            b"0".to_vec()
        }),
        NativeScalarTag::Int => Ok(value.int_value.to_string().into_bytes()),
        NativeScalarTag::Float => request_state_lossless_float_key_bytes(value.float_value)
            .ok_or(NativeRequestStateOperationStatus::UnsupportedKeyCoercion),
    }
}

fn url_decode_form_component(value: &[u8]) -> Vec<u8> {
    let mut decoded = Vec::with_capacity(value.len());
    let mut index = 0;
    while index < value.len() {
        match value[index] {
            b'+' => {
                decoded.push(b' ');
                index += 1;
            }
            b'%' if index + 2 < value.len() => {
                if let (Some(high), Some(low)) =
                    (hex_value(value[index + 1]), hex_value(value[index + 2]))
                {
                    decoded.push((high << 4) | low);
                    index += 3;
                } else {
                    decoded.push(value[index]);
                    index += 1;
                }
            }
            byte => {
                decoded.push(byte);
                index += 1;
            }
        }
    }
    decoded
}

fn hex_value(value: u8) -> Option<u8> {
    match value {
        b'0'..=b'9' => Some(value - b'0'),
        b'a'..=b'f' => Some(value - b'a' + 10),
        b'A'..=b'F' => Some(value - b'A' + 10),
        _ => None,
    }
}

fn is_form_urlencoded_content_type(value: &[u8]) -> bool {
    trim_ascii_whitespace(
        split_once_byte(value, b';')
            .map(|(mime, _)| mime)
            .unwrap_or(value),
    )
    .eq_ignore_ascii_case(b"application/x-www-form-urlencoded")
}

impl NativeRequestStateOperationResult {
    pub const fn null() -> Self {
        Self {
            value: NativeValueHandle::null(),
            array: NativeArrayHandle::null(),
            is_set: 0,
            result_kind: 0,
            status: 0,
        }
    }

    fn unsupported(status: NativeRequestStateOperationStatus) -> Self {
        Self {
            status: status.abi_tag(),
            ..Self::null()
        }
    }

    fn value(value: Value, is_set: bool, status: NativeRequestStateOperationStatus) -> Self {
        Self {
            value: NativeValueHandle::from_value(value),
            array: NativeArrayHandle::null(),
            is_set: u8::from(is_set),
            result_kind: PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
            status: status.abi_tag(),
        }
    }

    fn array(array: PhpArray, is_set: bool, status: NativeRequestStateOperationStatus) -> Self {
        Self {
            value: NativeValueHandle::null(),
            array: NativeArrayHandle::from_array(array),
            is_set: u8::from(is_set),
            result_kind: PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
            status: status.abi_tag(),
        }
    }

    fn presence(is_set: bool, status: NativeRequestStateOperationStatus) -> Self {
        Self {
            value: NativeValueHandle::null(),
            array: NativeArrayHandle::null(),
            is_set: u8::from(is_set),
            result_kind: PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
            status: status.abi_tag(),
        }
    }

    fn bag_presence(is_set: bool, status: NativeRequestStateOperationStatus) -> Self {
        Self {
            value: NativeValueHandle::null(),
            array: NativeArrayHandle::null(),
            is_set: u8::from(is_set),
            result_kind: PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
            status: status.abi_tag(),
        }
    }

    unsafe fn free_owned_handles(self) {
        match self.result_kind {
            PHPC_NATIVE_REQUEST_STATE_OP_VALUE => {
                unsafe { phpc_native_value_free(self.value) };
            }
            PHPC_NATIVE_REQUEST_STATE_OP_ARRAY => {
                unsafe { phpc_native_array_free(self.array) };
            }
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE | PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE => {}
            _ => {}
        }
    }
}

impl NativeRequestStateKeyResult {
    fn ok(bytes: Vec<u8>) -> Self {
        Self {
            buffer: NativeByteBuffer::from_vec(bytes),
            status: NativeRequestStateOperationStatus::Ok.abi_tag(),
        }
    }

    fn unsupported(status: NativeRequestStateOperationStatus) -> Self {
        Self {
            buffer: NativeByteBuffer::empty(),
            status: status.abi_tag(),
        }
    }
}

impl<'a> NativeRequestStateOperation<'a> {
    unsafe fn from_abi(
        handle: NativeRequestStateHandle,
        operation_kind: NativeRequestStateOperationKind,
        bag_ptr: *const u8,
        bag_len: usize,
        key_ptr: *const u8,
        key_len: usize,
        key_status: u8,
    ) -> Result<Self, NativeRequestStateOperationStatus> {
        let key_status = NativeRequestStateOperationStatus::from_abi_tag(key_status)
            .ok_or(NativeRequestStateOperationStatus::InvalidAbi)?;
        if operation_kind.uses_keyed_scalar_snapshot() {
            return unsafe { Self::keyed(handle, bag_ptr, bag_len, key_ptr, key_len, key_status) };
        }

        if operation_kind.uses_bag_snapshot()
            && (key_status != NativeRequestStateOperationStatus::Ok
                || !key_ptr.is_null()
                || key_len != 0)
        {
            return Err(NativeRequestStateOperationStatus::InvalidAbi);
        }

        unsafe { Self::bag(handle, bag_ptr, bag_len) }
    }

    unsafe fn keyed(
        handle: NativeRequestStateHandle,
        bag_ptr: *const u8,
        bag_len: usize,
        key_ptr: *const u8,
        key_len: usize,
        key_status: NativeRequestStateOperationStatus,
    ) -> Result<Self, NativeRequestStateOperationStatus> {
        if key_status != NativeRequestStateOperationStatus::Ok {
            return Err(key_status);
        }
        let request_state =
            unsafe { handle.ptr.as_ref() }.ok_or(NativeRequestStateOperationStatus::NullState)?;
        let bag = unsafe { native_abi_bytes(bag_ptr, bag_len) }
            .ok_or(NativeRequestStateOperationStatus::InvalidAbi)?;
        let key = unsafe { native_abi_bytes(key_ptr, key_len) }
            .ok_or(NativeRequestStateOperationStatus::InvalidAbi)?;
        let bag = NativeRequestStateBag::from_abi_bytes(bag)
            .ok_or(NativeRequestStateOperationStatus::UnknownBag)?;
        if !bag.supports_keyed_scalar_snapshot() {
            return Err(NativeRequestStateOperationStatus::UnsupportedKeyedBag);
        }

        Ok(Self::Keyed {
            request_state,
            bag,
            key,
        })
    }

    unsafe fn bag(
        handle: NativeRequestStateHandle,
        bag_ptr: *const u8,
        bag_len: usize,
    ) -> Result<Self, NativeRequestStateOperationStatus> {
        let request_state =
            unsafe { handle.ptr.as_ref() }.ok_or(NativeRequestStateOperationStatus::NullState)?;
        let bag = unsafe { native_abi_bytes(bag_ptr, bag_len) }
            .ok_or(NativeRequestStateOperationStatus::InvalidAbi)?;
        let bag = NativeRequestStateBag::from_abi_bytes(bag)
            .ok_or(NativeRequestStateOperationStatus::UnknownBag)?;

        Ok(Self::Bag { request_state, bag })
    }

    fn value_bytes(&self) -> Option<&[u8]> {
        match self {
            Self::Keyed {
                request_state,
                bag,
                key,
            } => request_state.superglobal_value(*bag, key),
            Self::Bag { .. } => None,
        }
    }

    fn runtime_value(&self) -> Value {
        match self {
            Self::Keyed {
                request_state,
                bag,
                key,
            } => request_state.superglobal_runtime_value(*bag, key),
            Self::Bag { .. } => Value::Null,
        }
    }

    fn array(&self) -> PhpArray {
        match self {
            Self::Bag { request_state, bag } => request_state.superglobal_array(*bag),
            Self::Keyed { .. } => PhpArray::new(),
        }
    }

    fn is_set(&self) -> bool {
        self.value_bytes().is_some()
    }

    fn bag_is_set(&self) -> bool {
        match self {
            Self::Bag { .. } => true,
            Self::Keyed { .. } => false,
        }
    }

    fn status(&self) -> NativeRequestStateOperationStatus {
        match self {
            Self::Keyed { .. } if self.value_bytes().is_none() => {
                NativeRequestStateOperationStatus::MissingKey
            }
            _ => NativeRequestStateOperationStatus::Ok,
        }
    }

    fn result(
        &self,
        operation_kind: NativeRequestStateOperationKind,
    ) -> NativeRequestStateOperationResult {
        let status = self.status();
        match operation_kind {
            NativeRequestStateOperationKind::Value => NativeRequestStateOperationResult::value(
                self.runtime_value(),
                self.is_set(),
                status,
            ),
            NativeRequestStateOperationKind::Array => {
                NativeRequestStateOperationResult::array(self.array(), self.bag_is_set(), status)
            }
            NativeRequestStateOperationKind::Presence => {
                NativeRequestStateOperationResult::presence(self.is_set(), status)
            }
            NativeRequestStateOperationKind::BagPresence => {
                NativeRequestStateOperationResult::bag_presence(self.bag_is_set(), status)
            }
        }
    }
}

impl NativeScalarValue {
    pub const fn null() -> Self {
        Self {
            tag: NativeScalarTag::Null,
            bool_value: 0,
            int_value: 0,
            float_value: 0.0,
        }
    }

    pub const fn bool(value: bool) -> Self {
        Self {
            tag: NativeScalarTag::Bool,
            bool_value: value as u8,
            int_value: 0,
            float_value: 0.0,
        }
    }

    pub const fn int(value: i64) -> Self {
        Self {
            tag: NativeScalarTag::Int,
            bool_value: 0,
            int_value: value,
            float_value: 0.0,
        }
    }

    pub const fn float(value: f64) -> Self {
        Self {
            tag: NativeScalarTag::Float,
            bool_value: 0,
            int_value: 0,
            float_value: value,
        }
    }

    pub fn tag(&self) -> NativeScalarTag {
        self.tag
    }

    pub fn to_value(self) -> Value {
        match self.tag {
            NativeScalarTag::Null => Value::Null,
            NativeScalarTag::Bool => Value::Bool(self.bool_value != 0),
            NativeScalarTag::Int => Value::Int(self.int_value),
            NativeScalarTag::Float => Value::Float(self.float_value),
        }
    }

    pub fn echo_string(self) -> String {
        self.to_value().echo_string()
    }
}

#[no_mangle]
pub extern "C" fn phpc_native_null() -> NativeScalarValue {
    NativeScalarValue::null()
}

#[no_mangle]
pub extern "C" fn phpc_native_bool(value: bool) -> NativeScalarValue {
    NativeScalarValue::bool(value)
}

#[no_mangle]
pub extern "C" fn phpc_native_int(value: i64) -> NativeScalarValue {
    NativeScalarValue::int(value)
}

#[no_mangle]
pub extern "C" fn phpc_native_float(value: f64) -> NativeScalarValue {
    NativeScalarValue::float(value)
}

/// # Safety
///
/// When `len` is nonzero, `ptr` must point to at least `len` readable bytes.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_string_truthy(ptr: *const u8, len: usize) -> bool {
    if len == 0 || ptr.is_null() {
        return false;
    }

    if len == 1 {
        return unsafe { *ptr } != b'0';
    }

    true
}

#[no_mangle]
pub extern "C" fn phpc_native_array_null() -> NativeArrayHandle {
    NativeArrayHandle::null()
}

#[no_mangle]
pub extern "C" fn phpc_native_array_empty() -> NativeArrayHandle {
    NativeArrayHandle::empty()
}

#[no_mangle]
pub extern "C" fn phpc_native_array_is_null(handle: NativeArrayHandle) -> bool {
    handle.is_null()
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_len(handle: NativeArrayHandle) -> usize {
    unsafe { handle.as_ref() }
        .map(|array| array.value.len())
        .unwrap_or(0)
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_is_truthy(handle: NativeArrayHandle) -> bool {
    unsafe { handle.as_ref() }
        .map(|array| !array.value.is_empty())
        .unwrap_or(false)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. On failure the helper stores a diagnostic handle that
/// the caller owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_len_with_diagnostic(
    handle: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> usize {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(value) = (unsafe { handle.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native value array length failed: value handle is null",
                    )
                    .message(),
                )
            };
        }
        return 0;
    };

    match value {
        Value::Array(array) => array.len(),
        other => {
            if !diagnostic.is_null() {
                unsafe {
                    *diagnostic = NativeDiagnosticHandle::from_message(
                        RuntimeError::unsupported_call(
                            "count()",
                            format!(
                                "only arrays and Countable objects are supported, got {}",
                                other.type_name()
                            ),
                        )
                        .message(),
                    )
                };
            }
            0
        }
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The helper clones from the owned PHP array value
/// boundary and returns an owned PHP value for operation tags: `0`
/// array_values(), `1` array_keys(), `2` array_key_first(), `3`
/// array_key_last(), `4` current(), and `5` array_is_list(). On failure it
/// stores a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_operation_with_diagnostic(
    handle: NativeValueHandle,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    match unsafe { native_value_array_operation_value(handle, operation) } {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` and `operand` must be null or value handles previously returned by
/// the runtime ABI and not yet freed. The helper clones from the PHP array
/// value boundary and returns an owned PHP value for operation tags: `0`
/// array_keys($array, $search, $strict), `1` in_array(), `2` array_search(),
/// `3` array_flip(), `4` array_count_values(), `5` array_sum(), and `6`
/// array_product(), `7` array_fill_keys(), and `8` array_combine(). On failure
/// it stores a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
