/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `key` must be a result returned by the runtime ABI.
/// The returned value handle owns a clone of the indexed array slot. Null
/// handles, invalid keys, and missing keys return a null value handle and store
/// a diagnostic when `diagnostic` is non-null; the caller owns that diagnostic
/// and must release it with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_read_key_with_diagnostic(
    handle: NativeArrayHandle,
    key: NativeArrayKeyMaterializationResult,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(array) = (unsafe { handle.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native array read failed: array handle is null",
                    )
                    .message(),
                )
            };
        }
        return NativeValueHandle::null();
    };

    match native_array_key_materialization_to_array_key(key) {
        Ok(key) => array
            .value
            .get_cloned(key.clone())
            .map(NativeValueHandle::from_value)
            .unwrap_or_else(|| {
                if !diagnostic.is_null() {
                    unsafe {
                        *diagnostic = NativeDiagnosticHandle::from_message(
                            RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
                        )
                    };
                }
                NativeValueHandle::null()
            }),
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `array` and `key` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. The helper borrows both values, materializes
/// `key` through the array_key_exists-specific PHP key boundary, and stores a
/// diagnostic handle on invalid operands when `diagnostic` is non-null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_key_exists_with_diagnostic(
    array: NativeValueHandle,
    key: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(array_value) = (unsafe { array.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native array_key_exists failed: array value handle is null",
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    let Value::Array(array) = array_value else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::unsupported_call(
                        "array_key_exists()",
                        format!(
                            "second argument must be array, got {}",
                            array_value.type_name()
                        ),
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    let Some(key) = (unsafe { key.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_key(
                        "native array_key_exists failed: key value handle is null",
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    match ArrayKey::from_array_key_exists_value(key) {
        Ok(key) => array.contains_key(key),
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            false
        }
    }
}

