pub unsafe extern "C" fn phpc_native_array_lvalue_foreach_value_reference_result(
    mut handle: NativeArrayHandle,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    index: usize,
) -> NativeArrayReferenceResult {
    let Some(array) = (unsafe { handle.as_mut() }) else {
        return NativeArrayReferenceResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array foreach value reference root handle is null",
        );
    };
    let path = match unsafe { native_array_path_from_segments(segments, segment_count) } {
        Ok(path) => path,
        Err(result) => return NativeArrayReferenceResult::from_lvalue_result(result),
    };

    native_array_foreach_value_reference_path_result(&mut array.value, &path, index)
}

/// # Safety
///
/// `handle` and each key handle inside `segments` must be null or handles
/// previously returned by the runtime ABI and not yet freed. `segments` must
/// point to at least one initialized key path segment.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_unset(
    handle: NativeArrayHandle,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
) -> bool {
    let result = unsafe { phpc_native_array_lvalue_unset_result(handle, segments, segment_count) };
    let succeeded = result.succeeded();
    unsafe { phpc_native_array_lvalue_result_free(result) };
    succeeded
}

/// # Safety
