/// # Safety
///
/// `key` must be null or a value handle previously returned by the runtime ABI
/// and not yet freed. The returned result carries a diagnostic when the value
/// cannot be used as an array key; an OK result does not own a value handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_key_from_value_result(
    key: NativeValueHandle,
) -> NativeArrayLvalueResult {
    let Some(key) = (unsafe { key.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue key value handle is null",
        );
    };

    match native_array_key_from_value_result(key) {
        Ok(_) => NativeArrayLvalueResult::ok(),
        Err(result) => result,
    }
}

