fn native_array_lvalue_owner_value_result_dispatch(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    array: impl FnOnce(
        NativeArrayHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayLvalueResult,
    value_root: impl FnOnce(
        NativeValueHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayLvalueResult,
    value_slot: impl FnOnce(
        *mut NativeValueHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayLvalueResult,
    reference_slot: impl FnOnce(
        NativeReferenceHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayLvalueResult,
) -> NativeArrayLvalueResult {
    match owner.tag {
        NATIVE_ARRAY_LVALUE_OWNER_ARRAY => array(owner.array, segments, segment_count),
        NATIVE_ARRAY_LVALUE_OWNER_VALUE_ROOT => value_root(owner.value, segments, segment_count),
        NATIVE_ARRAY_LVALUE_OWNER_VALUE_SLOT => {
            value_slot(owner.value_slot, segments, segment_count)
        }
        NATIVE_ARRAY_LVALUE_OWNER_REFERENCE_SLOT => {
            reference_slot(owner.reference, segments, segment_count)
        }
        _ => native_array_lvalue_owner_invalid_result(owner.tag),
    }
}

fn native_array_lvalue_owner_reference_result_dispatch(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    array: impl FnOnce(
        NativeArrayHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayReferenceResult,
    value_root: impl FnOnce(
        NativeValueHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayReferenceResult,
    value_slot: impl FnOnce(
        *mut NativeValueHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayReferenceResult,
    reference_slot: impl FnOnce(
        NativeReferenceHandle,
        *const NativeArrayPathSegment,
        usize,
    ) -> NativeArrayReferenceResult,
) -> NativeArrayReferenceResult {
    match owner.tag {
        NATIVE_ARRAY_LVALUE_OWNER_ARRAY => array(owner.array, segments, segment_count),
        NATIVE_ARRAY_LVALUE_OWNER_VALUE_ROOT => value_root(owner.value, segments, segment_count),
        NATIVE_ARRAY_LVALUE_OWNER_VALUE_SLOT => {
            value_slot(owner.value_slot, segments, segment_count)
        }
        NATIVE_ARRAY_LVALUE_OWNER_REFERENCE_SLOT => {
            reference_slot(owner.reference, segments, segment_count)
        }
        _ => native_array_lvalue_owner_invalid_reference_result(owner.tag),
    }
}

#[derive(Clone, Copy)]
enum NativeArrayLvalueValueRootOperation {
    Write,
    Unset,
    ByReferenceForeach,
    Reference,
    ReferenceBinding,
}

impl NativeArrayLvalueValueRootOperation {
    fn label(self) -> &'static str {
        match self {
            Self::Write => "write",
            Self::Unset => "unset",
            Self::ByReferenceForeach => "by-reference foreach",
            Self::Reference => "reference",
            Self::ReferenceBinding => "reference binding",
        }
    }
}

/// # Safety
