/// # Safety
///
/// The owner handle, `value`, and each key handle inside `segments` must be
/// null or handles previously returned by the runtime ABI and not yet freed.
/// `segments` must be null when `segment_count` is zero, or point to
/// `segment_count` initialized path segments. This helper does not take
/// ownership of `value`; the caller remains responsible for freeing it. The
/// returned result owns a clone of the assigned PHP expression value.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_assign_value_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    value: NativeValueHandle,
) -> NativeArrayLvalueResult {
    unsafe {
        native_array_lvalue_owner_write_handle_value_result(
            owner,
            segments,
            segment_count,
            value,
            "array lvalue assignment value materialization produced a null value handle",
            |value| value.clone(),
        )
    }
}

unsafe fn native_array_lvalue_owner_write_handle_value_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    value: NativeValueHandle,
    null_value_diagnostic: &'static str,
    expression_value: impl FnOnce(&Value) -> Value,
) -> NativeArrayLvalueResult {
    let Some(value_ref) = (unsafe { value.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            null_value_diagnostic,
        );
    };
    let expression_value = expression_value(value_ref);

    let write = unsafe {
        phpc_native_array_lvalue_owner_write_value_result(owner, segments, segment_count, value)
    };
    if write.tag != NATIVE_ARRAY_LVALUE_OK {
        return write;
    }
    unsafe { phpc_native_array_lvalue_result_free(write) };
    NativeArrayLvalueResult::value(expression_value)
}

struct NativeArrayLvalueWriteBack {
    write_value: Value,
    expression_value: Value,
}

unsafe fn native_array_lvalue_owner_write_back_value_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    write_back: NativeArrayLvalueWriteBack,
) -> NativeArrayLvalueResult {
    let NativeArrayLvalueWriteBack {
        write_value,
        expression_value,
    } = write_back;
    let write_handle = NativeValueHandle::from_value(write_value);
    let result = unsafe {
        native_array_lvalue_owner_write_handle_value_result(
            owner,
            segments,
            segment_count,
            write_handle,
            "array lvalue write-back value materialization produced a null value handle",
            |_| expression_value,
        )
    };
    unsafe { phpc_native_value_free(write_handle) };
    result
}

unsafe fn native_array_lvalue_owner_read_modify_write_value_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    missing_slot_diagnostic: &'static str,
    null_read_diagnostic: &'static str,
    update: impl FnOnce(&Value) -> RuntimeResult<NativeArrayLvalueWriteBack>,
) -> NativeArrayLvalueResult {
    let current =
        unsafe { phpc_native_array_lvalue_owner_read_result(owner, segments, segment_count) };
    if current.tag == NATIVE_ARRAY_LVALUE_MISSING {
        unsafe { phpc_native_array_lvalue_result_free(current) };
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            missing_slot_diagnostic,
        );
    }
    if current.tag != NATIVE_ARRAY_LVALUE_OK {
        return current;
    }

    let Some(current_value) = (unsafe { current.value.as_ref() }) else {
        unsafe { phpc_native_array_lvalue_result_free(current) };
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            null_read_diagnostic,
        );
    };

    let write_back = match update(current_value) {
        Ok(write_back) => write_back,
        Err(error) => {
            unsafe { phpc_native_array_lvalue_result_free(current) };
            return NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                error.message(),
            );
        }
    };
    unsafe { phpc_native_array_lvalue_result_free(current) };

    unsafe {
        native_array_lvalue_owner_write_back_value_result(
            owner,
            segments,
            segment_count,
            write_back,
        )
    }
}

/// # Safety
///
/// The owner handle, `value`, and each key handle inside `segments` must be
/// null or handles previously returned by the runtime ABI and not yet freed.
/// `segments` must be null when `segment_count` is zero, or point to
/// `segment_count` initialized path segments. This helper does not take
/// ownership of `value`; the caller remains responsible for freeing it. The
/// returned result owns the PHP compound-assignment expression value.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_compound_assign_value_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    op: u8,
    value: NativeValueHandle,
) -> NativeArrayLvalueResult {
    let Some(rhs) = (unsafe { value.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            "array lvalue compound assignment value materialization produced a null value handle",
        );
    };

    unsafe {
        native_array_lvalue_owner_read_modify_write_value_result(
            owner,
            segments,
            segment_count,
            "array lvalue compound assignment needs undefined-offset warning recovery before missing slots can be written",
            "array lvalue compound assignment read produced a null value handle",
            |current_value| {
                let expression_value = native_array_lvalue_compound_value(current_value, op, rhs)?;
                Ok(NativeArrayLvalueWriteBack {
                    write_value: expression_value.clone(),
                    expression_value,
                })
            },
        )
    }
}

/// # Safety
///
/// The owner handle and each key handle inside `segments` must be null or
/// handles previously returned by the runtime ABI and not yet freed. `segments`
/// must be null when `segment_count` is zero, or point to `segment_count`
/// initialized path segments. The returned result owns the PHP
/// increment/decrement expression value selected by `position`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_increment_decrement_value_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    op: u8,
    position: u8,
) -> NativeArrayLvalueResult {
    if !matches!(
        op,
        NATIVE_ARRAY_LVALUE_INCREMENT | NATIVE_ARRAY_LVALUE_DECREMENT
    ) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!("array lvalue increment/decrement operation tag {op} is not supported"),
        );
    }
    if !matches!(
        position,
        NATIVE_ARRAY_LVALUE_POSITION_PRE | NATIVE_ARRAY_LVALUE_POSITION_POST
    ) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!("array lvalue increment/decrement position tag {position} is not supported"),
        );
    }

    unsafe {
        native_array_lvalue_owner_read_modify_write_value_result(
            owner,
            segments,
            segment_count,
            "array lvalue increment/decrement needs undefined-offset warning recovery before missing slots can be written",
            "array lvalue increment/decrement read produced a null value handle",
            |current_value| {
                let previous_value = current_value.clone();
                let updated_value =
                    native_array_lvalue_increment_decrement_value(current_value, op)?;
                let expression_value = match position {
                    NATIVE_ARRAY_LVALUE_POSITION_PRE => updated_value.clone(),
                    NATIVE_ARRAY_LVALUE_POSITION_POST => previous_value,
                    _ => unreachable!("position tag was validated before mutation"),
                };
                Ok(NativeArrayLvalueWriteBack {
                    write_value: updated_value,
                    expression_value,
                })
            },
        )
    }
}

