/// The owner handle and each key handle inside `segments` must be null or
/// handles previously returned by the runtime ABI and not yet freed.
/// `segments` must be null when `segment_count` is zero, or point to
/// `segment_count` initialized path segments. Value-slot and reference-slot
/// null/false roots are reported as a null value so generated C can preserve
/// null-coalescing assignment RHS laziness without classifying them as invalid
/// array reads.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_null_coalesce_read_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
) -> NativeArrayLvalueResult {
    if owner.tag == NATIVE_ARRAY_LVALUE_OWNER_VALUE_SLOT {
        let Some(root) = (unsafe { native_array_lvalue_slot_ref(owner.value_slot) }) else {
            return NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                "array lvalue owner value slot is null",
            );
        };
        if matches!(root, Value::Null | Value::Bool(false)) {
            if let Err(result) = unsafe { native_array_path_from_segments(segments, segment_count) }
            {
                return result;
            }
            return NativeArrayLvalueResult::value(Value::Null);
        }
    }
    if owner.tag == NATIVE_ARRAY_LVALUE_OWNER_REFERENCE_SLOT {
        let Some(reference) = (unsafe { owner.reference.as_ref() }) else {
            return NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                "array lvalue owner reference slot is null",
            );
        };
        if matches!(reference.read_value(), Value::Null | Value::Bool(false)) {
            if let Err(result) = unsafe { native_array_path_from_segments(segments, segment_count) }
            {
                return result;
            }
            return NativeArrayLvalueResult::value(Value::Null);
        }
    }

    unsafe { phpc_native_array_lvalue_owner_read_result(owner, segments, segment_count) }
}

/// # Safety
