unsafe fn native_value_array_lvalue_root_ref<'a>(
    root: NativeValueHandle,
) -> Result<&'a Value, NativeArrayLvalueResult> {
    if root.ptr.is_null() {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue root value handle is null",
        ));
    }

    Ok(unsafe { &*root.ptr })
}

unsafe fn native_value_array_lvalue_value_root_blocker_result(
    root: &Value,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    operation: NativeArrayLvalueValueRootOperation,
) -> NativeArrayLvalueResult {
    let _path = match unsafe { native_array_path_from_segments(segments, segment_count) } {
        Ok(path) => path,
        Err(result) => return result,
    };

    match root {
        Value::Array(_) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_COW_REFERENCE_BLOCKED,
            format!(
                "array lvalue {} through a value root needs owner-slot materialization with copy-on-write and reference aliasing",
                operation.label()
            ),
        ),
        other => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!("cannot use {} as array lvalue root", other.type_name()),
        ),
    }
}

