fn native_array_reference_lvalue_value_slot(
    root: &mut Value,
    path: &[NativeArrayPathElement],
) -> NativeArrayReferenceResult {
    match root {
        Value::Array(array) => native_array_reference_lvalue_path(array, path),
        Value::Null | Value::Bool(false) => {
            let mut array = PhpArray::new();
            let result = native_array_reference_lvalue_path(&mut array, path);
            if result.succeeded() {
                *root = Value::Array(array);
            }
            result
        }
        other => NativeArrayReferenceResult::from_lvalue_result(
            native_array_lvalue_owner_slot_invalid_root_result(other),
        ),
    }
}

