unsafe fn native_array_string_key(handle: NativeStringHandle) -> Option<ArrayKey> {
    let string = unsafe { handle.as_ref() }?;
    Some(ArrayKey::string_bytes(string.bytes.clone()))
}

unsafe fn native_array_key_arg(key: NativeArrayKeyArg) -> Option<ArrayKey> {
    match key {
        NativeArrayKeyArg::Int(value) => Some(ArrayKey::Int(value)),
        NativeArrayKeyArg::String(handle) => unsafe { native_array_string_key(handle) },
    }
}

unsafe fn native_array_write_value(
    mut handle: NativeArrayHandle,
    key: NativeArrayKeyArg,
    value: Value,
) -> bool {
    let (Some(array), Some(key)) = (unsafe { handle.as_mut() }, unsafe {
        native_array_key_arg(key)
    }) else {
        return false;
    };

    array.value.insert(key, value);
    true
}

unsafe fn native_array_key_exists(handle: NativeArrayHandle, key: NativeArrayKeyArg) -> bool {
    let Some(key) = (unsafe { native_array_key_arg(key) }) else {
        return false;
    };

    unsafe { handle.as_ref() }.is_some_and(|array| array.value.get(key).is_some())
}

unsafe fn native_array_isset(handle: NativeArrayHandle, key: NativeArrayKeyArg) -> bool {
    let Some(key) = (unsafe { native_array_key_arg(key) }) else {
        return false;
    };

    unsafe { handle.as_ref() }
        .and_then(|array| array.value.get(key))
        .is_some_and(|value| !matches!(value, Value::Null))
}

unsafe fn native_array_unset(mut handle: NativeArrayHandle, key: NativeArrayKeyArg) -> bool {
    let (Some(array), Some(key)) = (unsafe { handle.as_mut() }, unsafe {
        native_array_key_arg(key)
    }) else {
        return false;
    };

    array.value.remove(key);
    true
}

unsafe fn native_array_read(
    handle: NativeArrayHandle,
    key: NativeArrayKeyArg,
) -> NativeValueHandle {
    let Some(key) = (unsafe { native_array_key_arg(key) }) else {
        return NativeValueHandle::null();
    };

    unsafe { handle.as_ref() }
        .and_then(|array| array.value.get_cloned(key))
        .map(NativeValueHandle::from_value)
        .unwrap_or_else(NativeValueHandle::null)
}

unsafe fn native_array_path_from_segments(
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
) -> Result<Vec<NativeArrayPathElement>, NativeArrayLvalueResult> {
    if segment_count == 0 {
        return Ok(Vec::new());
    }
    if segments.is_null() {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue path pointer is null with nonzero length",
        ));
    }

    let segments = unsafe { std::slice::from_raw_parts(segments, segment_count) };
    let mut path = Vec::with_capacity(segment_count);
    for segment in segments {
        match segment.tag {
            NATIVE_ARRAY_PATH_KEY => {
                let Some(key) = (unsafe { segment.key.as_ref() }) else {
                    return Err(NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        "array lvalue key segment has a null value handle",
                    ));
                };
                let key = native_array_key_from_value_result(key)?;
                path.push(NativeArrayPathElement::Key(key));
            }
            NATIVE_ARRAY_PATH_APPEND => path.push(NativeArrayPathElement::Append),
            _ => {
                return Err(NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    format!(
                        "array lvalue path segment tag {} is not supported",
                        segment.tag
                    ),
                ))
            }
        }
    }
    Ok(path)
}

fn native_array_key_from_value_result(value: &Value) -> Result<ArrayKey, NativeArrayLvalueResult> {
    native_array_lvalue_key_from_value(value).map_err(|error| {
        NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_INVALID_KEY, error.message())
    })
}

fn native_array_lvalue_compound_value(
    current: &Value,
    op: u8,
    rhs: &Value,
) -> RuntimeResult<Value> {
    let Some(binary_op) = native_array_lvalue_compound_binary_op(op) else {
        return Err(RuntimeError::invalid_arithmetic(
            ArithmeticOp::Add,
            format!("array lvalue compound assignment operation tag {op} is not supported"),
        ));
    };

    native_value_binary_value(current, binary_op, rhs)
}

fn native_array_lvalue_compound_binary_op(op: u8) -> Option<u8> {
    match op {
        NATIVE_ARRAY_LVALUE_COMPOUND_ADD => Some(NATIVE_VALUE_BINARY_ADD),
        NATIVE_ARRAY_LVALUE_COMPOUND_SUB => Some(NATIVE_VALUE_BINARY_SUB),
        NATIVE_ARRAY_LVALUE_COMPOUND_MUL => Some(NATIVE_VALUE_BINARY_MUL),
        NATIVE_ARRAY_LVALUE_COMPOUND_DIV => Some(NATIVE_VALUE_BINARY_DIV),
        NATIVE_ARRAY_LVALUE_COMPOUND_MOD => Some(NATIVE_VALUE_BINARY_MOD),
        NATIVE_ARRAY_LVALUE_COMPOUND_CONCAT => Some(NATIVE_VALUE_BINARY_CONCAT),
        NATIVE_ARRAY_LVALUE_COMPOUND_BITWISE_AND => Some(NATIVE_VALUE_BINARY_BITWISE_AND),
        NATIVE_ARRAY_LVALUE_COMPOUND_BITWISE_OR => Some(NATIVE_VALUE_BINARY_BITWISE_OR),
        NATIVE_ARRAY_LVALUE_COMPOUND_BITWISE_XOR => Some(NATIVE_VALUE_BINARY_BITWISE_XOR),
        NATIVE_ARRAY_LVALUE_COMPOUND_SHIFT_LEFT => Some(NATIVE_VALUE_BINARY_SHIFT_LEFT),
        NATIVE_ARRAY_LVALUE_COMPOUND_SHIFT_RIGHT => Some(NATIVE_VALUE_BINARY_SHIFT_RIGHT),
        _ => None,
    }
}

fn native_array_lvalue_increment_decrement_value(current: &Value, op: u8) -> RuntimeResult<Value> {
    match (current, op) {
        (Value::Int(value), NATIVE_ARRAY_LVALUE_INCREMENT) => Ok(Value::Int(value.wrapping_add(1))),
        (Value::Int(value), NATIVE_ARRAY_LVALUE_DECREMENT) => Ok(Value::Int(value.wrapping_sub(1))),
        (Value::Float(value), NATIVE_ARRAY_LVALUE_INCREMENT) => Ok(Value::Float(value + 1.0)),
        (Value::Float(value), NATIVE_ARRAY_LVALUE_DECREMENT) => Ok(Value::Float(value - 1.0)),
        (_, other)
            if other != NATIVE_ARRAY_LVALUE_INCREMENT && other != NATIVE_ARRAY_LVALUE_DECREMENT =>
        {
            Err(RuntimeError::unsupported_call(
                "array lvalue increment/decrement",
                format!("operation tag {other} is not supported"),
            ))
        }
        (other, _) => Err(RuntimeError::unsupported_call(
            "array lvalue increment/decrement",
            format!(
                "only int and float slots are implemented, got {}",
                other.type_name()
            ),
        )),
    }
}

fn native_array_lvalue_key_from_value(value: &Value) -> RuntimeResult<ArrayKey> {
    match value {
        Value::Null => Ok(ArrayKey::String(String::new())),
        Value::Bool(false) => Ok(ArrayKey::Int(0)),
        Value::Bool(true) => Ok(ArrayKey::Int(1)),
        Value::Int(value) => Ok(ArrayKey::Int(*value)),
        Value::Float(value)
            if value.is_finite()
                && value.fract() == 0.0
                && *value >= i64::MIN as f64
                && *value < i64::MAX as f64 =>
        {
            Ok(ArrayKey::Int(*value as i64))
        }
        Value::Float(_) => Err(RuntimeError::invalid_array_key(
            "lossy or non-finite float keys are not supported; only null, bool, int, string, and integral finite float keys are implemented",
        )),
        Value::String(value) => Ok(ArrayKey::string(value.clone())),
        Value::BinaryString(value) => Ok(ArrayKey::string_bytes(value.clone())),
        other => Err(RuntimeError::invalid_array_key(format!(
            "{} keys are not supported; only null, bool, int, string, and integral finite float keys are implemented",
            other.type_name()
        ))),
    }
}

fn native_array_key_path(path: &[NativeArrayPathElement]) -> Option<Vec<ArrayKey>> {
    if path.is_empty() {
        return None;
    }

    path.iter()
        .map(|element| match element {
            NativeArrayPathElement::Key(key) => Some(key.clone()),
            NativeArrayPathElement::Append => None,
        })
        .collect()
}

fn native_array_lvalue_owner_slot_invalid_root_result(root: &Value) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_INVALID_ROOT,
        format!("cannot use {} as array lvalue owner slot", root.type_name()),
    )
}

fn native_array_lvalue_reference_slot_null_result() -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_INVALID_ROOT,
        "array lvalue owner reference slot is null",
    )
}

fn native_array_lvalue_reference_slot_invalid_root_result(root: &Value) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_INVALID_ROOT,
        format!(
            "cannot use {} as array lvalue reference owner slot",
            root.type_name()
        ),
    )
}

unsafe fn native_array_lvalue_slot_ref<'a>(
    value_slot: *mut NativeValueHandle,
) -> Option<&'a Value> {
    if value_slot.is_null() {
        return None;
    }

    unsafe { (*value_slot).as_ref() }
}

unsafe fn native_array_lvalue_slot_mut<'a>(
    value_slot: *mut NativeValueHandle,
) -> Option<&'a mut Value> {
    if value_slot.is_null() {
        return None;
    }

    unsafe { (*value_slot).as_mut() }
}

unsafe fn native_array_lvalue_reference_cell(
    reference: NativeReferenceHandle,
) -> Result<PhpReferenceCell, NativeArrayLvalueResult> {
    let Some(reference) = (unsafe { reference.as_ref() }) else {
        return Err(native_array_lvalue_reference_slot_null_result());
    };

    Ok(reference.cell.clone())
}

fn native_array_write_lvalue_value_slot(
    root: &mut Value,
    path: &[NativeArrayPathElement],
    value: Value,
) -> NativeArrayLvalueResult {
    match root {
        Value::Array(array) => native_array_write_lvalue_path(array, path, value),
        Value::Null | Value::Bool(false) => {
            let mut array = PhpArray::new();
            let result = native_array_write_lvalue_path(&mut array, path, value);
            if result.succeeded() {
                *root = Value::Array(array);
            }
            result
        }
        other => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!(
                "cannot use {} as array lvalue owner slot",
                other.type_name()
            ),
        ),
    }
}

fn native_array_bind_reference_lvalue_value_slot(
    root: &mut Value,
    path: &[NativeArrayPathElement],
    reference: PhpReferenceCell,
) -> NativeArrayLvalueResult {
    match root {
        Value::Array(array) => native_array_bind_reference_lvalue_path(array, path, reference),
        Value::Null | Value::Bool(false) => {
            let mut array = PhpArray::new();
            let result = native_array_bind_reference_lvalue_path(&mut array, path, reference);
            if result.succeeded() {
                *root = Value::Array(array);
            }
            result
        }
        other => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!(
                "cannot use {} as array lvalue owner slot",
                other.type_name()
            ),
        ),
    }
}

fn native_array_unset_lvalue_reference_slot(
    root: &mut Value,
    path: &[NativeArrayPathElement],
) -> NativeArrayLvalueResult {
    match root {
        Value::Array(array) => native_array_unset_lvalue_path(array, path),
        Value::Null | Value::Bool(false) => NativeArrayLvalueResult::ok(),
        other => native_array_lvalue_reference_slot_invalid_root_result(other),
    }
}

fn native_array_reference_lvalue_path(
    array: &mut PhpArray,
    path: &[NativeArrayPathElement],
) -> NativeArrayReferenceResult {
    let Some((segment, rest)) = path.split_first() else {
        let reference = PhpReferenceCell::new(Value::Null);
        return match array.append_reference(reference.clone()) {
            Ok(_) => NativeArrayReferenceResult::reference(reference),
            Err(error) => NativeArrayReferenceResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_KEY,
                error.message(),
            ),
        };
    };

    match segment {
        NativeArrayPathElement::Key(key) if rest.is_empty() => {
            if array.get_slot(key.clone()).is_none() {
                array.insert(key.clone(), Value::Null);
            }
            let Some(slot) = array.get_slot_mut(key.clone()) else {
                return NativeArrayReferenceResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    "array lvalue reference slot disappeared during materialization",
                );
            };
            NativeArrayReferenceResult::reference(slot.promote_to_reference_cell())
        }
        NativeArrayPathElement::Key(key) => {
            let mut child = match array.get_cloned(key.clone()) {
                Some(Value::Array(child)) => child,
                Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
                Some(other) => {
                    return NativeArrayReferenceResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_SCALAR_INTERMEDIATE,
                        format!("cannot create reference offset on {}", other.type_name()),
                    );
                }
            };

            let result = native_array_reference_lvalue_path(&mut child, rest);
            if result.succeeded() {
                array.insert(key.clone(), Value::Array(child));
            }
            result
        }
        NativeArrayPathElement::Append if rest.is_empty() => {
            let reference = PhpReferenceCell::new(Value::Null);
            match array.append_reference(reference.clone()) {
                Ok(_) => NativeArrayReferenceResult::reference(reference),
                Err(error) => NativeArrayReferenceResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    error.message(),
                ),
            }
        }
        NativeArrayPathElement::Append => {
            let mut child = PhpArray::new();
            let result = native_array_reference_lvalue_path(&mut child, rest);
            if !result.succeeded() {
                return result;
            }

            match array.append(Value::Array(child)) {
                Ok(_) => result,
                Err(error) => {
                    unsafe { phpc_native_array_reference_result_free(result) };
                    NativeArrayReferenceResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        error.message(),
                    )
                }
            }
        }
    }
}

fn native_array_bind_reference_lvalue_path(
    array: &mut PhpArray,
    path: &[NativeArrayPathElement],
    reference: PhpReferenceCell,
) -> NativeArrayLvalueResult {
    let Some((segment, rest)) = path.split_first() else {
        return match array.append_reference(reference) {
            Ok(_) => NativeArrayLvalueResult::ok(),
            Err(error) => NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_KEY,
                error.message(),
            ),
        };
    };

    match segment {
        NativeArrayPathElement::Key(key) if rest.is_empty() => {
            array.insert_reference(key.clone(), reference);
            NativeArrayLvalueResult::ok()
        }
        NativeArrayPathElement::Key(key) => {
            let mut child = match array.get_cloned(key.clone()) {
                Some(Value::Array(child)) => child,
                Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
                Some(other) => {
                    return NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_SCALAR_INTERMEDIATE,
                        format!("cannot bind reference offset on {}", other.type_name()),
                    );
                }
            };

            let result = native_array_bind_reference_lvalue_path(&mut child, rest, reference);
            if result.succeeded() {
                array.insert(key.clone(), Value::Array(child));
            }
            result
        }
        NativeArrayPathElement::Append if rest.is_empty() => {
            match array.append_reference(reference) {
                Ok(_) => NativeArrayLvalueResult::ok(),
                Err(error) => NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    error.message(),
                ),
            }
        }
        NativeArrayPathElement::Append => {
            let mut child = PhpArray::new();
            let result = native_array_bind_reference_lvalue_path(&mut child, rest, reference);
            if !result.succeeded() {
                return result;
            }

            match array.append(Value::Array(child)) {
                Ok(_) => NativeArrayLvalueResult::ok(),
                Err(error) => NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    error.message(),
                ),
            }
        }
    }
}

fn native_array_write_lvalue_path(
    array: &mut PhpArray,
    path: &[NativeArrayPathElement],
    value: Value,
) -> NativeArrayLvalueResult {
    let Some((segment, rest)) = path.split_first() else {
        return match array.append(value) {
            Ok(_) => NativeArrayLvalueResult::ok(),
            Err(error) => NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_KEY,
                error.message(),
            ),
        };
    };

    match segment {
        NativeArrayPathElement::Key(key) if rest.is_empty() => {
            array.insert(key.clone(), value);
            NativeArrayLvalueResult::ok()
        }
        NativeArrayPathElement::Key(key) => {
            let mut child = match array.get_cloned(key.clone()) {
                Some(Value::Array(child)) => child,
                Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
                Some(other) => {
                    return NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_SCALAR_INTERMEDIATE,
                        format!("cannot write offset on {}", other.type_name()),
                    );
                }
            };

            let result = native_array_write_lvalue_path(&mut child, rest, value);
            if !result.succeeded() {
                return result;
            }
            array.insert(key.clone(), Value::Array(child));
            NativeArrayLvalueResult::ok()
        }
        NativeArrayPathElement::Append if rest.is_empty() => match array.append(value) {
            Ok(_) => NativeArrayLvalueResult::ok(),
            Err(error) => NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_KEY,
                error.message(),
            ),
        },
        NativeArrayPathElement::Append => {
            let mut child = PhpArray::new();
            let result = native_array_write_lvalue_path(&mut child, rest, value);
            if !result.succeeded() {
                return result;
            }
            match array.append(Value::Array(child)) {
                Ok(_) => NativeArrayLvalueResult::ok(),
                Err(error) => NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    error.message(),
                ),
            }
        }
    }
}

fn native_array_read_lvalue_path(
    array: &PhpArray,
    path: &[NativeArrayPathElement],
) -> NativeArrayLvalueResult {
    let Some((segment, rest)) = path.split_first() else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue read path must contain at least one key segment",
        );
    };

    let NativeArrayPathElement::Key(key) = segment else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue read path cannot contain append segments",
        );
    };

    let Some(value) = array.get_cloned(key.clone()) else {
        return NativeArrayLvalueResult::missing();
    };
    if rest.is_empty() {
        return NativeArrayLvalueResult::value(value);
    }

    match value {
        Value::Array(child) => native_array_read_lvalue_path(&child, rest),
        other => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_SCALAR_INTERMEDIATE,
            format!("cannot read offset on {}", other.type_name()),
        ),
    }
}

fn native_array_foreach_iterable_path_result(
    array: &PhpArray,
    path: &[NativeArrayPathElement],
) -> NativeArrayLvalueResult {
    if path.is_empty() {
        return NativeArrayLvalueResult::value(Value::Array(array.clone()));
    }

    match native_array_foreach_iterable_path_value(array, path) {
        Ok(Some(value)) => native_value_foreach_iterable_value_result(value),
        Ok(None) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            RuntimeError::invalid_foreach("missing array lvalue iterable").message(),
        ),
        Err(result) => result,
    }
}

fn native_value_foreach_iterable_path_result(
    value: &Value,
    path: &[NativeArrayPathElement],
) -> NativeArrayLvalueResult {
    let Value::Array(array) = value else {
        return native_value_foreach_iterable_value_result(value.clone());
    };

    native_array_foreach_iterable_path_result(array, path)
}

fn native_value_foreach_iterable_value_result(value: Value) -> NativeArrayLvalueResult {
    match value {
        Value::Array(_) => NativeArrayLvalueResult::value(value),
        other => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            RuntimeError::invalid_foreach(format!(
                "cannot iterate {} array lvalue iterable",
                other.type_name()
            ))
            .message(),
        ),
    }
}

fn native_array_foreach_iterable_path_value(
    array: &PhpArray,
    path: &[NativeArrayPathElement],
) -> Result<Option<Value>, NativeArrayLvalueResult> {
    let Some((segment, rest)) = path.split_first() else {
        return Ok(Some(Value::Array(array.clone())));
    };

    let NativeArrayPathElement::Key(key) = segment else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array foreach iterable path cannot contain append segments",
        ));
    };

    let Some(value) = array.get_cloned(key.clone()) else {
        return Ok(None);
    };
    if rest.is_empty() {
        return Ok(Some(value));
    }

    match value {
        Value::Array(child) => native_array_foreach_iterable_path_value(&child, rest),
        other => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_SCALAR_INTERMEDIATE,
            format!(
                "cannot iterate nested foreach offset on {}",
                other.type_name()
            ),
        )),
    }
}

fn native_array_foreach_value_reference_path_result(
    array: &mut PhpArray,
    path: &[NativeArrayPathElement],
    index: usize,
) -> NativeArrayReferenceResult {
    let Some((segment, rest)) = path.split_first() else {
        return native_array_foreach_value_reference_at_index(array, index);
    };

    let NativeArrayPathElement::Key(key) = segment else {
        return NativeArrayReferenceResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array by-reference foreach iterable path cannot contain append segments",
        );
    };

    let Some(slot) = array.get_slot_mut(key.clone()) else {
        return NativeArrayReferenceResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            RuntimeError::invalid_foreach("missing array lvalue iterable").message(),
        );
    };

    let mut value = slot.value_cloned();
    let result = native_value_foreach_value_reference_path_result(&mut value, rest, index);
    if result.succeeded() {
        slot.set_value(value);
    }
    result
}

fn native_value_foreach_value_reference_path_result(
    value: &mut Value,
    path: &[NativeArrayPathElement],
    index: usize,
) -> NativeArrayReferenceResult {
    let Value::Array(array) = value else {
        let message = if path.is_empty() {
            RuntimeError::invalid_foreach(format!(
                "cannot iterate {} array lvalue iterable by reference",
                value.type_name()
            ))
            .message()
            .to_string()
        } else {
            format!(
                "cannot iterate nested by-reference foreach offset on {}",
                value.type_name()
            )
        };
        return NativeArrayReferenceResult::diagnostic(NATIVE_ARRAY_LVALUE_INVALID_ROOT, message);
    };

    native_array_foreach_value_reference_path_result(array, path, index)
}

fn native_array_foreach_value_reference_at_index(
    array: &mut PhpArray,
    index: usize,
) -> NativeArrayReferenceResult {
    let Some(entry) = array.entries.get_mut(index) else {
        return NativeArrayReferenceResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            format!("array foreach reference index {index} is out of range"),
        );
    };

    NativeArrayReferenceResult::reference(entry.slot_mut().promote_to_reference_cell())
}

fn native_array_unset_lvalue_path(
    array: &mut PhpArray,
    path: &[NativeArrayPathElement],
) -> NativeArrayLvalueResult {
    let Some(keys) = native_array_key_path(path) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue unset path must contain key segments only",
        );
    };

    native_array_unset_key_path(array, &keys);
    NativeArrayLvalueResult::ok()
}

fn native_array_unset_key_path(array: &mut PhpArray, keys: &[ArrayKey]) -> bool {
    let Some((key, rest)) = keys.split_first() else {
        return false;
    };

    if rest.is_empty() {
        array.remove(key.clone());
        return true;
    }

    let Some(Value::Array(mut child)) = array.get_cloned(key.clone()) else {
        return true;
    };
    let removed = native_array_unset_key_path(&mut child, rest);
    array.insert(key.clone(), Value::Array(child));
    removed
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. Passing any other pointer is undefined behavior.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_free(handle: NativeArrayHandle) {
    if handle.ptr.is_null() {
        return;
    }

    drop(unsafe { Box::from_raw(handle.ptr) });
}

/// # Safety
///
/// `handle` must be null or a key snapshot handle previously returned by the
/// runtime ABI and not yet freed. Passing any other pointer is undefined
/// behavior.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_key_snapshot_free(handle: NativeArrayKeySnapshotHandle) {
    if handle.ptr.is_null() {
        return;
    }

    drop(unsafe { Box::from_raw(handle.ptr) });
}

/// # Safety
///
/// `handle` must be null or an entry snapshot handle previously returned by
/// the runtime ABI and not yet freed. Passing any other pointer is undefined
/// behavior.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_entry_snapshot_free(
    handle: NativeArrayEntrySnapshotHandle,
) {
    if handle.ptr.is_null() {
        return;
    }

    drop(unsafe { Box::from_raw(handle.ptr) });
}

#[no_mangle]
pub extern "C" fn phpc_native_symbol_table_null() -> NativeSymbolTableHandle {
    NativeSymbolTableHandle::null()
}

#[no_mangle]
pub extern "C" fn phpc_native_symbol_table_new() -> NativeSymbolTableHandle {
    NativeSymbolTableHandle::new()
}

#[no_mangle]
pub extern "C" fn phpc_native_symbol_table_is_null(handle: NativeSymbolTableHandle) -> bool {
    handle.is_null()
}

/// # Safety
///
/// `handle` must be null or a symbol-table handle previously returned by the
/// runtime ABI and not yet freed. `name` must either be null with `name_len == 0`,
/// or point to at least `name_len` readable bytes. The returned value handle
/// owns a clone of the variable value. Missing variables return an owned PHP
/// null value. Null table handles and invalid names return a null handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_symbol_table_read(
    handle: NativeSymbolTableHandle,
    name: *const u8,
    name_len: usize,
) -> NativeValueHandle {
    let (Some(table), Some(name)) = (unsafe { handle.as_ref() }, unsafe {
        native_symbol_name_from_bytes(name, name_len)
    }) else {
        return NativeValueHandle::null();
    };

    NativeValueHandle::from_value(table.variables.get(&name).cloned().unwrap_or(Value::Null))
}

/// # Safety
///
/// `handle` must be null or a symbol-table handle previously returned by the
/// runtime ABI and not yet freed. `name` must either be null with `name_len == 0`,
/// or point to at least `name_len` readable bytes. `value` must be null or a
/// value handle previously returned by the runtime ABI and not yet freed. The
/// symbol table owns a clone of `value`; ownership of `value` remains with the
/// caller. The helper returns `false` for null table handles, invalid names, or
/// null value handles.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_symbol_table_write(
    mut handle: NativeSymbolTableHandle,
    name: *const u8,
    name_len: usize,
    value: NativeValueHandle,
) -> bool {
    let (Some(table), Some(name), Some(value)) = (
        unsafe { handle.as_mut() },
        unsafe { native_symbol_name_from_bytes(name, name_len) },
        unsafe { value.as_ref() },
    ) else {
        return false;
    };

    table.variables.insert(name, value.clone());
    true
}

/// # Safety
///
/// `handle` must be null or a symbol-table handle previously returned by the
/// runtime ABI and not yet freed. `name` must either be null with `name_len == 0`,
/// or point to at least `name_len` readable bytes. The helper returns true only
/// when the variable exists and its value is not null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_symbol_table_isset(
    handle: NativeSymbolTableHandle,
    name: *const u8,
    name_len: usize,
) -> bool {
    let (Some(table), Some(name)) = (unsafe { handle.as_ref() }, unsafe {
        native_symbol_name_from_bytes(name, name_len)
    }) else {
        return false;
    };

    table
        .variables
        .get(&name)
        .is_some_and(|value| !matches!(value, Value::Null))
}

/// # Safety
///
/// `handle` must be null or a symbol-table handle previously returned by the
/// runtime ABI and not yet freed. `name` must either be null with `name_len == 0`,
/// or point to at least `name_len` readable bytes. Missing variables and invalid
/// inputs are empty, matching PHP's non-diagnostic `empty($local)` behavior.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_symbol_table_empty(
    handle: NativeSymbolTableHandle,
    name: *const u8,
    name_len: usize,
) -> bool {
    let (Some(table), Some(name)) = (unsafe { handle.as_ref() }, unsafe {
        native_symbol_name_from_bytes(name, name_len)
    }) else {
        return true;
    };

    table
        .variables
        .get(&name)
        .map(|value| !value.is_truthy())
        .unwrap_or(true)
}

/// # Safety
///
/// `handle` must be null or a symbol-table handle previously returned by the
/// runtime ABI and not yet freed. `name` must either be null with `name_len == 0`,
/// or point to at least `name_len` readable bytes. Missing variables are a
/// successful no-op; null handles and invalid names return false.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_symbol_table_unset(
    mut handle: NativeSymbolTableHandle,
    name: *const u8,
    name_len: usize,
) -> bool {
    let (Some(table), Some(name)) = (unsafe { handle.as_mut() }, unsafe {
        native_symbol_name_from_bytes(name, name_len)
    }) else {
        return false;
    };

    table.variables.remove(&name);
    true
}

/// # Safety
///
/// `handle` must be null or a symbol-table handle previously returned by the
/// runtime ABI and not yet freed. Passing any other pointer is undefined
/// behavior.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_symbol_table_free(handle: NativeSymbolTableHandle) {
    if handle.ptr.is_null() {
        return;
    }

    drop(unsafe { Box::from_raw(handle.ptr) });
}

unsafe fn native_symbol_name_from_bytes(name: *const u8, name_len: usize) -> Option<String> {
    if name_len == 0 {
        return Some(String::new());
    }
    if name.is_null() {
        return None;
    }

    let bytes = unsafe { std::slice::from_raw_parts(name, name_len) };
    std::str::from_utf8(bytes).ok().map(|name| name.to_string())
}

#[no_mangle]
pub extern "C" fn phpc_native_object_null() -> NativeObjectHandle {
    NativeObjectHandle::null()
}

#[no_mangle]
pub extern "C" fn phpc_native_object_is_null(handle: NativeObjectHandle) -> bool {
    handle.is_null()
}

/// # Safety
///
/// `class_name` must either be null with `len == 0`, or point to at least
/// `len` readable bytes. Null, empty, or non-UTF-8 names return a null handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_metadata_from_name(
    class_name: *const u8,
    len: usize,
) -> NativeClassMetadataHandle {
    if class_name.is_null() || len == 0 {
        return NativeClassMetadataHandle::null();
    }

    let bytes = unsafe { std::slice::from_raw_parts(class_name, len) };
    let Ok(name) = String::from_utf8(bytes.to_vec()) else {
        return NativeClassMetadataHandle::null();
    };

    NativeClassMetadataHandle::from_name(name)
}

/// # Safety
///
/// `class_name` must be null or a string handle previously returned by the
/// runtime ABI and not yet freed. Null or non-UTF-8 names return a null
/// handle. The returned class metadata handle owns a clone of the string name.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_metadata_from_string(
    class_name: NativeStringHandle,
) -> NativeClassMetadataHandle {
    let Some(class_name) = (unsafe { class_name.as_ref() }) else {
        return NativeClassMetadataHandle::null();
    };
    let Ok(name) = String::from_utf8(class_name.bytes.clone()) else {
        return NativeClassMetadataHandle::null();
    };
    if name.is_empty() {
        return NativeClassMetadataHandle::null();
    }

    NativeClassMetadataHandle::from_name(name)
}

