#[no_mangle]
pub unsafe extern "C" fn phpc_native_string_bytes(handle: NativeStringHandle) -> *const u8 {
    let Some(string) = (unsafe { handle.as_ref() }) else {
        return ptr::null();
    };

    if string.bytes.is_empty() {
        ptr::null()
    } else {
        string.bytes.as_ptr()
    }
}

/// # Safety
///
/// `handle` must be null or a handle previously returned by the runtime ABI
/// and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_string_clone_bytes(
    handle: NativeStringHandle,
) -> NativeByteBuffer {
    unsafe { handle.as_ref() }
        .map(|string| NativeByteBuffer::from_vec(string.bytes.clone()))
        .unwrap_or_else(NativeByteBuffer::empty)
}

/// # Safety
///
/// `handle` must be null or a handle previously returned by the runtime ABI
/// and not yet freed. The returned value handle owns a cloned runtime
/// `Value::String` for valid UTF-8 bytes. Null handles and non-UTF-8 bytes
/// return a null value handle until diagnostics and binary string values have
/// native ABI coverage.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_from_string(
    handle: NativeStringHandle,
) -> NativeValueHandle {
    native_value_from_string(handle)
        .map(NativeValueHandle::from_value)
        .unwrap_or_else(|_| NativeValueHandle::null())
}

/// # Safety
///
/// `handle` must be null or a handle previously returned by the runtime ABI
/// and not yet freed. Valid UTF-8 bytes keep using `Value::String`; other PHP
/// string bytes use byte-preserving `Value::BinaryString`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_from_binary_string(
    handle: NativeStringHandle,
) -> NativeValueHandle {
    let Some(string) = (unsafe { handle.as_ref() }) else {
        return NativeValueHandle::null();
    };

    NativeValueHandle::from_value(value_from_php_string_bytes(string.bytes.clone()))
}

/// # Safety
///
/// `bytes` must either be null with `len == 0`, or point to at least `len`
/// readable bytes. Null non-empty inputs return a null value handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_binary_value_from_bytes(
    bytes: *const u8,
    len: usize,
) -> NativeValueHandle {
    let string = unsafe { phpc_native_binary_string_from_bytes(bytes, len) };
    if string.is_null() {
        return NativeValueHandle::null();
    }

    let value = unsafe { phpc_native_value_from_binary_string(string) };
    unsafe { phpc_native_string_free(string) };
    value
}

#[no_mangle]
pub extern "C" fn phpc_native_value_from_scalar(value: NativeScalarValue) -> NativeValueHandle {
    NativeValueHandle::from_value(value.to_value())
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. This helper covers the current native subset of PHP
/// termination semantics: integer values become the process status, and every
/// other value is emitted like an exit/die message with status 0. Shutdown
/// functions, destructors/finally ordering, output buffers, and SAPI handoff
/// are still outside this runtime ABI.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_termination_status_value(handle: NativeValueHandle) -> i32 {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return 255;
    };

    if let Value::Int(status) = value {
        return *status as i32;
    }

    let output = value.echo_bytes();
    if !output.is_empty() {
        let mut stdout = io::stdout();
        let _ = stdout.write_all(&output).and_then(|()| stdout.flush());
    }

    0
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned value handle owns a cloned PHP value and
/// must be released with `phpc_native_value_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_clone(handle: NativeValueHandle) -> NativeValueHandle {
    unsafe { native_value_clone_result(handle) }
        .map(NativeValueHandle::from_value)
        .unwrap_or_else(|_| NativeValueHandle::null())
}

unsafe fn native_value_clone_result(handle: NativeValueHandle) -> RuntimeResult<Value> {
    unsafe {
        native_value_handle_result(
            handle,
            || {
                RuntimeError::unsupported_call(
                    "native value clone",
                    "native value clone failed: value handle is null",
                )
            },
            |value| Ok(value.clone()),
        )
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_truthy(handle: NativeValueHandle) -> bool {
    unsafe { handle.as_ref() }
        .map(Value::is_truthy)
        .unwrap_or(false)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `diagnostic` may be null; when non-null, it must
/// point to writable storage for one `NativeDiagnosticHandle`. A null handle is
/// treated as an ABI failure and reported through the diagnostic handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_truthy_with_diagnostic(
    handle: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(value) = (unsafe { handle.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_string_conversion(
                        "native truthiness conversion failed: value handle is null",
                    )
                    .message(),
                );
            }
        }
        return false;
    };

    value.is_truthy()
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `diagnostic` may be null; when non-null, it must
/// point to writable storage for one `NativeDiagnosticHandle`. A null handle or
/// unsupported PHP value stores a diagnostic handle that the caller owns and
/// must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_to_int_with_diagnostic(
    handle: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> i64 {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(value) = (unsafe { handle.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_string_conversion(
                        "native integer argument conversion failed: value handle is null",
                    )
                    .message(),
                );
            }
        }
        return 0;
    };

    match php_value_to_int_argument(value) {
        Ok(value) => value,
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            0
        }
    }
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. Null handles are treated as PHP null so
/// generated consumers can feed missing lvalue reads through the same value
/// comparison boundary.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_strict_identity(
    left: NativeValueHandle,
    right: NativeValueHandle,
) -> bool {
    let null_left = Value::Null;
    let null_right = Value::Null;
    let left = unsafe { left.as_ref() }.unwrap_or(&null_left);
    let right = unsafe { right.as_ref() }.unwrap_or(&null_right);

    left.php_identical_checked(right).unwrap_or(false)
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are treated as PHP null so generated
/// consumers can compare optional value-result payloads with ABI scalars.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_strict_identity_scalar(
    value: NativeValueHandle,
    scalar: NativeScalarValue,
) -> bool {
    let null_value = Value::Null;
    let value = unsafe { value.as_ref() }.unwrap_or(&null_value);

    value
        .php_identical_checked(&scalar.to_value())
        .unwrap_or(false)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are treated as PHP null so optional
/// value-result payloads and missing lvalue reads share the same predicate
/// boundary as owned runtime values.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_type_predicate(
    handle: NativeValueHandle,
    predicate: u8,
) -> bool {
    let null_value = Value::Null;
    let value = unsafe { handle.as_ref() }.unwrap_or(&null_value);
    native_value_type_predicate(value, predicate).unwrap_or(false)
}

/// # Safety
///
/// `handle` must be a value handle previously returned by the runtime ABI and
/// not yet freed. `diagnostic` may be null; when non-null, it must point to
/// writable storage for one `NativeDiagnosticHandle`. On failure the helper
/// stores a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_type_predicate_with_diagnostic(
    handle: NativeValueHandle,
    predicate: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(value) = (unsafe { handle.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_string_conversion(
                        "native value type predicate failed: value handle is null",
                    )
                    .message(),
                );
            }
        }
        return false;
    };

    match native_value_type_predicate(value, predicate) {
        Some(result) => result,
        None => {
            if !diagnostic.is_null() {
                unsafe {
                    *diagnostic = NativeDiagnosticHandle::from_message(
                        RuntimeError::invalid_string_conversion(
                            "native value type predicate failed: unsupported predicate tag",
                        )
                        .message(),
                    );
                }
            }
            false
        }
    }
}

fn native_value_type_predicate(value: &Value, predicate: u8) -> Option<bool> {
    match predicate {
        NATIVE_VALUE_TYPE_IS_NULL => Some(matches!(value, Value::Null)),
        NATIVE_VALUE_TYPE_IS_BOOL => Some(matches!(value, Value::Bool(_))),
        NATIVE_VALUE_TYPE_IS_INT => Some(matches!(value, Value::Int(_))),
        NATIVE_VALUE_TYPE_IS_FLOAT => Some(matches!(value, Value::Float(_))),
        NATIVE_VALUE_TYPE_IS_STRING => {
            Some(matches!(value, Value::String(_) | Value::BinaryString(_)))
        }
        NATIVE_VALUE_TYPE_IS_ARRAY => Some(matches!(value, Value::Array(_))),
        NATIVE_VALUE_TYPE_IS_SCALAR => Some(value.is_scalar()),
        NATIVE_VALUE_TYPE_IS_NUMERIC => Some(value.is_numeric()),
        NATIVE_VALUE_TYPE_IS_COUNTABLE => Some(value.is_countable()),
        NATIVE_VALUE_TYPE_IS_ITERABLE => Some(value.is_iterable()),
        NATIVE_VALUE_TYPE_IS_OBJECT => Some(matches!(value, Value::Object(_) | Value::Closure(_))),
        _ => None,
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are treated as PHP null so optional
/// value-result payloads and missing lvalue reads share the same type-name
/// boundary as owned runtime values.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_type_name_result(
    handle: NativeValueHandle,
    kind: u8,
) -> NativeArrayLvalueResult {
    let null_value = Value::Null;
    let value = unsafe { handle.as_ref() }.unwrap_or(&null_value);
    let name = match native_value_type_name(value, kind) {
        Ok(name) => name,
        Err(message) => {
            return NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message)
        }
    };

    NativeArrayLvalueResult::value(Value::String(name.to_string()))
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned value handle owns the PHP string result
/// for `gettype()` when `debug` is false, or `get_debug_type()` otherwise. On
/// ABI failure or currently unsupported debug type families, the helper stores
/// a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_type_name_with_diagnostic(
    handle: NativeValueHandle,
    debug: bool,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(value) = (unsafe { handle.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_string_conversion(
                        "native value type name failed: value handle is null",
                    )
                    .message(),
                );
            }
        }
        return NativeValueHandle::null();
    };

    let kind = if debug {
        NATIVE_VALUE_TYPE_NAME_DEBUG
    } else {
        NATIVE_VALUE_TYPE_NAME_GETTYPE
    };
    match native_value_type_name(value, kind) {
        Ok(name) => NativeValueHandle::from_value(Value::String(name.to_string())),
        Err(message) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(message) };
            }
            NativeValueHandle::null()
        }
    }
}

fn native_value_type_name(value: &Value, kind: u8) -> Result<&'static str, String> {
    match kind {
        NATIVE_VALUE_TYPE_NAME_GETTYPE => Ok(value.gettype_name()),
        NATIVE_VALUE_TYPE_NAME_DEBUG => native_value_debug_type_name(value),
        _ => Err(format!(
            "native value type-name operation tag {kind} is not supported"
        )),
    }
}

fn native_value_debug_type_name(value: &Value) -> Result<&'static str, String> {
    match value {
        Value::Object(_) | Value::Closure(_) => Err(
            "native value get_debug_type rejects object debug names until native class metadata, closure names, object handles, copy-on-write/reference identity, cleanup ownership, and exact diagnostics exist"
                .to_string(),
        ),
        Value::Resource(_) => Err(
            "native value get_debug_type rejects resource debug names until native resource type names, resource lifecycle state, cleanup ownership, and exact diagnostics exist"
                .to_string(),
        ),
        _ => Ok(value.type_name()),
    }
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are treated as PHP null. The result
/// carries either an owned value handle or a diagnostic explaining the
/// unsupported semantic family.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_unary_result(
    value: NativeValueHandle,
    op: u8,
) -> NativeArrayLvalueResult {
    if !native_value_unary_op_is_supported(op) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            "native value unary operation tag is not supported",
        );
    }

    let null_value = Value::Null;
    let value = unsafe { value.as_ref() }.unwrap_or(&null_value);

    if let Some(message) = native_value_unary_blocker(value) {
        return NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message);
    }

    match native_value_unary_value(value, op) {
        Ok(value) => NativeArrayLvalueResult::value(value),
        Err(error) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native value unary operation rejected by runtime semantics: {}",
                error.message()
            ),
        ),
    }
}

fn native_value_unary_op_is_supported(op: u8) -> bool {
    matches!(
        op,
        NATIVE_VALUE_UNARY_NEGATE | NATIVE_VALUE_UNARY_BITWISE_NOT
    )
}

fn native_value_unary_value(value: &Value, op: u8) -> RuntimeResult<Value> {
    match op {
        NATIVE_VALUE_UNARY_NEGATE => value.php_negate(),
        NATIVE_VALUE_UNARY_BITWISE_NOT => value.php_bitwise_not(),
        _ => Err(RuntimeError::invalid_arithmetic(
            ArithmeticOp::Negate,
            format!("native value unary operation tag {op} is not supported"),
        )),
    }
}

fn native_value_unary_blocker(value: &Value) -> Option<String> {
    let unsupported = match value {
        Value::Array(_) => "arrays",
        Value::Object(_) | Value::Closure(_) => "objects or closures",
        Value::Resource(_) => "resources",
        _ => return None,
    };

    Some(format!(
        "native value unary operation rejects {unsupported} until the value-result unary boundary can model PHP array coercions, object/ArrayAccess coercion hooks, resource coercions, copy-on-write/reference identity, cleanup ownership, and exact diagnostics"
    ))
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. Null handles are treated as PHP null. The
/// result carries either an owned value handle or a diagnostic explaining the
/// unsupported semantic family.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_binary_result(
    left: NativeValueHandle,
    op: u8,
    right: NativeValueHandle,
) -> NativeArrayLvalueResult {
    if !native_value_binary_op_is_supported(op) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            "native value binary operation tag is not supported",
        );
    }

    let null_left = Value::Null;
    let null_right = Value::Null;
    let left = unsafe { left.as_ref() }.unwrap_or(&null_left);
    let right = unsafe { right.as_ref() }.unwrap_or(&null_right);

    if let Some(message) = native_value_binary_blocker(left, right) {
        return NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message);
    }

    match native_value_binary_value(left, op, right) {
        Ok(value) => NativeArrayLvalueResult::value(value),
        Err(error) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native value binary operation rejected by runtime semantics: {}",
                error.message()
            ),
        ),
    }
}

fn native_value_binary_op_is_supported(op: u8) -> bool {
    matches!(
        op,
        NATIVE_VALUE_BINARY_ADD
            | NATIVE_VALUE_BINARY_SUB
            | NATIVE_VALUE_BINARY_MUL
            | NATIVE_VALUE_BINARY_DIV
            | NATIVE_VALUE_BINARY_MOD
            | NATIVE_VALUE_BINARY_CONCAT
            | NATIVE_VALUE_BINARY_BITWISE_AND
            | NATIVE_VALUE_BINARY_BITWISE_OR
            | NATIVE_VALUE_BINARY_BITWISE_XOR
            | NATIVE_VALUE_BINARY_SHIFT_LEFT
            | NATIVE_VALUE_BINARY_SHIFT_RIGHT
    )
}

fn native_value_binary_value(left: &Value, op: u8, right: &Value) -> RuntimeResult<Value> {
    match op {
        NATIVE_VALUE_BINARY_ADD => left.php_add(right),
        NATIVE_VALUE_BINARY_SUB => left.php_sub(right),
        NATIVE_VALUE_BINARY_MUL => left.php_mul(right),
        NATIVE_VALUE_BINARY_DIV => left.php_div(right),
        NATIVE_VALUE_BINARY_MOD => left.php_mod(right),
        NATIVE_VALUE_BINARY_CONCAT => left.php_concat(right),
        NATIVE_VALUE_BINARY_BITWISE_AND => left.php_bitwise_and(right),
        NATIVE_VALUE_BINARY_BITWISE_OR => left.php_bitwise_or(right),
        NATIVE_VALUE_BINARY_BITWISE_XOR => left.php_bitwise_xor(right),
        NATIVE_VALUE_BINARY_SHIFT_LEFT => left.php_shift_left(right),
        NATIVE_VALUE_BINARY_SHIFT_RIGHT => left.php_shift_right(right),
        _ => Err(RuntimeError::invalid_arithmetic(
            ArithmeticOp::Add,
            format!("native value binary operation tag {op} is not supported"),
        )),
    }
}

fn native_value_binary_blocker(left: &Value, right: &Value) -> Option<String> {
    let unsupported = match (left, right) {
        (Value::Array(_), _) | (_, Value::Array(_)) => "arrays",
        (Value::Object(_), _)
        | (_, Value::Object(_))
        | (Value::Closure(_), _)
        | (_, Value::Closure(_)) => "objects or closures",
        (Value::Resource(_), _) | (_, Value::Resource(_)) => "resources",
        _ => return None,
    };

    Some(format!(
        "native value binary operation rejects {unsupported} until the value-result binary boundary can model PHP array union/arithmetic, array-to-string diagnostics, object/ArrayAccess coercion hooks, resource coercions, copy-on-write/reference identity, cleanup ownership, and exact diagnostics"
    ))
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. Null handles are treated as PHP null. The
/// result carries either a boolean value handle or a diagnostic explaining the
/// unsupported semantic family.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_compare_result(
    left: NativeValueHandle,
    op: u8,
    right: NativeValueHandle,
) -> NativeArrayLvalueResult {
    let Some(op) = native_value_comparison_op(op) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            "native value comparison operation tag is not supported",
        );
    };

    let null_left = Value::Null;
    let null_right = Value::Null;
    let left = unsafe { left.as_ref() }.unwrap_or(&null_left);
    let right = unsafe { right.as_ref() }.unwrap_or(&null_right);

    if let Some(message) = native_value_comparison_blocker(left, right) {
        return NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message);
    }

    match left.php_cmp_checked(right, op) {
        Ok(result) => NativeArrayLvalueResult::value(Value::Bool(result)),
        Err(error) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native value comparison rejected by runtime comparison semantics: {}",
                error.message()
            ),
        ),
    }
}

fn native_value_comparison_op(op: u8) -> Option<Comparison> {
    match op {
        NATIVE_VALUE_COMPARISON_EQ => Some(Comparison::Eq),
        NATIVE_VALUE_COMPARISON_NE => Some(Comparison::Ne),
        NATIVE_VALUE_COMPARISON_LT => Some(Comparison::Lt),
        NATIVE_VALUE_COMPARISON_LE => Some(Comparison::Le),
        NATIVE_VALUE_COMPARISON_GT => Some(Comparison::Gt),
        NATIVE_VALUE_COMPARISON_GE => Some(Comparison::Ge),
        _ => None,
    }
}

fn native_value_comparison_blocker(left: &Value, right: &Value) -> Option<String> {
    let unsupported = match (left, right) {
        (Value::Array(_), _) | (_, Value::Array(_)) => "arrays",
        (Value::Object(_), _)
        | (_, Value::Object(_))
        | (Value::Closure(_), _)
        | (_, Value::Closure(_)) => "objects or closures",
        (Value::Resource(_), _) | (_, Value::Resource(_)) => "resources",
        _ => return None,
    };

    Some(format!(
        "native value comparison rejects {unsupported} until the value-result comparison boundary can model PHP array ordering, object comparison hooks, resource ordering, reference identity, cleanup ownership, and exact diagnostics",
    ))
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are treated as PHP null. The result
/// carries either an owned value handle or a diagnostic explaining the
/// unsupported semantic family.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_cast_result(
    value: NativeValueHandle,
    op: u8,
) -> NativeArrayLvalueResult {
    if !native_value_cast_op_is_supported(op) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            "native value cast operation tag is not supported",
        );
    }

    let null_value = Value::Null;
    let value = unsafe { value.as_ref() }.unwrap_or(&null_value);

    if let Some(message) = native_value_cast_blocker(value, op) {
        return NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message);
    }

    match native_value_cast_value(value, op) {
        Ok(value) => NativeArrayLvalueResult::value(value),
        Err(error) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native value cast rejected by runtime cast semantics: {}",
                error.message()
            ),
        ),
    }
}

fn native_value_cast_op_is_supported(op: u8) -> bool {
    matches!(
        op,
        NATIVE_VALUE_CAST_STRING
            | NATIVE_VALUE_CAST_INT
            | NATIVE_VALUE_CAST_BOOL
            | NATIVE_VALUE_CAST_FLOAT
            | NATIVE_VALUE_CAST_ARRAY
    )
}

fn native_value_cast_value(value: &Value, op: u8) -> RuntimeResult<Value> {
    match op {
        NATIVE_VALUE_CAST_STRING => value.php_string_cast(),
        NATIVE_VALUE_CAST_INT => value.php_cast_int().map(Value::Int),
        NATIVE_VALUE_CAST_BOOL => Ok(Value::Bool(value.is_truthy())),
        NATIVE_VALUE_CAST_FLOAT => value.php_cast_float().map(Value::Float),
        NATIVE_VALUE_CAST_ARRAY => value.php_cast_array().map(Value::Array),
        _ => Err(RuntimeError::unsupported_call(
            "native value cast",
            format!("native value cast operation tag {op} is not supported"),
        )),
    }
}

fn native_value_cast_blocker(value: &Value, op: u8) -> Option<String> {
    if matches!(op, NATIVE_VALUE_CAST_BOOL) {
        return None;
    }

    let unsupported = match (op, value) {
        (NATIVE_VALUE_CAST_STRING, Value::Array(_)) => "array-to-string diagnostics",
        (NATIVE_VALUE_CAST_STRING, Value::Object(_) | Value::Closure(_)) => {
            "object __toString()/ArrayAccess coercion hooks"
        }
        (NATIVE_VALUE_CAST_STRING, Value::Resource(_)) => "resource-to-string diagnostics",
        (NATIVE_VALUE_CAST_INT | NATIVE_VALUE_CAST_FLOAT, Value::Array(_)) => {
            "array numeric cast diagnostics"
        }
        (NATIVE_VALUE_CAST_INT | NATIVE_VALUE_CAST_FLOAT, Value::Object(_) | Value::Closure(_)) => {
            "object numeric cast hooks"
        }
        (NATIVE_VALUE_CAST_INT | NATIVE_VALUE_CAST_FLOAT, Value::Resource(_)) => {
            "resource numeric casts"
        }
        (NATIVE_VALUE_CAST_ARRAY, Value::Object(_) | Value::Closure(_)) => {
            "object property materialization"
        }
        (NATIVE_VALUE_CAST_ARRAY, Value::Resource(_)) => "resource array casts",
        _ => return None,
    };

    Some(format!(
        "native value cast rejects {unsupported} until the value-result cast boundary can model PHP array/object/resource cast diagnostics, ArrayAccess/object hooks, copy-on-write/reference identity, cleanup ownership, and exact diagnostics"
    ))
}

