/// non-string values return zero.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_string_byte_len(handle: NativeValueHandle) -> usize {
    unsafe {
        native_value_string_bytes_result(handle, "native value string byte length", |bytes| {
            bytes.len()
        })
    }
    .unwrap_or(0)
}

/// # Safety
