unsafe fn native_value_text_string(
    handle: NativeValueHandle,
    surface: TextOnlySurface,
) -> RuntimeResult<String> {
    let bytes = unsafe { native_value_to_string_bytes(handle) }?;
    text_only_surface_str(&bytes, surface).map(str::to_owned)
}

