static NEXT_OBJECT_ID: AtomicI64 = AtomicI64::new(1);

#[derive(Debug, Clone)]
pub struct PhpObject {
    id: i64,
    class_id: ClassId,
    class_name: String,
    ancestor_class_names: Vec<String>,
    interface_names: Vec<String>,
    properties: Rc<RefCell<Vec<ObjectProperty>>>,
}

impl PartialEq for PhpObject {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

impl PhpObject {
    pub fn from_class(class: &PhpClassMetadata) -> Self {
        Self::from_class_with_id(class, NEXT_OBJECT_ID.fetch_add(1, AtomicOrdering::Relaxed))
    }

    pub fn from_class_with_id(class: &PhpClassMetadata, id: i64) -> Self {
        Self::from_class_with_inherited_properties_with_id(class, &[], id)
    }

    pub fn from_class_with_inherited_metadata_with_id(
        class: &PhpClassMetadata,
        inherited_properties: &[PhpObjectPropertyInitializer],
        ancestor_class_names: Vec<String>,
        id: i64,
    ) -> Self {
        Self::from_class_with_inherited_metadata_and_id(
            class,
            inherited_properties,
            ancestor_class_names,
            Vec::new(),
            id,
        )
    }

    pub fn from_class_with_relationship_metadata_with_id(
        class: &PhpClassMetadata,
        inherited_properties: &[PhpObjectPropertyInitializer],
        ancestor_class_names: Vec<String>,
        interface_names: Vec<String>,
        id: i64,
    ) -> Self {
        Self::from_class_with_inherited_metadata_and_id(
            class,
            inherited_properties,
            ancestor_class_names,
            interface_names,
            id,
        )
    }

    pub fn from_class_with_inherited_properties_with_id(
        class: &PhpClassMetadata,
        inherited_properties: &[PhpObjectPropertyInitializer],
        id: i64,
    ) -> Self {
        Self::from_class_with_inherited_properties_and_ancestors_with_id(
            class,
            inherited_properties,
            Vec::new(),
            id,
        )
    }

    fn from_class_with_inherited_properties_and_ancestors_with_id(
        class: &PhpClassMetadata,
        inherited_properties: &[PhpObjectPropertyInitializer],
        ancestor_class_names: Vec<String>,
        id: i64,
    ) -> Self {
        Self::from_class_with_inherited_metadata_and_id(
            class,
            inherited_properties,
            ancestor_class_names,
            Vec::new(),
            id,
        )
    }

    fn from_class_with_inherited_metadata_and_id(
        class: &PhpClassMetadata,
        inherited_properties: &[PhpObjectPropertyInitializer],
        ancestor_class_names: Vec<String>,
        interface_names: Vec<String>,
        id: i64,
    ) -> Self {
        let mut properties = Vec::new();
        for initializer in inherited_properties
            .iter()
            .filter(|initializer| !initializer.property.is_static())
        {
            Self::push_or_update_instance_property(
                &mut properties,
                initializer.declaring_class_id,
                initializer.declaring_class_name.clone(),
                initializer.property.name(),
                initializer.property.visibility(),
                initializer.property.type_decl().map(str::to_string),
            );
        }

        for property in class
            .properties()
            .iter()
            .filter(|property| !property.is_static())
        {
            Self::push_or_update_instance_property(
                &mut properties,
                class.id(),
                class.name().to_string(),
                property.name(),
                property.visibility(),
                property.type_decl().map(str::to_string),
            );
        }

        Self {
            id,
            class_id: class.id(),
            class_name: class.name().to_string(),
            ancestor_class_names,
            interface_names,
            properties: Rc::new(RefCell::new(properties)),
        }
    }

    fn push_or_update_instance_property(
        properties: &mut Vec<ObjectProperty>,
        declaring_class_id: ClassId,
        declaring_class_name: String,
        name: &str,
        visibility: Visibility,
        type_decl: Option<String>,
    ) {
        if visibility != Visibility::Private {
            if let Some(property) = properties.iter_mut().find(|property| {
                property.name == name && property.visibility != Visibility::Private
            }) {
                property.visibility = visibility;
                property.type_decl = type_decl;
                property.initialized = property.type_decl.is_none();
                return;
            }
        }

        properties.push(ObjectProperty {
            declaring_class_id,
            declaring_class_name,
            name: name.to_string(),
            visibility,
            type_decl: type_decl.clone(),
            storage: ObjectPropertyStorage::Value(PhpValueCell::new(Value::Null)),
            initialized: type_decl.is_none(),
        });
    }

    pub fn id(&self) -> i64 {
        self.id
    }

    pub fn hash(&self) -> String {
        format!("{:032x}", self.id)
    }

    pub fn class_id(&self) -> ClassId {
        self.class_id
    }

    pub fn class_name(&self) -> &str {
        &self.class_name
    }

    pub fn properties(&self) -> Vec<ObjectProperty> {
        self.properties.borrow().clone()
    }

    pub fn shallow_clone_with_id(&self, id: i64) -> Self {
        Self {
            id,
            class_id: self.class_id,
            class_name: self.class_name.clone(),
            ancestor_class_names: self.ancestor_class_names.clone(),
            interface_names: self.interface_names.clone(),
            properties: Rc::new(RefCell::new(self.properties.borrow().clone())),
        }
    }

    pub fn is_instance_of_class_name(&self, class_name: &str) -> bool {
        self.class_name.eq_ignore_ascii_case(class_name)
            || self
                .ancestor_class_names
                .iter()
                .any(|ancestor| ancestor.eq_ignore_ascii_case(class_name))
            || self
                .interface_names
                .iter()
                .any(|interface| interface.eq_ignore_ascii_case(class_name))
    }

    pub fn read_public_property(&self, name: &str) -> RuntimeResult<Value> {
        let properties = self.properties.borrow();
        let property = self.public_property_or_error(&properties, name)?;

        property.initialized_value_cloned()
    }

    pub fn public_property_cell_id(&self, name: &str) -> RuntimeResult<PhpValueCellId> {
        let properties = self.properties.borrow();
        let property = self.public_property_or_error(&properties, name)?;

        Ok(property.cell_id())
    }

    pub fn public_property_reference_cell_id(
        &self,
        name: &str,
    ) -> RuntimeResult<Option<PhpReferenceCellId>> {
        let properties = self.properties.borrow();
        let property = self.public_property_or_error(&properties, name)?;

        Ok(property.reference_cell_id())
    }

    pub fn read_property_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<Value> {
        let properties = self.properties.borrow();
        let property =
            self.context_property(&properties, name, current_class_id, protected_class_ids)?;

        property.initialized_value_cloned()
    }

    pub fn property_visibility_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<Visibility> {
        let properties = self.properties.borrow();
        let property =
            self.context_property(&properties, name, current_class_id, protected_class_ids)?;

        Ok(property.visibility)
    }

    pub fn is_public_property_set(&self, name: &str) -> RuntimeResult<bool> {
        let properties = self.properties.borrow();
        let Some(property) = self.public_property_or_none(&properties, name)? else {
            return Ok(false);
        };

        Ok(property.initialized && !matches!(property.value_cloned(), Value::Null))
    }

    pub fn is_property_set_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<bool> {
        let properties = self.properties.borrow();
        let Some(property) = self.context_property_or_none(
            &properties,
            name,
            current_class_id,
            protected_class_ids,
        )?
        else {
            return Ok(false);
        };

        Ok(property.initialized && !matches!(property.value_cloned(), Value::Null))
    }

    pub fn read_public_property_for_isset(&self, name: &str) -> RuntimeResult<Option<Value>> {
        let properties = self.properties.borrow();
        let Some(property) = self.public_property_or_none(&properties, name)? else {
            return Ok(None);
        };

        if !property.initialized {
            return Ok(None);
        }

        Ok(Some(property.value_cloned()))
    }

    pub fn read_property_for_isset_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<Option<Value>> {
        let properties = self.properties.borrow();
        let Some(property) = self.context_property_or_none(
            &properties,
            name,
            current_class_id,
            protected_class_ids,
        )?
        else {
            return Ok(None);
        };

        if !property.initialized {
            return Ok(None);
        }

        Ok(Some(property.value_cloned()))
    }

    pub fn read_current_public_property(&self, name: &str) -> Option<Value> {
        self.properties
            .borrow()
            .iter()
            .find(|property| property.name == name && property.visibility == Visibility::Public)
            .and_then(|property| property.initialized.then(|| property.value_cloned()))
    }

    pub fn is_public_property_empty(&self, name: &str) -> RuntimeResult<bool> {
        let properties = self.properties.borrow();
        let Some(property) = self.public_property_or_none(&properties, name)? else {
            return Ok(true);
        };

        if !property.initialized {
            return Ok(true);
        }

        Ok(!property.value_cloned().is_truthy())
    }

    pub fn is_property_empty_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<bool> {
        let properties = self.properties.borrow();
        let Some(property) = self.context_property_or_none(
            &properties,
            name,
            current_class_id,
            protected_class_ids,
        )?
        else {
            return Ok(true);
        };

        if !property.initialized {
            return Ok(true);
        }

        Ok(!property.value_cloned().is_truthy())
    }

    pub fn write_public_property(&self, name: &str, value: Value) -> RuntimeResult<()> {
        let mut properties = self.properties.borrow_mut();
        let property = self.public_property_mut_or_error(&mut properties, name)?;

        let value = coerce_typed_property_value(property, value)?;
        property.set_value(value);
        property.initialized = true;
        Ok(())
    }

    pub fn bind_public_property_reference_cell(
        &self,
        name: &str,
        reference: PhpReferenceCell,
    ) -> RuntimeResult<()> {
        let mut properties = self.properties.borrow_mut();
        let property = self.public_property_mut_or_error(&mut properties, name)?;

        let value = coerce_typed_property_value(property, reference.value_cloned())?;
        reference.set_value(value);
        property.set_reference_cell(reference);
        property.initialized = true;
        Ok(())
    }

    pub fn bind_dynamic_public_property_reference_cell(
        &self,
        name: &str,
    ) -> RuntimeResult<PhpReferenceCell> {
        let mut properties = self.properties.borrow_mut();
        if let Some(index) = properties.iter().rposition(|property| {
            property.name == name && property.visibility == Visibility::Public
        }) {
            return properties[index].reference_cell();
        }

        if properties
            .iter()
            .any(|property| property.name == name && property.visibility != Visibility::Public)
        {
            return Err(RuntimeError::unsupported_property_access(format!(
                "non-public property {}::${} requires same-class method context in the current subset",
                self.class_name, name
            )));
        }

        if !self.allows_dynamic_public_properties() {
            return Err(RuntimeError::undefined_property(
                self.class_name.clone(),
                name,
            ));
        }

        let reference = PhpReferenceCell::new(Value::Null);
        properties.push(ObjectProperty {
            declaring_class_id: self.class_id,
            declaring_class_name: self.class_name.clone(),
            name: name.to_string(),
            visibility: Visibility::Public,
            type_decl: None,
            storage: ObjectPropertyStorage::Reference(reference.clone()),
            initialized: true,
        });
        Ok(reference)
    }

    pub fn write_dynamic_public_property(&self, name: &str, value: Value) -> RuntimeResult<()> {
        let mut properties = self.properties.borrow_mut();
        if let Some(index) = properties.iter().rposition(|property| {
            property.name == name && property.visibility == Visibility::Public
        }) {
            let value = coerce_typed_property_value(&properties[index], value)?;
            properties[index].set_value(value);
            properties[index].initialized = true;
            return Ok(());
        }

        if properties
            .iter()
            .any(|property| property.name == name && property.visibility != Visibility::Public)
        {
            return Err(RuntimeError::unsupported_property_access(format!(
                "non-public property {}::${} requires same-class method context in the current subset",
                self.class_name, name
            )));
        }

        if !self.allows_dynamic_public_properties() {
            return Err(RuntimeError::undefined_property(
                self.class_name.clone(),
                name,
            ));
        }

        properties.push(ObjectProperty {
            declaring_class_id: self.class_id,
            declaring_class_name: self.class_name.clone(),
            name: name.to_string(),
            visibility: Visibility::Public,
            type_decl: None,
            storage: ObjectPropertyStorage::Value(PhpValueCell::new(value)),
            initialized: true,
        });
        Ok(())
    }

    fn allows_dynamic_public_properties(&self) -> bool {
        self.class_name.eq_ignore_ascii_case("stdClass")
            || self.class_name.eq_ignore_ascii_case("wpdb")
    }

    pub fn write_property_from_context(
        &self,
        name: &str,
        value: Value,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<()> {
        let mut properties = self.properties.borrow_mut();
        let Some(property) = self.context_property_mut_or_none(
            &mut properties,
            name,
            current_class_id,
            protected_class_ids,
        )?
        else {
            drop(properties);
            return self.write_dynamic_public_property(name, value);
        };

        let value = coerce_typed_property_value(property, value)?;
        property.set_value(value);
        property.initialized = true;
        Ok(())
    }

    pub fn bind_property_reference_cell_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<PhpReferenceCell> {
        let mut properties = self.properties.borrow_mut();
        let property = self.context_property_mut(
            &mut properties,
            name,
            current_class_id,
            protected_class_ids,
        )?;

        property.reference_cell()
    }

    pub fn existing_property_reference_cell_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<Option<PhpReferenceCell>> {
        let mut properties = self.properties.borrow_mut();
        let property = self.context_property_mut(
            &mut properties,
            name,
            current_class_id,
            protected_class_ids,
        )?;

        property.existing_reference_cell()
    }

    pub fn bind_property_reference_cell_to_context(
        &self,
        name: &str,
        reference: PhpReferenceCell,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<()> {
        let mut properties = self.properties.borrow_mut();
        let property = self.context_property_mut(
            &mut properties,
            name,
            current_class_id,
            protected_class_ids,
        )?;

        let value = coerce_typed_property_value(property, reference.value_cloned())?;
        reference.set_value(value);
        property.set_reference_cell(reference);
        property.initialized = true;
        Ok(())
    }

    pub fn write_property_from_context_with_object_type_resolver<F>(
        &self,
        name: &str,
        value: Value,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
        object_type_resolver: F,
    ) -> RuntimeResult<()>
    where
        F: Fn(&PhpObject, &str) -> bool,
    {
        let mut properties = self.properties.borrow_mut();
        let Some(property) = self.context_property_mut_or_none(
            &mut properties,
            name,
            current_class_id,
            protected_class_ids,
        )?
        else {
            drop(properties);
            return self.write_dynamic_public_property(name, value);
        };

        let value = coerce_typed_property_value_with_object_type_resolver(
            property,
            value,
            &object_type_resolver,
        )?;
        property.set_value(value);
        property.initialized = true;
        Ok(())
    }

    pub fn unset_property_from_context(
        &self,
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<bool> {
        let mut properties = self.properties.borrow_mut();
        let Some(property) = self.context_property_mut_or_none(
            &mut properties,
            name,
            current_class_id,
            protected_class_ids,
        )?
        else {
            return Ok(false);
        };

        property.unset_value();
        Ok(true)
    }

    fn public_property_or_error<'a>(
        &self,
        properties: &'a [ObjectProperty],
        name: &str,
    ) -> RuntimeResult<&'a ObjectProperty> {
        self.public_property_or_none(properties, name)?
            .ok_or_else(|| RuntimeError::undefined_property(self.class_name.clone(), name))
    }

    fn public_property_or_none<'a>(
        &self,
        properties: &'a [ObjectProperty],
        name: &str,
    ) -> RuntimeResult<Option<&'a ObjectProperty>> {
        if let Some(property) = properties
            .iter()
            .rev()
            .find(|property| property.name == name && property.visibility == Visibility::Public)
        {
            return Ok(Some(property));
        }

        self.unsupported_non_public_property(properties, name)
    }

    fn public_property_mut_or_error<'a>(
        &self,
        properties: &'a mut [ObjectProperty],
        name: &str,
    ) -> RuntimeResult<&'a mut ObjectProperty> {
        if let Some(index) = properties.iter().rposition(|property| {
            property.name == name && property.visibility == Visibility::Public
        }) {
            return Ok(&mut properties[index]);
        }

        self.unsupported_non_public_property_mut(properties, name)
    }

    fn context_property<'a>(
        &self,
        properties: &'a [ObjectProperty],
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<&'a ObjectProperty> {
        self.context_property_or_none(properties, name, current_class_id, protected_class_ids)?
            .ok_or_else(|| RuntimeError::undefined_property(self.class_name.clone(), name))
    }

    fn context_property_or_none<'a>(
        &self,
        properties: &'a [ObjectProperty],
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<Option<&'a ObjectProperty>> {
        if current_class_id.is_some() {
            if let Some(property) = properties.iter().rev().find(|property| {
                property.name == name
                    && property.visibility != Visibility::Public
                    && property.is_visible_in_context(current_class_id, protected_class_ids)
            }) {
                return Ok(Some(property));
            }
        }

        self.public_property_or_none(properties, name)
    }

    fn context_property_mut<'a>(
        &self,
        properties: &'a mut [ObjectProperty],
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<&'a mut ObjectProperty> {
        if current_class_id.is_some() {
            if let Some(index) = properties.iter().rposition(|property| {
                property.name == name
                    && property.visibility != Visibility::Public
                    && property.is_visible_in_context(current_class_id, protected_class_ids)
            }) {
                return Ok(&mut properties[index]);
            }
        }

        self.public_property_mut_or_error(properties, name)
    }

    fn context_property_mut_or_none<'a>(
        &self,
        properties: &'a mut [ObjectProperty],
        name: &str,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> RuntimeResult<Option<&'a mut ObjectProperty>> {
        if current_class_id.is_some() {
            if let Some(index) = properties.iter().rposition(|property| {
                property.name == name
                    && property.visibility != Visibility::Public
                    && property.is_visible_in_context(current_class_id, protected_class_ids)
            }) {
                return Ok(Some(&mut properties[index]));
            }
        }

        if let Some(index) = properties.iter().rposition(|property| {
            property.name == name && property.visibility == Visibility::Public
        }) {
            return Ok(Some(&mut properties[index]));
        }

        if properties
            .iter()
            .any(|property| property.name == name && property.visibility != Visibility::Public)
        {
            return Err(RuntimeError::unsupported_property_access(format!(
                "non-public property {}::${} requires same-class method context in the current subset",
                self.class_name, name
            )));
        }

        Ok(None)
    }

    fn unsupported_non_public_property<'a>(
        &self,
        properties: &'a [ObjectProperty],
        name: &str,
    ) -> RuntimeResult<Option<&'a ObjectProperty>> {
        if properties
            .iter()
            .any(|property| property.name == name && property.visibility != Visibility::Public)
        {
            return Err(RuntimeError::unsupported_property_access(format!(
                "non-public property {}::${} requires same-class method context in the current subset",
                self.class_name, name
            )));
        }

        Ok(None)
    }

    fn unsupported_non_public_property_mut<'a>(
        &self,
        properties: &'a mut [ObjectProperty],
        name: &str,
    ) -> RuntimeResult<&'a mut ObjectProperty> {
        if properties
            .iter()
            .any(|property| property.name == name && property.visibility != Visibility::Public)
        {
            return Err(RuntimeError::unsupported_property_access(format!(
                "non-public property {}::${} requires same-class method context in the current subset",
                self.class_name, name
            )));
        }

        Err(RuntimeError::undefined_property(
            self.class_name.clone(),
            name,
        ))
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ObjectProperty {
    declaring_class_id: ClassId,
    declaring_class_name: String,
    name: String,
    visibility: Visibility,
    type_decl: Option<String>,
    storage: ObjectPropertyStorage,
    initialized: bool,
}

#[derive(Debug, Clone, PartialEq)]
enum ObjectPropertyStorage {
    Value(PhpValueCell),
    Reference(PhpReferenceCell),
}

impl ObjectProperty {
    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn visibility(&self) -> Visibility {
        self.visibility
    }

    pub fn declaring_class_id(&self) -> ClassId {
        self.declaring_class_id
    }

    pub fn declaring_class_name(&self) -> &str {
        &self.declaring_class_name
    }

    pub fn value(&self) -> &Value {
        match &self.storage {
            ObjectPropertyStorage::Value(cell) => cell.value(),
            ObjectPropertyStorage::Reference(_) => {
                panic!("reference-backed object properties require value_cloned() reads")
            }
        }
    }

    pub fn value_cloned(&self) -> Value {
        match &self.storage {
            ObjectPropertyStorage::Value(cell) => cell.value_cloned(),
            ObjectPropertyStorage::Reference(reference) => reference.value_cloned(),
        }
    }

    pub fn cell_id(&self) -> PhpValueCellId {
        match &self.storage {
            ObjectPropertyStorage::Value(cell) => cell.id(),
            ObjectPropertyStorage::Reference(_) => {
                panic!("reference-backed object properties do not have value-cell ids")
            }
        }
    }

    pub fn reference_cell_id(&self) -> Option<PhpReferenceCellId> {
        match &self.storage {
            ObjectPropertyStorage::Value(_) => None,
            ObjectPropertyStorage::Reference(reference) => Some(reference.id()),
        }
    }

    pub fn is_reference(&self) -> bool {
        matches!(self.storage, ObjectPropertyStorage::Reference(_))
    }

    pub fn shares_reference_with(&self, other: &Self) -> bool {
        match (&self.storage, &other.storage) {
            (ObjectPropertyStorage::Reference(left), ObjectPropertyStorage::Reference(right)) => {
                left.shares_reference_with(right)
            }
            _ => false,
        }
    }

    pub fn is_initialized(&self) -> bool {
        self.initialized
    }

    pub fn mangled_name(&self) -> String {
        match self.visibility {
            Visibility::Public => self.name.clone(),
            Visibility::Protected => format!("\0*\0{}", self.name),
            Visibility::Private => format!("\0{}\0{}", self.declaring_class_name, self.name),
        }
    }

    fn is_visible_in_context(
        &self,
        current_class_id: Option<ClassId>,
        protected_class_ids: &[ClassId],
    ) -> bool {
        match self.visibility {
            Visibility::Public => true,
            Visibility::Private => current_class_id == Some(self.declaring_class_id),
            Visibility::Protected => protected_class_ids.contains(&self.declaring_class_id),
        }
    }

    fn initialized_value_cloned(&self) -> RuntimeResult<Value> {
        if self.initialized {
            Ok(self.value_cloned())
        } else {
            Err(RuntimeError::uninitialized_typed_property(
                self.declaring_class_name.clone(),
                self.name.clone(),
            ))
        }
    }

    fn set_value(&mut self, value: Value) {
        match &mut self.storage {
            ObjectPropertyStorage::Value(cell) => cell.set_value(value),
            ObjectPropertyStorage::Reference(reference) => reference.set_value(value),
        }
    }

    fn set_reference_cell(&mut self, reference: PhpReferenceCell) {
        reference.add_property_type_constraint(
            self.type_decl.as_deref(),
            &self.declaring_class_name,
            &self.name,
        );
        self.storage = ObjectPropertyStorage::Reference(reference);
    }

    fn unset_value(&mut self) {
        if let ObjectPropertyStorage::Reference(reference) = &self.storage {
            reference.remove_property_type_constraint(
                self.type_decl.as_deref(),
                &self.declaring_class_name,
                &self.name,
            );
        }
        self.storage = ObjectPropertyStorage::Value(PhpValueCell::new(Value::Null));
        self.initialized = self.type_decl.is_none();
    }

    fn reference_cell(&mut self) -> RuntimeResult<PhpReferenceCell> {
        if !self.initialized {
            return Err(RuntimeError::uninitialized_typed_property(
                self.declaring_class_name.clone(),
                self.name.clone(),
            ));
        }

        match &self.storage {
            ObjectPropertyStorage::Reference(reference) => {
                reference.add_property_type_constraint(
                    self.type_decl.as_deref(),
                    &self.declaring_class_name,
                    &self.name,
                );
                Ok(reference.clone())
            }
            ObjectPropertyStorage::Value(cell) => {
                let reference = PhpReferenceCell::new(cell.value_cloned());
                reference.add_property_type_constraint(
                    self.type_decl.as_deref(),
                    &self.declaring_class_name,
                    &self.name,
                );
                self.storage = ObjectPropertyStorage::Reference(reference.clone());
                Ok(reference)
            }
        }
    }

    fn existing_reference_cell(&self) -> RuntimeResult<Option<PhpReferenceCell>> {
        if !self.initialized {
            return Err(RuntimeError::uninitialized_typed_property(
                self.declaring_class_name.clone(),
                self.name.clone(),
            ));
        }

        match &self.storage {
            ObjectPropertyStorage::Reference(reference) => Ok(Some(reference.clone())),
            ObjectPropertyStorage::Value(_) => Ok(None),
        }
    }
}

fn coerce_typed_property_value(property: &ObjectProperty, value: Value) -> RuntimeResult<Value> {
    let Some(type_decl) = property.type_decl.as_deref() else {
        return Ok(value);
    };
    coerce_property_value(
        type_decl,
        value,
        &property.declaring_class_name,
        &property.name,
    )
}

fn coerce_typed_property_value_with_object_type_resolver<F>(
    property: &ObjectProperty,
    value: Value,
    object_type_resolver: &F,
) -> RuntimeResult<Value>
where
    F: Fn(&PhpObject, &str) -> bool,
{
    let Some(type_decl) = property.type_decl.as_deref() else {
        return Ok(value);
    };
    coerce_property_value_with_object_type_resolver(
        type_decl,
        value,
        &property.declaring_class_name,
        &property.name,
        object_type_resolver,
    )
}

pub fn coerce_property_value(
    type_decl: &str,
    value: Value,
    class_name: &str,
    property_name: &str,
) -> RuntimeResult<Value> {
    coerce_property_value_with_object_type_resolver(
        type_decl,
        value,
        class_name,
        property_name,
        |object, type_name| object.is_instance_of_class_name(type_name),
    )
}

pub fn coerce_property_value_with_object_type_resolver<F>(
    type_decl: &str,
    value: Value,
    class_name: &str,
    property_name: &str,
    object_type_resolver: F,
) -> RuntimeResult<Value>
where
    F: Fn(&PhpObject, &str) -> bool,
{
    coerce_property_value_with_object_type_resolver_dyn(
        type_decl,
        value,
        class_name,
        property_name,
        &object_type_resolver,
    )
}

fn coerce_property_value_with_object_type_resolver_dyn(
    type_decl: &str,
    value: Value,
    class_name: &str,
    property_name: &str,
    object_type_resolver: &dyn Fn(&PhpObject, &str) -> bool,
) -> RuntimeResult<Value> {
    if type_decl.contains('|') {
        for part in type_decl.split('|') {
            if let Ok(value) = coerce_property_value_with_object_type_resolver_dyn(
                part.trim(),
                value.clone(),
                class_name,
                property_name,
                object_type_resolver,
            ) {
                return Ok(value);
            }
        }
        return Err(typed_property_type_error(
            class_name,
            property_name,
            type_decl,
            value.type_name(),
        ));
    }

    if type_decl.contains('&') {
        for part in type_decl.split('&') {
            coerce_property_value_with_object_type_resolver_dyn(
                part.trim(),
                value.clone(),
                class_name,
                property_name,
                object_type_resolver,
            )
            .map_err(|_| {
                typed_property_type_error(class_name, property_name, type_decl, value.type_name())
            })?;
        }
        return Ok(value);
    }

    let without_nullable = type_decl.strip_prefix('?').unwrap_or(type_decl);
    let normalized = without_nullable
        .strip_prefix('\\')
        .unwrap_or(without_nullable)
        .to_ascii_lowercase();
    let allows_null = type_decl.starts_with('?') || normalized == "mixed" || normalized == "null";

    if matches!(value, Value::Null) {
        if allows_null {
            return Ok(value);
        }
        return Err(typed_property_type_error(
            class_name,
            property_name,
            type_decl,
            "null",
        ));
    }

    let coerced = match normalized.as_str() {
        "int" => match &value {
            Value::Int(_) => Some(value.clone()),
            Value::Bool(value) => Some(Value::Int(if *value { 1 } else { 0 })),
            Value::Float(value) => Some(Value::Int(*value as i64)),
            value if value.php_string_bytes().is_some() => {
                value.php_string_numeric_value().map(|number| match number {
                    Number::Int(value) => Value::Int(value),
                    Number::Float(value) => Value::Int(value as i64),
                })
            }
            _ => None,
        },
        "float" => match &value {
            Value::Int(value) => Some(Value::Float(*value as f64)),
            Value::Float(_) => Some(value.clone()),
            Value::Bool(value) => Some(Value::Float(if *value { 1.0 } else { 0.0 })),
            value if value.php_string_bytes().is_some() => {
                value.php_string_numeric_value().map(|number| match number {
                    Number::Int(value) => Value::Float(value as f64),
                    Number::Float(value) => Value::Float(value),
                })
            }
            _ => None,
        },
        "bool" => match &value {
            Value::Bool(_) => Some(value.clone()),
            Value::Int(value) => Some(Value::Bool(*value != 0)),
            Value::Float(value) => Some(Value::Bool(*value != 0.0)),
            value if value.php_string_bytes().is_some() => {
                value.php_string_truthy().map(Value::Bool)
            }
            _ => None,
        },
        "string" => match &value {
            Value::Null => None,
            _ => value.php_scalar_string_value(),
        },
        _ => None,
    };
    if let Some(value) = coerced {
        return Ok(value);
    }

    let compatible = match (&value, normalized.as_str()) {
        (_, "mixed") => true,
        (Value::Bool(true), "bool" | "true") => true,
        (Value::Bool(false), "bool" | "false") => true,
        (Value::Array(_), "array") => true,
        (Value::Object(_), "object") => true,
        (Value::Object(object), type_name) => object_type_resolver(object, type_name),
        _ => false,
    };

    if !compatible {
        return Err(typed_property_type_error(
            class_name,
            property_name,
            type_decl,
            value.type_name(),
        ));
    }

    Ok(value)
}

fn typed_property_type_error(
    class_name: &str,
    property_name: &str,
    type_decl: &str,
    actual: &str,
) -> RuntimeError {
    RuntimeError::invalid_property_access(format!(
        "typed property {class_name}::${property_name} expects {type_decl}, got {actual}"
    ))
}

fn normalize_string_key(value: String) -> ArrayKey {
    if is_php_integer_array_key(&value) {
        if let Ok(parsed) = value.parse::<i64>() {
            return ArrayKey::Int(parsed);
        }
    }

    ArrayKey::String(value)
}

fn normalize_string_key_bytes(value: Vec<u8>) -> ArrayKey {
    match String::from_utf8(value) {
        Ok(value) => normalize_string_key(value),
        Err(error) => {
            let bytes = error.into_bytes();
            if is_php_integer_array_key_bytes(&bytes) {
                if let Ok(text) = std::str::from_utf8(&bytes) {
                    if let Ok(parsed) = text.parse::<i64>() {
                        return ArrayKey::Int(parsed);
                    }
                }
            }
            ArrayKey::BinaryString(bytes)
        }
    }
}

pub fn text_only_surface_str(bytes: &[u8], surface: TextOnlySurface) -> RuntimeResult<&str> {
    if bytes.contains(&0) {
        return Err(RuntimeError::invalid_string_conversion(format!(
            "{} cannot contain NUL bytes",
            surface.label()
        )));
    }

    std::str::from_utf8(bytes).map_err(|_| {
        RuntimeError::invalid_string_conversion(format!(
            "{} requires valid UTF-8 text",
            surface.label()
        ))
    })
}

fn is_php_integer_array_key(value: &str) -> bool {
    is_php_integer_array_key_bytes(value.as_bytes())
}

fn is_php_integer_array_key_bytes(bytes: &[u8]) -> bool {
    if bytes.is_empty() {
        return false;
    }

    let (negative, digits) = if bytes[0] == b'-' {
        if bytes.len() == 1 {
            return false;
        }
        (true, &bytes[1..])
    } else {
        (false, bytes)
    };

    if !digits.iter().all(u8::is_ascii_digit) {
        return false;
    }

    if digits == b"0" {
        return !negative;
    }

    digits[0] != b'0'
}

pub fn escaped_byte_string(value: &[u8]) -> String {
    let mut escaped = String::new();
    for byte in value {
        match *byte {
            b'\\' => escaped.push_str("\\\\"),
            b'"' => escaped.push_str("\\\""),
            b'\n' => escaped.push_str("\\n"),
            b'\r' => escaped.push_str("\\r"),
            b'\t' => escaped.push_str("\\t"),
            0x20..=0x7e => escaped.push(char::from(*byte)),
            other => escaped.push_str(&format!("\\x{other:02X}")),
        }
    }
    escaped
}

fn normalize_class_lookup_name(name: &str) -> String {
    name.to_ascii_lowercase()
}

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    String(String),
    BinaryString(Vec<u8>),
    Array(PhpArray),
    Object(PhpObject),
    Closure(PhpClosure),
    Resource(i64),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PhpValueByteFormatter {
    Echo,
    Serialize,
    VarDump,
    PrintR,
}

impl PhpValueByteFormatter {
    fn surface_name(self) -> &'static str {
        match self {
            Self::Echo => "echo",
            Self::Serialize => "serialize()",
            Self::VarDump => "var_dump()",
            Self::PrintR => "print_r()",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct PhpClosure {
    id: i64,
    is_arrow: bool,
    captures: Vec<PhpClosureCapture>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct PhpClosureCapture {
    name: String,
    by_reference: bool,
    value: PhpReferenceCell,
}

impl PhpClosure {
    pub fn new(id: i64, is_arrow: bool, captures: Vec<PhpClosureCapture>) -> Self {
        Self {
            id,
            is_arrow,
            captures,
        }
    }

    pub fn id(&self) -> i64 {
        self.id
    }

    pub fn is_arrow(&self) -> bool {
        self.is_arrow
    }

    pub fn captures(&self) -> &[PhpClosureCapture] {
        &self.captures
    }
}

impl PhpClosureCapture {
    pub fn new(name: impl Into<String>, by_reference: bool, value: Value) -> Self {
        Self {
            name: name.into(),
            by_reference,
            value: PhpReferenceCell::new(value),
        }
    }

    pub fn new_reference(
        name: impl Into<String>,
        by_reference: bool,
        value: PhpReferenceCell,
    ) -> Self {
        Self {
            name: name.into(),
            by_reference,
            value,
        }
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn by_reference(&self) -> bool {
        self.by_reference
    }

    pub fn value(&self) -> Value {
        self.value.value_cloned()
    }

    pub fn cell(&self) -> PhpReferenceCell {
        self.value.clone()
    }
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Null => "null",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::String(_) | Value::BinaryString(_) => "string",
            Value::Array(_) => "array",
            Value::Object(_) => "object",
            Value::Closure(_) => "closure",
            Value::Resource(_) => "resource",
        }
    }

    pub fn gettype_name(&self) -> &'static str {
        match self {
            Value::Null => "NULL",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "double",
            Value::String(_) | Value::BinaryString(_) => "string",
            Value::Array(_) => "array",
            Value::Object(_) => "object",
            Value::Closure(_) => "object",
            Value::Resource(_) => "resource",
        }
    }

    pub fn is_scalar(&self) -> bool {
        matches!(
            self,
            Value::Bool(_)
                | Value::Int(_)
                | Value::Float(_)
                | Value::String(_)
                | Value::BinaryString(_)
        )
    }

    pub fn is_numeric(&self) -> bool {
        if self.php_string_bytes().is_some() {
            return self.php_string_numeric_value().is_some();
        }

        match self {
            Value::Int(_) | Value::Float(_) => true,
            Value::Null
            | Value::Bool(_)
            | Value::String(_)
            | Value::BinaryString(_)
            | Value::Array(_)
            | Value::Object(_)
            | Value::Closure(_)
            | Value::Resource(_) => false,
        }
    }

    pub fn is_countable(&self) -> bool {
        matches!(self, Value::Array(_))
    }

    pub fn is_iterable(&self) -> bool {
        matches!(self, Value::Array(_))
    }

    pub fn echo_string(&self) -> String {
        match self {
            Value::Null => String::new(),
            Value::Bool(false) => String::new(),
            Value::Bool(true) => "1".to_string(),
            Value::Int(value) => value.to_string(),
            Value::Float(value) => format_php_float(*value),
            Value::String(value) => value.clone(),
            Value::BinaryString(value) => String::from_utf8_lossy(value).into_owned(),
            Value::Array(_) => "Array".to_string(),
            Value::Object(_) => "Object".to_string(),
            Value::Closure(_) => "Object".to_string(),
            Value::Resource(id) => format!("Resource id #{id}"),
        }
    }

    pub fn try_echo_string(&self) -> RuntimeResult<String> {
        match self {
            Value::Array(_) => Err(RuntimeError::invalid_string_conversion(
                "array cannot be converted to string",
            )),
            Value::Object(object) => Err(RuntimeError::invalid_string_conversion(format!(
                "object of class {} cannot be converted to string",
                object.class_name()
            ))),
            Value::Closure(_) => Err(RuntimeError::invalid_string_conversion(
                "object of class Closure cannot be converted to string",
            )),
            Value::Resource(_) => Err(RuntimeError::invalid_string_conversion(
                "resource cannot be converted to string",
            )),
            _ => Ok(self.echo_string()),
        }
    }

    pub fn echo_bytes(&self) -> Vec<u8> {
        self.php_format_bytes(PhpValueByteFormatter::Echo)
            .expect("echo byte formatting is infallible for runtime values")
    }

    pub fn php_scalar_string_bytes(&self) -> Option<Vec<u8>> {
        match self {
            Value::Null
            | Value::Bool(_)
            | Value::Int(_)
            | Value::Float(_)
            | Value::String(_)
            | Value::BinaryString(_) => Some(self.echo_bytes()),
            Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => None,
        }
    }

    pub fn php_scalar_string_value(&self) -> Option<Self> {
        self.php_scalar_string_bytes()
            .map(value_from_php_string_bytes)
    }

    pub fn try_echo_bytes(&self) -> RuntimeResult<Vec<u8>> {
        match self {
            Value::Array(_) => Err(RuntimeError::invalid_string_conversion(
                "array cannot be converted to string",
            )),
            Value::Object(object) => Err(RuntimeError::invalid_string_conversion(format!(
                "object of class {} cannot be converted to string",
                object.class_name()
            ))),
            Value::Closure(_) => Err(RuntimeError::invalid_string_conversion(
                "object of class Closure cannot be converted to string",
            )),
            Value::Resource(_) => Err(RuntimeError::invalid_string_conversion(
                "resource cannot be converted to string",
            )),
            _ => Ok(self.echo_bytes()),
        }
    }

    pub fn try_string_bytes(&self) -> RuntimeResult<Vec<u8>> {
        self.try_echo_bytes()
    }

    pub fn php_serialized_bytes(&self) -> RuntimeResult<Vec<u8>> {
        self.php_format_bytes(PhpValueByteFormatter::Serialize)
    }

    pub fn php_var_dump_bytes(&self) -> Vec<u8> {
        self.php_format_bytes(PhpValueByteFormatter::VarDump)
            .expect("var_dump byte formatting is infallible for runtime values")
    }

    pub fn php_print_r_bytes(&self) -> Vec<u8> {
        self.php_format_bytes(PhpValueByteFormatter::PrintR)
            .expect("print_r byte formatting is infallible for runtime values")
    }

    pub fn php_format_bytes(&self, formatter: PhpValueByteFormatter) -> RuntimeResult<Vec<u8>> {
        match formatter {
            PhpValueByteFormatter::Echo => Ok(format_php_echo_value_bytes(self)),
            PhpValueByteFormatter::Serialize => {
                let mut output = Vec::new();
                format_php_serialized_value_bytes(self, &mut output).ok_or_else(|| {
                    RuntimeError::unsupported_call(
                        "serialize()",
                        format!(
                            "values of type {} are not implemented in the current subset",
                            self.type_name()
                        ),
                    )
                })?;
                Ok(output)
            }
            PhpValueByteFormatter::VarDump => Ok(format_php_var_dump_bytes_with_indent(self, 0)),
            PhpValueByteFormatter::PrintR => Ok(format_php_print_r_bytes_with_indent(self, 0)),
        }
    }

    pub fn is_truthy(&self) -> bool {
        if let Some(truthy) = self.php_string_truthy() {
            return truthy;
        }

        match self {
            Value::Null => false,
            Value::Bool(value) => *value,
            Value::Int(value) => *value != 0,
            Value::Float(value) => *value != 0.0,
            Value::String(_) | Value::BinaryString(_) => {
                unreachable!("string values handled above")
            }
            Value::Array(value) => !value.is_empty(),
            Value::Object(_) => true,
            Value::Closure(_) => true,
            Value::Resource(_) => true,
        }
    }

    pub fn php_add(&self, other: &Value) -> RuntimeResult<Value> {
        match (
            self.to_arithmetic_number(ArithmeticOp::Add)?,
            other.to_arithmetic_number(ArithmeticOp::Add)?,
        ) {
            (Number::Int(a), Number::Int(b)) => Ok(Value::Int(a.wrapping_add(b))),
            (a, b) => Ok(Value::Float(a.as_float() + b.as_float())),
        }
    }

    pub fn php_sub(&self, other: &Value) -> RuntimeResult<Value> {
        match (
            self.to_arithmetic_number(ArithmeticOp::Subtract)?,
            other.to_arithmetic_number(ArithmeticOp::Subtract)?,
        ) {
            (Number::Int(a), Number::Int(b)) => Ok(Value::Int(a.wrapping_sub(b))),
            (a, b) => Ok(Value::Float(a.as_float() - b.as_float())),
        }
    }

    pub fn php_mul(&self, other: &Value) -> RuntimeResult<Value> {
        match (
            self.to_arithmetic_number(ArithmeticOp::Multiply)?,
            other.to_arithmetic_number(ArithmeticOp::Multiply)?,
        ) {
            (Number::Int(a), Number::Int(b)) => Ok(Value::Int(a.wrapping_mul(b))),
            (a, b) => Ok(Value::Float(a.as_float() * b.as_float())),
        }
    }

    pub fn php_div(&self, other: &Value) -> RuntimeResult<Value> {
        let left = self.to_arithmetic_number(ArithmeticOp::Divide)?;
        let right = other.to_arithmetic_number(ArithmeticOp::Divide)?;
        if right.as_float() == 0.0 {
            return Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::Divide,
                "division by zero",
            ));
        }

        match (left, right) {
            (Number::Int(i64::MIN), Number::Int(-1)) => Ok(Value::Float(i64::MIN as f64 / -1.0)),
            (Number::Int(a), Number::Int(b)) if a % b == 0 => Ok(Value::Int(a / b)),
            (a, b) => Ok(Value::Float(a.as_float() / b.as_float())),
        }
    }

    pub fn php_mod(&self, other: &Value) -> RuntimeResult<Value> {
        let left = self.to_arithmetic_int(ArithmeticOp::Modulo)?;
        let right = other.to_arithmetic_int(ArithmeticOp::Modulo)?;
        if right == 0 {
            return Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::Modulo,
                "modulo by zero",
            ));
        }
        if left == i64::MIN && right == -1 {
            return Ok(Value::Int(0));
        }

        Ok(Value::Int(left % right))
    }

    pub fn php_negate(&self) -> RuntimeResult<Value> {
        match self.to_arithmetic_number(ArithmeticOp::Negate)? {
            Number::Int(value) => Ok(Value::Int(value.wrapping_neg())),
            Number::Float(value) => Ok(Value::Float(-value)),
        }
    }

    pub fn php_concat(&self, other: &Value) -> RuntimeResult<Value> {
        let mut bytes = self.try_string_bytes()?;
        bytes.extend_from_slice(&other.try_string_bytes()?);
        Ok(value_from_php_string_bytes(bytes))
    }

    pub fn php_string_cast(&self) -> RuntimeResult<Value> {
        self.try_string_bytes().map(value_from_php_string_bytes)
    }

    pub fn php_cast_int(&self) -> RuntimeResult<i64> {
        match self {
            Value::Null => Ok(0),
            Value::Bool(value) => Ok(if *value { 1 } else { 0 }),
            Value::Int(value) => Ok(*value),
            Value::Float(value) => native_cast_float_to_int(*value, "(int)"),
            Value::String(value) => native_cast_bytes_to_int(value.as_bytes()),
            Value::BinaryString(value) => native_cast_bytes_to_int(value),
            Value::Array(_) => Err(RuntimeError::unsupported_call(
                "(int)",
                "array-to-int cast behavior is not implemented",
            )),
            Value::Object(_) => Err(RuntimeError::unsupported_call(
                "(int)",
                "object-to-int cast behavior is not implemented",
            )),
            Value::Closure(_) => Err(RuntimeError::unsupported_call(
                "(int)",
                "Closure object-to-int cast behavior is not implemented",
            )),
            Value::Resource(_) => Err(RuntimeError::unsupported_call(
                "(int)",
                "resource-to-int cast behavior is not implemented",
            )),
        }
    }

    pub fn php_cast_float(&self) -> RuntimeResult<f64> {
        match self {
            Value::Null => Ok(0.0),
            Value::Bool(value) => Ok(if *value { 1.0 } else { 0.0 }),
            Value::Int(value) => Ok(*value as f64),
            Value::Float(value) => Ok(*value),
            Value::String(value) => native_cast_bytes_to_float(value.as_bytes()),
            Value::BinaryString(value) => native_cast_bytes_to_float(value),
            Value::Array(_) => Err(RuntimeError::unsupported_call(
                "(float)",
                "array-to-float cast behavior is not implemented",
            )),
            Value::Object(_) => Err(RuntimeError::unsupported_call(
                "(float)",
                "object-to-float cast behavior is not implemented",
            )),
            Value::Closure(_) => Err(RuntimeError::unsupported_call(
                "(float)",
                "Closure object-to-float cast behavior is not implemented",
            )),
            Value::Resource(_) => Err(RuntimeError::unsupported_call(
                "(float)",
                "resource-to-float cast behavior is not implemented",
            )),
        }
    }

    pub fn php_cast_array(&self) -> RuntimeResult<PhpArray> {
        match self {
            Value::Null => Ok(PhpArray::new()),
            Value::Array(value) => Ok(value.clone()),
            Value::Bool(_)
            | Value::Int(_)
            | Value::Float(_)
            | Value::String(_)
            | Value::BinaryString(_) => {
                let mut array = PhpArray::new();
                array.append(self.clone())?;
                Ok(array)
            }
            Value::Object(_) => Err(RuntimeError::unsupported_call(
                "(array)",
                "object-to-array cast property materialization is not implemented",
            )),
            Value::Closure(_) => Err(RuntimeError::unsupported_call(
                "(array)",
                "Closure object-to-array cast behavior is not implemented",
            )),
            Value::Resource(_) => Err(RuntimeError::unsupported_call(
                "(array)",
                "resource-to-array cast behavior is not implemented",
            )),
        }
    }

    pub fn php_bitwise_and(&self, other: &Value) -> RuntimeResult<Value> {
        self.php_bitwise(
            other,
            ArithmeticOp::BitwiseAnd,
            |left, right| left & right,
            |left, right| left & right,
        )
    }

    pub fn php_bitwise_or(&self, other: &Value) -> RuntimeResult<Value> {
        self.php_bitwise(
            other,
            ArithmeticOp::BitwiseOr,
            |left, right| left | right,
            |left, right| left | right,
        )
    }

    pub fn php_bitwise_xor(&self, other: &Value) -> RuntimeResult<Value> {
        self.php_bitwise(
            other,
            ArithmeticOp::BitwiseXor,
            |left, right| left ^ right,
            |left, right| left ^ right,
        )
    }

    pub fn php_bitwise_not(&self) -> RuntimeResult<Value> {
        if let Some(bytes) = self.php_string_bytes() {
            return Ok(bitwise_not_string_bytes(bytes));
        }

        match self {
            Value::Int(value) => Ok(Value::Int(!value)),
            Value::String(_) | Value::BinaryString(_) => {
                unreachable!("string values handled above")
            }
            Value::Null => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "null cannot be used with unary bitwise not",
            )),
            Value::Bool(_) => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "booleans cannot be used with unary bitwise not",
            )),
            Value::Float(_) => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "floats cannot be used with unary bitwise not",
            )),
            Value::Array(_) => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "arrays cannot be used with unary bitwise not",
            )),
            Value::Object(_) => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "objects cannot be used with unary bitwise not",
            )),
            Value::Closure(_) => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "closures cannot be used with unary bitwise not",
            )),
            Value::Resource(_) => Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::BitwiseNot,
                "resources cannot be used with unary bitwise not",
            )),
        }
    }

    pub fn php_shift_left(&self, other: &Value) -> RuntimeResult<Value> {
        let left = self.to_bitwise_int(ArithmeticOp::ShiftLeft)?;
        let right = other.to_bitwise_int(ArithmeticOp::ShiftLeft)?;
        if right < 0 {
            return Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::ShiftLeft,
                "bit shift by negative number",
            ));
        }
        let right = right as u32;
        if right >= i64::BITS {
            return Ok(Value::Int(0));
        }
        Ok(Value::Int((left as u64).wrapping_shl(right) as i64))
    }

    pub fn php_shift_right(&self, other: &Value) -> RuntimeResult<Value> {
        let left = self.to_bitwise_int(ArithmeticOp::ShiftRight)?;
        let right = other.to_bitwise_int(ArithmeticOp::ShiftRight)?;
        if right < 0 {
            return Err(RuntimeError::invalid_arithmetic(
                ArithmeticOp::ShiftRight,
                "bit shift by negative number",
            ));
        }
        let right = right as u32;
        if right >= i64::BITS - 1 {
            return Ok(Value::Int(if left < 0 { -1 } else { 0 }));
        }
        Ok(Value::Int(left >> right))
    }

    pub fn php_eq(&self, other: &Value) -> bool {
        self.php_cmp(other, Comparison::Eq)
    }

    pub fn php_identical_checked(&self, other: &Value) -> RuntimeResult<bool> {
        match (self, other) {
            (Value::Array(left), Value::Array(right)) => left.is_identical_to(right),
            (Value::Array(_), _) | (_, Value::Array(_)) => Ok(false),
            (Value::Object(left), Value::Object(right)) => Ok(left.id() == right.id()),
            (Value::Object(_), _) | (_, Value::Object(_)) => Ok(false),
            (Value::Resource(left), Value::Resource(right)) => Ok(left == right),
            (Value::Resource(_), _) | (_, Value::Resource(_)) => Ok(false),
            _ => Ok(self.php_identical_scalar(other)),
        }
    }

    fn php_identical_scalar(&self, other: &Value) -> bool {
        if let (Some(left), Some(right)) = (self.php_string_bytes(), other.php_string_bytes()) {
            return left == right;
        }

        match (self, other) {
            (Value::Null, Value::Null) => true,
            (Value::Bool(left), Value::Bool(right)) => left == right,
            (Value::Int(left), Value::Int(right)) => left == right,
            (Value::Float(left), Value::Float(right)) => left == right,
            (Value::Resource(left), Value::Resource(right)) => left == right,
            _ => false,
        }
    }

    pub fn php_cmp_checked(&self, other: &Value, op: Comparison) -> RuntimeResult<bool> {
        match (self, other) {
            (Value::Object(_), _) | (_, Value::Object(_)) => Err(
                RuntimeError::unsupported_comparison("object comparisons are not implemented"),
            ),
            (Value::Resource(_), _) | (_, Value::Resource(_)) => Err(
                RuntimeError::unsupported_comparison("resource comparisons are not implemented"),
            ),
            _ => Ok(self.php_cmp(other, op)),
        }
    }

    pub fn php_cmp(&self, other: &Value, op: Comparison) -> bool {
        match (self.php_ordering(other), op) {
            (Some(Ordering::Less), Comparison::Lt | Comparison::Le | Comparison::Ne) => true,
            (Some(Ordering::Equal), Comparison::Eq | Comparison::Le | Comparison::Ge) => true,
            (Some(Ordering::Greater), Comparison::Gt | Comparison::Ge | Comparison::Ne) => true,
            (None, Comparison::Ne) => true,
            _ => false,
        }
    }

    fn php_ordering(&self, other: &Value) -> Option<Ordering> {
        match (self, other) {
            (Value::Bool(_), _) | (_, Value::Bool(_)) => {
                Some(self.is_truthy().cmp(&other.is_truthy()))
            }
            (Value::Array(_), _) | (_, Value::Array(_)) => None,
            (Value::Object(_), _) | (_, Value::Object(_)) => None,
            (Value::Resource(_), _) | (_, Value::Resource(_)) => None,
            (Value::Null, Value::Null) => Some(Ordering::Equal),
            (Value::Null, right) if right.php_string_bytes().is_some() => {
                compare_binary_bytes(b"", right.php_string_bytes().unwrap())
            }
            (left, Value::Null) if left.php_string_bytes().is_some() => {
                compare_binary_bytes(left.php_string_bytes().unwrap(), b"")
            }
            (Value::Null, _) => compare_numbers(Number::Int(0), other.numeric_value()?),
            (_, Value::Null) => compare_numbers(self.numeric_value()?, Number::Int(0)),
            (left, right)
                if left.php_string_bytes().is_some() && right.php_string_bytes().is_some() =>
            {
                compare_php_string_bytes(
                    left.php_string_bytes().unwrap(),
                    right.php_string_bytes().unwrap(),
                )
            }
            (left, Value::Int(right)) if left.php_string_bytes().is_some() => {
                compare_string_bytes_and_number(
                    left.php_string_bytes().unwrap(),
                    Number::Int(*right),
                )
            }
            (left, Value::Float(right)) if left.php_string_bytes().is_some() => {
                compare_string_bytes_and_number(
                    left.php_string_bytes().unwrap(),
                    Number::Float(*right),
                )
            }
            (Value::Int(left), right) if right.php_string_bytes().is_some() => {
                compare_number_and_string_bytes(
                    Number::Int(*left),
                    right.php_string_bytes().unwrap(),
                )
            }
            (Value::Float(left), right) if right.php_string_bytes().is_some() => {
                compare_number_and_string_bytes(
                    Number::Float(*left),
                    right.php_string_bytes().unwrap(),
                )
            }
            _ => compare_numbers(self.numeric_value()?, other.numeric_value()?),
        }
    }

    fn php_string_bytes(&self) -> Option<&[u8]> {
        match self {
            Value::String(value) => Some(value.as_bytes()),
            Value::BinaryString(value) => Some(value.as_slice()),
            _ => None,
        }
    }

    fn php_string_numeric_value(&self) -> Option<Number> {
        self.php_string_bytes().and_then(parse_numeric_bytes)
    }

    fn php_string_truthy(&self) -> Option<bool> {
        self.php_string_bytes().map(php_string_bytes_truthy)
    }

    fn numeric_value(&self) -> Option<Number> {
        match self {
            Value::Int(value) => Some(Number::Int(*value)),
            Value::Float(value) => Some(Number::Float(*value)),
            Value::Null => Some(Number::Int(0)),
            Value::Bool(false) => Some(Number::Int(0)),
            Value::Bool(true) => Some(Number::Int(1)),
            value if value.php_string_bytes().is_some() => value.php_string_numeric_value(),
            Value::String(_) | Value::BinaryString(_) => None,
            Value::Array(_) => None,
            Value::Object(_) => None,
            Value::Closure(_) => None,
            Value::Resource(_) => None,
        }
    }

    fn to_arithmetic_number(&self, operation: ArithmeticOp) -> RuntimeResult<Number> {
        match self {
            Value::Null => Ok(Number::Int(0)),
            Value::Bool(false) => Ok(Number::Int(0)),
            Value::Bool(true) => Ok(Number::Int(1)),
            Value::Int(value) => Ok(Number::Int(*value)),
            Value::Float(value) => Ok(Number::Float(*value)),
            value if value.php_string_bytes().is_some() => {
                value.php_string_numeric_value().ok_or_else(|| {
                    RuntimeError::invalid_arithmetic(operation, "string is not numeric")
                })
            }
            Value::String(_) | Value::BinaryString(_) => {
                unreachable!("string values handled above")
            }
            Value::Array(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "arrays are not numeric",
            )),
            Value::Object(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "objects are not numeric",
            )),
            Value::Closure(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "closures are not numeric",
            )),
            Value::Resource(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "resources are not numeric",
            )),
        }
    }

    fn to_arithmetic_int(&self, operation: ArithmeticOp) -> RuntimeResult<i64> {
        match self.to_arithmetic_number(operation)? {
            Number::Int(value) => Ok(value),
            Number::Float(value) => Ok(value as i64),
        }
    }

    fn php_bitwise(
        &self,
        other: &Value,
        operation: ArithmeticOp,
        byte_op: fn(u8, u8) -> u8,
        int_op: fn(i64, i64) -> i64,
    ) -> RuntimeResult<Value> {
        if let (Some(left), Some(right)) = (self.php_string_bytes(), other.php_string_bytes()) {
            return Ok(value_from_php_string_bytes(bitwise_string_bytes(
                left, right, operation, byte_op,
            )));
        }

        let left = self.to_bitwise_int(operation)?;
        let right = other.to_bitwise_int(operation)?;
        Ok(Value::Int(int_op(left, right)))
    }

    fn to_bitwise_int(&self, operation: ArithmeticOp) -> RuntimeResult<i64> {
        match self {
            Value::Null => Ok(0),
            Value::Bool(false) => Ok(0),
            Value::Bool(true) => Ok(1),
            Value::Int(value) => Ok(*value),
            Value::Float(value) => Ok(*value as i64),
            value if value.php_string_bytes().is_some() => match value.php_string_numeric_value() {
                Some(Number::Int(value)) => Ok(value),
                Some(Number::Float(value)) => Ok(value as i64),
                None => Err(RuntimeError::invalid_arithmetic(
                    operation,
                    "string is not numeric",
                )),
            },
            Value::String(_) | Value::BinaryString(_) => {
                unreachable!("string values handled above")
            }
            Value::Array(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "arrays cannot be used with bitwise operators",
            )),
            Value::Object(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "objects cannot be used with bitwise operators",
            )),
            Value::Closure(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "closures cannot be used with bitwise operators",
            )),
            Value::Resource(_) => Err(RuntimeError::invalid_arithmetic(
                operation,
                "resources cannot be used with bitwise operators",
            )),
        }
    }
}

fn bitwise_string_bytes(
    left: &[u8],
    right: &[u8],
    operation: ArithmeticOp,
    op: fn(u8, u8) -> u8,
) -> Vec<u8> {
    match operation {
        ArithmeticOp::BitwiseAnd | ArithmeticOp::BitwiseXor => left
            .iter()
            .zip(right.iter())
            .map(|(left, right)| op(*left, *right))
            .collect(),
        ArithmeticOp::BitwiseOr => {
            let mut output = Vec::with_capacity(left.len().max(right.len()));
            let common_len = left.len().min(right.len());
            for index in 0..common_len {
                output.push(op(left[index], right[index]));
            }
            if left.len() > common_len {
                output.extend_from_slice(&left[common_len..]);
            } else if right.len() > common_len {
                output.extend_from_slice(&right[common_len..]);
            }
            output
        }
        _ => unreachable!("caller provided a bitwise operation"),
    }
}

fn bitwise_not_string_bytes(value: &[u8]) -> Value {
    value_from_php_string_bytes(value.iter().map(|byte| !byte).collect())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Comparison {
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

#[derive(Debug, Clone, Copy)]
enum Number {
    Int(i64),
    Float(f64),
}

impl Number {
    fn as_float(&self) -> f64 {
        match self {
            Number::Int(value) => *value as f64,
            Number::Float(value) => *value,
        }
    }

    fn to_php_string(self) -> String {
        match self {
            Number::Int(value) => value.to_string(),
            Number::Float(value) => format_php_float(value),
        }
    }
}

fn compare_numbers(left: Number, right: Number) -> Option<Ordering> {
    match (left, right) {
        (Number::Int(left), Number::Int(right)) => Some(left.cmp(&right)),
        (left, right) => left.as_float().partial_cmp(&right.as_float()),
    }
}

fn compare_php_string_bytes(left: &[u8], right: &[u8]) -> Option<Ordering> {
    match (parse_numeric_bytes(left), parse_numeric_bytes(right)) {
        (Some(left), Some(right)) => compare_numbers(left, right),
        _ => compare_binary_bytes(left, right),
    }
}

fn compare_number_and_string_bytes(left: Number, right: &[u8]) -> Option<Ordering> {
    if let Some(right) = parse_numeric_bytes(right) {
        compare_numbers(left, right)
    } else {
        compare_binary_bytes(left.to_php_string().as_bytes(), right)
    }
}

fn compare_string_bytes_and_number(left: &[u8], right: Number) -> Option<Ordering> {
    if let Some(left) = parse_numeric_bytes(left) {
        compare_numbers(left, right)
    } else {
        compare_binary_bytes(left, right.to_php_string().as_bytes())
    }
}

fn compare_binary_bytes(left: &[u8], right: &[u8]) -> Option<Ordering> {
    Some(left.cmp(right))
}

fn native_cast_bytes_to_int(value: &[u8]) -> RuntimeResult<i64> {
    let trimmed = trim_ascii_whitespace_bytes(value);
    let Some(prefix) = leading_numeric_bytes(trimmed) else {
        return Ok(0);
    };
    let prefix = std::str::from_utf8(prefix).map_err(|_| {
        RuntimeError::unsupported_call("(int)", "non-UTF-8 numeric string prefix is not supported")
    })?;

    if let Ok(value) = prefix.parse::<i64>() {
        return Ok(value);
    }
    if let Ok(value) = prefix.parse::<f64>() {
        return native_cast_float_to_int(value, "(int)");
    }

    Ok(0)
}

fn native_cast_bytes_to_float(value: &[u8]) -> RuntimeResult<f64> {
    let trimmed = trim_ascii_whitespace_bytes(value);
    let Some(prefix) = leading_numeric_bytes(trimmed) else {
        return Ok(0.0);
    };
    let prefix = std::str::from_utf8(prefix).map_err(|_| {
        RuntimeError::unsupported_call(
            "(float)",
            "non-UTF-8 numeric string prefix is not supported",
        )
    })?;

    match prefix.parse::<f64>() {
        Ok(value) if value.is_finite() => Ok(value),
        Ok(_) => Err(RuntimeError::unsupported_call(
            "(float)",
            "non-finite float string cast behavior is not implemented",
        )),
        Err(_) => Ok(0.0),
    }
}

fn native_cast_float_to_int(value: f64, callable: &'static str) -> RuntimeResult<i64> {
    if !value.is_finite() || value < i64::MIN as f64 || value >= 9_223_372_036_854_775_808.0 {
        return Err(RuntimeError::unsupported_call(
            callable,
            "non-finite or out-of-range float-to-int cast behavior is not implemented",
        ));
    }

    Ok(value.trunc() as i64)
}

fn trim_ascii_whitespace_bytes(value: &[u8]) -> &[u8] {
    let start = value
        .iter()
        .position(|byte| !byte.is_ascii_whitespace())
        .unwrap_or(value.len());
    let end = value
        .iter()
        .rposition(|byte| !byte.is_ascii_whitespace())
        .map(|index| index + 1)
        .unwrap_or(start);
    &value[start..end]
}

fn leading_numeric_bytes(value: &[u8]) -> Option<&[u8]> {
    let mut index = 0;

    if matches!(value.get(index), Some(b'+' | b'-')) {
        index += 1;
    }

    let digits_before_decimal = consume_ascii_digits(value, &mut index);
    if matches!(value.get(index), Some(b'.')) {
        index += 1;
        let digits_after_decimal = consume_ascii_digits(value, &mut index);
        if digits_before_decimal == 0 && digits_after_decimal == 0 {
            return None;
        }
    } else if digits_before_decimal == 0 {
        return None;
    }

    if matches!(value.get(index), Some(b'e' | b'E')) {
        let exponent_marker = index;
        index += 1;
        if matches!(value.get(index), Some(b'+' | b'-')) {
            index += 1;
        }
        if consume_ascii_digits(value, &mut index) == 0 {
            index = exponent_marker;
        }
    }

    Some(&value[..index])
}

fn parse_numeric_string(value: &str) -> Option<Number> {
    let trimmed = value.trim_matches(|ch: char| ch.is_ascii_whitespace());
    if trimmed.is_empty() || !is_well_formed_numeric_string(trimmed) {
        return None;
    }

    let has_float_syntax = trimmed
        .bytes()
        .any(|byte| matches!(byte, b'.' | b'e' | b'E'));
    if !has_float_syntax {
        if let Ok(parsed) = trimmed.parse::<i64>() {
            return Some(Number::Int(parsed));
        }
    }

    trimmed.parse::<f64>().ok().map(Number::Float)
}

fn parse_numeric_bytes(value: &[u8]) -> Option<Number> {
    std::str::from_utf8(value)
        .ok()
        .and_then(parse_numeric_string)
}

fn php_string_offset_from_bytes(value: &[u8]) -> Option<i64> {
    let value = trim_ascii_whitespace_bytes(value);
    if value.is_empty() {
        return None;
    }

    let digits = if matches!(value[0], b'+' | b'-') {
        let digits = &value[1..];
        if digits.is_empty() {
            return None;
        }
        digits
    } else {
        value
    };
    if !digits.iter().all(u8::is_ascii_digit) {
        return None;
    }

    std::str::from_utf8(value).ok()?.parse::<i64>().ok()
}

fn php_string_bytes_truthy(bytes: &[u8]) -> bool {
    !bytes.is_empty() && bytes != b"0"
}

fn is_well_formed_numeric_string(value: &str) -> bool {
    let bytes = value.as_bytes();
    let mut index = 0;

    if matches!(bytes.get(index), Some(b'+' | b'-')) {
        index += 1;
    }

    let digits_before_decimal = consume_ascii_digits(bytes, &mut index);
    if matches!(bytes.get(index), Some(b'.')) {
        index += 1;
        let digits_after_decimal = consume_ascii_digits(bytes, &mut index);
        if digits_before_decimal == 0 && digits_after_decimal == 0 {
            return false;
        }
    } else if digits_before_decimal == 0 {
        return false;
    }

    if matches!(bytes.get(index), Some(b'e' | b'E')) {
        index += 1;
        if matches!(bytes.get(index), Some(b'+' | b'-')) {
            index += 1;
        }
        if consume_ascii_digits(bytes, &mut index) == 0 {
            return false;
        }
    }

    index == bytes.len()
}

fn consume_ascii_digits(bytes: &[u8], index: &mut usize) -> usize {
    let start = *index;
    while matches!(bytes.get(*index), Some(b'0'..=b'9')) {
        *index += 1;
    }
    *index - start
}

fn format_php_float(value: f64) -> String {
    if value.is_nan() {
        return "NAN".to_string();
    }
    if value.is_infinite() {
        return if value.is_sign_positive() {
            "INF".to_string()
        } else {
            "-INF".to_string()
        };
    }

    let formatted = format!("{}", value);
    if formatted == "-0" {
        "0".to_string()
    } else {
        formatted
    }
}

fn format_php_echo_value_bytes(value: &Value) -> Vec<u8> {
    if let Some(bytes) = value.php_string_bytes() {
        return bytes.to_vec();
    }

    match value {
        Value::Null => Vec::new(),
        Value::Bool(false) => Vec::new(),
        Value::Bool(true) => b"1".to_vec(),
        Value::Int(value) => value.to_string().into_bytes(),
        Value::Float(value) => format_php_float(*value).into_bytes(),
        Value::Array(_) => b"Array".to_vec(),
        Value::Object(_) => b"Object".to_vec(),
        Value::Closure(_) => b"Object".to_vec(),
        Value::Resource(id) => format!("Resource id #{id}").into_bytes(),
        Value::String(_) | Value::BinaryString(_) => unreachable!("string values handled above"),
    }
}

fn format_php_serialized_value_bytes(value: &Value, output: &mut Vec<u8>) -> Option<()> {
    if let Some(bytes) = value.php_string_bytes() {
        push_php_serialized_string_bytes(bytes, output);
        return Some(());
    }

    match value {
        Value::Null => output.extend_from_slice(b"N;"),
        Value::Bool(value) => output.extend_from_slice(if *value { b"b:1;" } else { b"b:0;" }),
        Value::Int(value) => {
            output.extend_from_slice(b"i:");
            output.extend_from_slice(value.to_string().as_bytes());
            output.push(b';');
        }
        Value::Float(value) => {
            output.extend_from_slice(b"d:");
            output.extend_from_slice(value.to_string().as_bytes());
            output.push(b';');
        }
        Value::Array(array) => {
            output.extend_from_slice(b"a:");
            output.extend_from_slice(array.len().to_string().as_bytes());
            output.extend_from_slice(b":{");
            for entry in array.entries() {
                format_php_serialized_array_key(&entry.key, output);
                format_php_serialized_value_bytes(entry.value(), output)?;
            }
            output.push(b'}');
        }
        Value::Object(_) | Value::Closure(_) | Value::Resource(_) => return None,
        Value::String(_) | Value::BinaryString(_) => unreachable!("string values handled above"),
    }
    Some(())
}

fn push_php_serialized_string_bytes(bytes: &[u8], output: &mut Vec<u8>) {
    output.extend_from_slice(b"s:");
    output.extend_from_slice(bytes.len().to_string().as_bytes());
    output.extend_from_slice(b":\"");
    output.extend_from_slice(bytes);
    output.extend_from_slice(b"\";");
}

fn format_php_serialized_array_key(key: &ArrayKey, output: &mut Vec<u8>) {
    if let Some(bytes) = key.php_string_bytes() {
        push_php_serialized_string_bytes(bytes, output);
        return;
    }

    match key {
        ArrayKey::Int(value) => {
            output.extend_from_slice(b"i:");
            output.extend_from_slice(value.to_string().as_bytes());
            output.push(b';');
        }
        ArrayKey::String(_) | ArrayKey::BinaryString(_) => {
            unreachable!("string keys handled above")
        }
    }
}

fn format_php_var_dump_bytes_with_indent(value: &Value, indent: usize) -> Vec<u8> {
    let padding = "  ".repeat(indent);
    if let Some(bytes) = value.php_string_bytes() {
        let mut output = format!("{padding}string({}) \"", bytes.len()).into_bytes();
        output.extend_from_slice(bytes);
        output.extend_from_slice(b"\"\n");
        return output;
    }

    match value {
        Value::Null => format!("{padding}NULL\n").into_bytes(),
        Value::Bool(value) => {
            format!("{padding}bool({})\n", if *value { "true" } else { "false" }).into_bytes()
        }
        Value::Int(value) => format!("{padding}int({value})\n").into_bytes(),
        Value::Float(value) => format!("{padding}float({})\n", value).into_bytes(),
        Value::Array(value) => {
            let mut output = format!("{padding}array({}) {{\n", value.len()).into_bytes();
            for entry in value.entries() {
                output.extend_from_slice(format!("{padding}  [").as_bytes());
                output.extend_from_slice(&format_php_var_dump_key_bytes(&entry.key));
                output.extend_from_slice(b"]=>\n");
                output.extend_from_slice(&format_php_var_dump_bytes_with_indent(
                    entry.value(),
                    indent + 1,
                ));
            }
            output.extend_from_slice(format!("{padding}}}\n").as_bytes());
            output
        }
        Value::Object(value) => {
            let mut output = format!(
                "{padding}object({}) ({}) {{\n",
                value.class_name(),
                value.properties().len()
            )
            .into_bytes();
            for property in value.properties() {
                output.extend_from_slice(format!("{padding}  [").as_bytes());
                output.extend_from_slice(format_php_var_dump_object_property(&property).as_bytes());
                output.extend_from_slice(b"]=>\n");
                let property_value = property.value_cloned();
                output.extend_from_slice(&format_php_var_dump_bytes_with_indent(
                    &property_value,
                    indent + 1,
                ));
            }
            output.extend_from_slice(format!("{padding}}}\n").as_bytes());
            output
        }
        Value::Closure(value) => format!(
            "{padding}object(Closure)#{} (0) {{\n{padding}}}\n",
            value.id()
        )
        .into_bytes(),
        Value::Resource(id) => format!("{padding}resource({id}) of type (stream)\n").into_bytes(),
        Value::String(_) | Value::BinaryString(_) => unreachable!("string values handled above"),
    }
}

fn format_php_var_dump_key_bytes(key: &ArrayKey) -> Vec<u8> {
    if let Some(bytes) = key.php_string_bytes() {
        let mut output = Vec::with_capacity(bytes.len() + 2);
        output.push(b'"');
        output.extend_from_slice(bytes);
        output.push(b'"');
        return output;
    }

    match key {
        ArrayKey::Int(value) => value.to_string().into_bytes(),
        ArrayKey::String(_) | ArrayKey::BinaryString(_) => {
            unreachable!("string keys handled above")
        }
    }
}

fn format_php_print_r_bytes_with_indent(value: &Value, indent: usize) -> Vec<u8> {
    if let Some(bytes) = value.php_string_bytes() {
        return bytes.to_vec();
    }

    match value {
        Value::Array(array) => format_php_print_r_array_bytes(array, indent),
        Value::Object(object) => format_php_print_r_object_bytes(object, indent),
        Value::Resource(id) => format!("Resource id #{id}").into_bytes(),
        Value::String(_) | Value::BinaryString(_) => unreachable!("string values handled above"),
        _ => value.echo_bytes(),
    }
}

fn format_php_print_r_array_bytes(array: &PhpArray, indent: usize) -> Vec<u8> {
    let padding = "    ".repeat(indent);
    let child_padding = "    ".repeat(indent + 1);
    let mut output = Vec::new();

    output.extend_from_slice(b"Array\n");
    output.extend_from_slice(format!("{padding}(\n").as_bytes());
    for entry in array.entries() {
        output.extend_from_slice(format!("{child_padding}[").as_bytes());
        output.extend_from_slice(&format_php_print_r_key_bytes(&entry.key));
        output.extend_from_slice(b"] => ");
        match entry.value() {
            Value::Array(value) => {
                output.extend_from_slice(&format_php_print_r_array_bytes(value, indent + 1));
            }
            Value::Object(value) => {
                output.extend_from_slice(&format_php_print_r_object_bytes(value, indent + 1));
            }
            value => {
                output.extend_from_slice(&format_php_print_r_bytes_with_indent(value, 0));
                output.push(b'\n');
            }
        }
    }
    output.extend_from_slice(format!("{padding})\n").as_bytes());
    output
}

fn format_php_print_r_object_bytes(object: &PhpObject, indent: usize) -> Vec<u8> {
    let padding = "    ".repeat(indent);
    let child_padding = "    ".repeat(indent + 1);
    let mut output = Vec::new();

    output.extend_from_slice(format!("{} Object\n", object.class_name()).as_bytes());
    output.extend_from_slice(format!("{padding}(\n").as_bytes());
    for property in object.properties() {
        output.extend_from_slice(format!("{child_padding}[").as_bytes());
        output.extend_from_slice(format_php_print_r_object_property(&property).as_bytes());
        output.extend_from_slice(b"] => ");
        match property.value_cloned() {
            Value::Array(value) => {
                output.extend_from_slice(&format_php_print_r_array_bytes(&value, indent + 1));
            }
            Value::Object(value) => {
                output.extend_from_slice(&format_php_print_r_object_bytes(&value, indent + 1));
            }
            value => {
                output.extend_from_slice(&format_php_print_r_bytes_with_indent(&value, 0));
                output.push(b'\n');
            }
        }
    }
    output.extend_from_slice(format!("{padding})\n").as_bytes());
    output
}

fn format_php_print_r_key_bytes(key: &ArrayKey) -> Vec<u8> {
    if let Some(bytes) = key.php_string_bytes() {
        return bytes.to_vec();
    }

    match key {
        ArrayKey::Int(value) => value.to_string().into_bytes(),
        ArrayKey::String(_) | ArrayKey::BinaryString(_) => {
            unreachable!("string keys handled above")
        }
    }
}

fn format_php_print_r_object_property(property: &ObjectProperty) -> String {
    match property.visibility() {
        Visibility::Public => property.name().to_string(),
        Visibility::Protected => format!("{}:protected", property.name()),
        Visibility::Private => {
            format!(
                "{}:{}:private",
                property.name(),
                property.declaring_class_name()
            )
        }
    }
}

fn format_php_var_dump_object_property(property: &ObjectProperty) -> String {
    match property.visibility() {
        Visibility::Public => format!("\"{}\"", property.name()),
        Visibility::Protected => format!("\"{}\":protected", property.name()),
        Visibility::Private => format!(
            "\"{}\":\"{}\":private",
            property.name(),
            property.declaring_class_name()
        ),
    }
}

