    fn native_value_text_membership_result_for_test(
        value: NativeValueHandle,
        surface: NativeTextSurfaceTag,
        candidates: &[&[u8]],
        case_insensitive: bool,
    ) -> Result<bool, Vec<u8>> {
        let candidate_ptrs = candidates
            .iter()
            .map(|candidate| candidate.as_ptr())
            .collect::<Vec<_>>();
        let candidate_lengths = candidates
            .iter()
            .map(|candidate| candidate.len())
            .collect::<Vec<_>>();
        let mut diagnostic = NativeDiagnosticHandle::null();
        let result = unsafe {
            phpc_native_value_text_membership_with_diagnostic(
                value,
                surface,
                candidate_ptrs.as_ptr(),
                candidate_lengths.as_ptr(),
                candidates.len(),
                case_insensitive,
                &mut diagnostic,
            )
        };
        if diagnostic.is_null() {
            Ok(result)
        } else {
            let message = diagnostic_message_for_test(diagnostic);
            unsafe { phpc_native_diagnostic_free(diagnostic) };
            Err(message)
        }
    }

    unsafe fn request_state_operation_for_test(
        request_state: NativeRequestStateHandle,
        operation_kind: u8,
        bag: &[u8],
        key: Option<&[u8]>,
    ) -> NativeRequestStateOperationResult {
        let (key_ptr, key_len) = key
            .map(|key| (key.as_ptr(), key.len()))
            .unwrap_or((std::ptr::null(), 0));
        unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                operation_kind,
                bag.as_ptr(),
                bag.len(),
                key_ptr,
                key_len,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        }
    }

    fn assert_request_state_value_for_test(
        request_state: NativeRequestStateHandle,
        bag: &[u8],
        key: &[u8],
        expected: Option<&[u8]>,
    ) {
        let expected_is_set = u8::from(expected.is_some());
        let presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                bag,
                Some(key),
            )
        };
        assert_eq!(presence.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE);
        assert_eq!(presence.is_set, expected_is_set);
        assert!(presence.value.is_null());
        assert!(presence.array.is_null());

        let value = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(key),
            )
        };
        assert_eq!(value.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(value.is_set, expected_is_set);
        assert_eq!(
            native_value_echo_bytes_for_test(value.value),
            expected.unwrap_or_default()
        );
        assert!(value.array.is_null());
        unsafe { phpc_native_value_free(value.value) };
    }

    #[test]
    fn native_request_state_operation_kind_maps_shared_abi_contract() {
        for (tag, expected, uses_keyed_scalar_snapshot) in [
            (
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                NativeRequestStateOperationKind::Value,
                true,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                NativeRequestStateOperationKind::Array,
                false,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                NativeRequestStateOperationKind::Presence,
                true,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                NativeRequestStateOperationKind::BagPresence,
                false,
            ),
        ] {
            let operation_kind = NativeRequestStateOperationKind::from_abi_tag(tag)
                .expect("request-state operation tag is supported");

            assert_eq!(operation_kind, expected);
            assert_eq!(
                operation_kind.uses_keyed_scalar_snapshot(),
                uses_keyed_scalar_snapshot
            );
        }

        assert_eq!(NativeRequestStateOperationKind::from_abi_tag(0), None);
        assert_eq!(NativeRequestStateOperationKind::from_abi_tag(99), None);
    }

    #[test]
    fn native_request_state_scalar_key_abi_coerces_lossless_php_key_family() {
        for (value, expected) in [
            (NativeScalarValue::null(), b"".as_slice()),
            (NativeScalarValue::bool(false), b"0".as_slice()),
            (NativeScalarValue::bool(true), b"1".as_slice()),
            (NativeScalarValue::int(-42), b"-42".as_slice()),
            (NativeScalarValue::float(42.0), b"42".as_slice()),
            (NativeScalarValue::float(-0.0), b"0".as_slice()),
        ] {
            let key = phpc_native_request_state_key_from_scalar(value);

            assert_eq!(key.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(native_byte_buffer_to_vec_for_test(key.buffer), expected);
        }

        for value in [
            NativeScalarValue::float(1.5),
            NativeScalarValue::float(f64::INFINITY),
            NativeScalarValue::float(f64::NAN),
        ] {
            let key = phpc_native_request_state_key_from_scalar(value);

            assert_eq!(
                key.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
            );
            assert_eq!(native_byte_buffer_to_vec_for_test(key.buffer), b"");
        }
    }

    #[test]
    fn native_request_state_operation_result_carries_key_resolution_status() {
        let request_state = phpc_native_request_state_empty();

        for operation_kind in [
            PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
        ] {
            for bag in [
                b"_GET".as_slice(),
                b"_POST".as_slice(),
                b"_REQUEST".as_slice(),
            ] {
                let result = unsafe {
                    phpc_native_request_state_superglobal_operation(
                        request_state,
                        operation_kind,
                        bag.as_ptr(),
                        bag.len(),
                        std::ptr::null(),
                        0,
                        PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION,
                    )
                };

                assert_eq!(result.result_kind, 0);
                assert_eq!(result.is_set, 0);
                assert_eq!(
                    result.status,
                    PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
                );
                assert!(result.value.is_null());
                assert!(result.array.is_null());
            }
        }

        let invalid_key_status = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET".as_ptr(),
                4,
                std::ptr::null(),
                0,
                0,
            )
        };
        assert_eq!(invalid_key_status.result_kind, 0);
        assert_eq!(
            invalid_key_status.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );

        let bag_with_failed_key = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_GET".as_ptr(),
                4,
                std::ptr::null(),
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION,
            )
        };
        assert_eq!(bag_with_failed_key.result_kind, 0);
        assert_eq!(
            bag_with_failed_key.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );

        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_keyed_snapshots_accept_scalar_key_family() {
        let request_state = phpc_native_request_state_empty();
        for (bag, key, value) in [
            (
                b"_SERVER".as_slice(),
                b"123".as_slice(),
                b"server-int".as_slice(),
            ),
            (b"_GET".as_slice(), b"0".as_slice(), b"get-zero".as_slice()),
            (
                b"_POST".as_slice(),
                b"-12".as_slice(),
                b"post-negative".as_slice(),
            ),
            (
                b"_REQUEST".as_slice(),
                b"42".as_slice(),
                b"request-int".as_slice(),
            ),
            (
                b"_COOKIE".as_slice(),
                b"01".as_slice(),
                b"cookie-leading-zero".as_slice(),
            ),
            (
                b"_ENV".as_slice(),
                b"APP_ENV".as_slice(),
                b"test".as_slice(),
            ),
        ] {
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_bytes(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value.as_ptr(),
                    value.len(),
                )
            });
        }

        for (bag, key, expected) in [
            (
                b"_SERVER".as_slice(),
                b"123".as_slice(),
                b"server-int".as_slice(),
            ),
            (b"_GET".as_slice(), b"0".as_slice(), b"get-zero".as_slice()),
            (
                b"_POST".as_slice(),
                b"-12".as_slice(),
                b"post-negative".as_slice(),
            ),
            (
                b"_REQUEST".as_slice(),
                b"42".as_slice(),
                b"request-int".as_slice(),
            ),
            (
                b"_ENV".as_slice(),
                b"APP_ENV".as_slice(),
                b"test".as_slice(),
            ),
        ] {
            let value = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(value.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
            assert_eq!(value.is_set, 1);
            assert_eq!(value.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(native_value_echo_bytes_for_test(value.value), expected);
            assert!(value.array.is_null());
            unsafe { phpc_native_value_free(value.value) };

            let presence = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(presence.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE);
            assert_eq!(presence.is_set, 1);
            assert_eq!(presence.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert!(presence.value.is_null());
            assert!(presence.array.is_null());
        }

        let leading_zero = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_COOKIE",
                Some(b"01"),
            )
        };
        assert_eq!(leading_zero.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(leading_zero.is_set, 1);
        assert_eq!(leading_zero.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(leading_zero.value),
            b"cookie-leading-zero"
        );
        unsafe { phpc_native_value_free(leading_zero.value) };

        let get_array = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_GET",
                None,
            )
        };
        assert_eq!(get_array.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
        assert_eq!(get_array.is_set, 1);

        let zero_key = unsafe { phpc_native_binary_string_from_bytes(b"0".as_ptr(), 1) };
        let zero = unsafe { phpc_native_array_read_string(get_array.array, zero_key) };
        assert_eq!(native_value_echo_bytes_for_test(zero), b"get-zero");

        unsafe { phpc_native_value_free(zero) };
        unsafe { phpc_native_string_free(zero_key) };
        unsafe { phpc_native_array_free(get_array.array) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_operation_statuses_cover_shared_bag_key_and_abi_boundaries() {
        let request_state = phpc_native_request_state_empty();
        for (bag, key, value) in [
            (b"_GET".as_slice(), b"alpha".as_slice(), b"one".as_slice()),
            (b"_POST".as_slice(), b"beta".as_slice(), b"two".as_slice()),
            (
                b"_COOKIE".as_slice(),
                &[0, b'k', 0xff][..],
                &[b'v', 0xfe][..],
            ),
        ] {
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_bytes(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value.as_ptr(),
                    value.len(),
                )
            });

            let value_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(value_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
            assert_eq!(value_result.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(value_result.is_set, 1);
            assert_eq!(native_value_echo_bytes_for_test(value_result.value), value);
            unsafe { phpc_native_request_state_operation_result_free(value_result) };

            let presence = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(presence.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE);
            assert_eq!(presence.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(presence.is_set, 1);

            let array = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                    bag,
                    None,
                )
            };
            assert_eq!(array.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
            assert_eq!(array.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(array.is_set, 1);
            assert_eq!(unsafe { phpc_native_array_len(array.array) }, 1);
            unsafe { phpc_native_request_state_operation_result_free(array) };
        }

        let missing = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(b"missing"),
            )
        };
        assert_eq!(missing.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(missing.status, PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY);
        assert_eq!(missing.is_set, 0);
        assert_eq!(native_value_echo_bytes_for_test(missing.value), b"");
        unsafe { phpc_native_request_state_operation_result_free(missing) };

        let missing_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_GET",
                Some(b"missing"),
            )
        };
        assert_eq!(
            missing_presence.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE
        );
        assert_eq!(
            missing_presence.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY
        );
        assert_eq!(missing_presence.is_set, 0);

        for (operation_kind, bag, key, expected_status) in [
            (
                99,
                b"_GET".as_slice(),
                Some(b"alpha".as_slice()),
                PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_OPERATION,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_GET".as_slice(),
                Some(b"alpha".as_slice()),
                PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_UNKNOWN".as_slice(),
                Some(b"alpha".as_slice()),
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNKNOWN_BAG,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_FILES".as_slice(),
                Some(b"upload".as_slice()),
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_BAG,
            ),
        ] {
            let result = unsafe {
                request_state_operation_for_test(request_state, operation_kind, bag, key)
            };
            assert_eq!(result.result_kind, 0);
            assert_eq!(result.status, expected_status);
            assert_eq!(result.is_set, 0);
            assert!(result.value.is_null());
            assert!(result.array.is_null());
        }

        let null_state = unsafe {
            request_state_operation_for_test(
                NativeRequestStateHandle::null(),
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_GET",
                Some(b"alpha"),
            )
        };
        assert_eq!(null_state.result_kind, 0);
        assert_eq!(
            null_state.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_NULL_STATE
        );
        assert_eq!(null_state.is_set, 0);

        unsafe { phpc_native_request_state_free(request_state) };
    }

    fn assert_native_reference_liveness(
        reference: NativeReferenceHandle,
        expected_is_null: bool,
        expected_is_empty: bool,
    ) {
        assert_eq!(
            unsafe { phpc_native_reference_is_null(reference) },
            expected_is_null
        );
        assert_eq!(
            unsafe { phpc_native_reference_is_empty(reference) },
            expected_is_empty
        );
    }

    fn assert_native_reference_state(
        reference: NativeReferenceHandle,
        expected_is_null: bool,
        expected_is_empty: bool,
        expected_echo: &[u8],
    ) {
        assert_native_reference_liveness(reference, expected_is_null, expected_is_empty);

        let value = unsafe { phpc_native_reference_read_value(reference) };
        assert!(!value.is_null());
        assert_eq!(native_value_echo_bytes_for_test(value), expected_echo);

        unsafe { phpc_native_value_free(value) };
    }

    fn assert_native_reference_state_for_case(
        label: &str,
        reference: NativeReferenceHandle,
        expected_is_null: bool,
        expected_is_empty: bool,
        expected_echo: &[u8],
    ) {
        assert_eq!(
            unsafe { phpc_native_reference_is_null(reference) },
            expected_is_null,
            "{label} is_null"
        );
        assert_eq!(
            unsafe { phpc_native_reference_is_empty(reference) },
            expected_is_empty,
            "{label} is_empty"
        );

        let value = unsafe { phpc_native_reference_read_value(reference) };
        assert!(!value.is_null(), "{label} read value");
        assert_eq!(
            native_value_echo_bytes_for_test(value),
            expected_echo,
            "{label} echo"
        );

        unsafe { phpc_native_value_free(value) };
    }

    fn write_native_reference_string_for_test(reference: NativeReferenceHandle, bytes: &[u8]) {
        let string = unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) };
        assert!(!string.is_null());
        let value = unsafe { phpc_native_value_from_string(string) };
        assert!(!value.is_null());

        assert!(unsafe { phpc_native_reference_write_value(reference, value) });

        unsafe { phpc_native_value_free(value) };
        unsafe { phpc_native_string_free(string) };
    }

    enum NativeReferenceScalarWriteForTest {
        AbiScalar(NativeScalarValue),
        StringValue(&'static [u8]),
    }

    struct NativeReferenceScalarWriteCase {
        label: &'static str,
        write: NativeReferenceScalarWriteForTest,
        expected_is_null: bool,
        expected_is_empty: bool,
        expected_echo: &'static [u8],
    }

    fn apply_native_reference_scalar_write_for_test(
        reference: NativeReferenceHandle,
        write: NativeReferenceScalarWriteForTest,
    ) {
        match write {
            NativeReferenceScalarWriteForTest::AbiScalar(value) => {
                assert!(unsafe { phpc_native_reference_write_scalar(reference, value) });
            }
            NativeReferenceScalarWriteForTest::StringValue(bytes) => {
                write_native_reference_string_for_test(reference, bytes);
            }
        }
    }

    #[test]
    fn echo_conversions_match_php_scalars_for_supported_values() {
        assert_eq!(Value::Null.echo_string(), "");
        assert_eq!(Value::Bool(false).echo_string(), "");
        assert_eq!(Value::Bool(true).echo_string(), "1");
        assert_eq!(Value::Int(42).echo_string(), "42");
        assert_eq!(Value::Float(1.5).echo_string(), "1.5");
        assert_eq!(Value::String("x".to_string()).echo_string(), "x");
    }

    #[test]
    fn native_scalar_abi_tags_are_stable() {
        assert_eq!(NativeScalarTag::Null as u8, 0);
        assert_eq!(NativeScalarTag::Bool as u8, 1);
        assert_eq!(NativeScalarTag::Int as u8, 2);
        assert_eq!(NativeScalarTag::Float as u8, 3);
    }

    #[test]
    fn native_scalar_abi_converts_to_runtime_values() {
        assert_eq!(phpc_native_null().to_value(), Value::Null);
        assert_eq!(phpc_native_bool(false).to_value(), Value::Bool(false));
        assert_eq!(phpc_native_bool(true).to_value(), Value::Bool(true));
        assert_eq!(phpc_native_int(-42).to_value(), Value::Int(-42));
        assert_eq!(phpc_native_float(1.5).to_value(), Value::Float(1.5));
    }

    #[test]
    fn native_string_truthy_abi_matches_php_byte_string_boundaries() {
        assert!(!unsafe { phpc_native_string_truthy(b"".as_ptr(), 0) });
        assert!(!unsafe { phpc_native_string_truthy(b"0".as_ptr(), 1) });
        assert!(unsafe { phpc_native_string_truthy(b"00".as_ptr(), 2) });
        assert!(unsafe { phpc_native_string_truthy(b"\0".as_ptr(), 1) });
        assert!(unsafe { phpc_native_string_truthy(b"hello".as_ptr(), 5) });
        assert!(!unsafe { phpc_native_string_truthy(std::ptr::null(), 1) });
    }

    #[test]
    fn native_scalar_abi_normalizes_bool_payloads() {
        let mut value = NativeScalarValue::bool(false);
        value.bool_value = 7;

        assert_eq!(value.tag(), NativeScalarTag::Bool);
        assert_eq!(value.to_value(), Value::Bool(true));
    }

    #[test]
    fn native_container_handle_shapes_are_pointer_sized_with_nullable_array_storage() {
        assert_eq!(
            std::mem::size_of::<NativeArrayHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeObjectHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeResourceHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeReferenceHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeRequestStateHandle>(),
            std::mem::size_of::<*mut ()>()
        );

        let array = phpc_native_array_null();
        let object = phpc_native_object_null();
        let resource = phpc_native_resource_null();
        let reference = phpc_native_reference_null();
        let request_state = phpc_native_request_state_null();

        assert!(array.is_null());
        assert!(object.is_null());
        assert!(resource.is_null());
        assert!(reference.is_null());
        assert!(request_state.is_null());
        assert!(phpc_native_array_is_null(array));
        assert!(phpc_native_object_is_null(object));
        assert!(phpc_native_resource_is_null(resource));
        assert!(unsafe { phpc_native_reference_is_null(reference) });
        assert!(phpc_native_request_state_is_null(request_state));

        let array = phpc_native_array_empty();
        assert!(!array.is_null());
        assert!(!phpc_native_array_is_null(array));
        assert_eq!(unsafe { phpc_native_array_len(array) }, 0);
        assert!(!unsafe { phpc_native_array_is_truthy(array) });
        unsafe { phpc_native_array_free(array) };

        assert_eq!(
            unsafe { phpc_native_array_len(NativeArrayHandle::null()) },
            0
        );
        assert!(!unsafe { phpc_native_array_is_truthy(NativeArrayHandle::null()) });
        unsafe { phpc_native_array_free(NativeArrayHandle::null()) };
    }

    #[test]
    fn native_request_state_superglobal_boundaries_are_bag_key_driven_and_binary_safe() {
        let request_state = phpc_native_request_state_empty();
        assert!(!request_state.is_null());
        assert!(!phpc_native_request_state_is_null(request_state));

        let bag = b"_GET";
        let key = [0xff, b'k', 0];
        let value = [b'v', 0xfe];
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_bytes(
                request_state,
                bag.as_ptr(),
                bag.len(),
                key.as_ptr(),
                key.len(),
                value.as_ptr(),
                value.len(),
            )
        });

        assert!(unsafe {
            phpc_native_request_state_superglobal_is_set(
                request_state,
                bag.as_ptr(),
                bag.len(),
                key.as_ptr(),
                key.len(),
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_superglobal_is_set(
                request_state,
                bag.as_ptr(),
                bag.len(),
                b"missing".as_ptr(),
                7,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_superglobal_is_set(
                request_state,
                b"_UNKNOWN".as_ptr(),
                b"_UNKNOWN".len(),
                key.as_ptr(),
                key.len(),
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_insert_superglobal_bytes(
                request_state,
                b"_UNKNOWN".as_ptr(),
                b"_UNKNOWN".len(),
                key.as_ptr(),
                key.len(),
                value.as_ptr(),
                value.len(),
            )
        });

        let string = unsafe {
            phpc_native_request_state_superglobal_string(
                request_state,
                bag.as_ptr(),
                bag.len(),
                key.as_ptr(),
                key.len(),
            )
        };
        assert_eq!(native_string_bytes_for_test(string), value);

        let runtime_value = unsafe {
            phpc_native_request_state_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                key.as_ptr(),
                key.len(),
            )
        };
        assert_eq!(
            unsafe { runtime_value.as_ref() },
            Some(&Value::BinaryString(value.to_vec()))
        );
        assert_eq!(native_value_echo_bytes_for_test(runtime_value), value);

        let snapshot = unsafe {
            phpc_native_request_state_superglobal_array(request_state, bag.as_ptr(), bag.len())
        };
        assert!(!snapshot.is_null());
        assert_eq!(unsafe { phpc_native_array_len(snapshot) }, 1);
        let key_handle = unsafe { phpc_native_binary_string_from_bytes(key.as_ptr(), key.len()) };
        let read = unsafe { phpc_native_array_read_string(snapshot, key_handle) };
        assert_eq!(native_value_echo_bytes_for_test(read), value);

        let empty_snapshot = unsafe {
            phpc_native_request_state_superglobal_array(
                request_state,
                b"_FILES".as_ptr(),
                b"_FILES".len(),
            )
        };
        assert!(!empty_snapshot.is_null());
        assert_eq!(unsafe { phpc_native_array_len(empty_snapshot) }, 0);

        let invalid_snapshot = unsafe {
            phpc_native_request_state_superglobal_array(
                request_state,
                b"_UNSET".as_ptr(),
                b"_UNSET".len(),
            )
        };
        assert!(invalid_snapshot.is_null());

        let invalid = unsafe {
            phpc_native_request_state_superglobal_string(
                request_state,
                std::ptr::null(),
                1,
                key.as_ptr(),
                key.len(),
            )
        };
        assert!(invalid.is_null());

        unsafe { phpc_native_string_free(invalid) };
        unsafe { phpc_native_array_free(invalid_snapshot) };
        unsafe { phpc_native_array_free(empty_snapshot) };
        unsafe { phpc_native_value_free(read) };
        unsafe { phpc_native_string_free(key_handle) };
        unsafe { phpc_native_array_free(snapshot) };
        unsafe { phpc_native_value_free(runtime_value) };
        unsafe { phpc_native_string_free(string) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_operation_carrier_shares_lookup_contracts() {
        let request_state = phpc_native_request_state_empty();
        let first_bag = b"_GET";
        let first_key = [0, b'a'];
        let first_value = [0xff, b'a'];
        let second_bag = b"_POST";
        let second_key = b"name";
        let second_value = b"text";
        let empty_bag = b"_COOKIE";
        let empty_key = b"";
        let empty_value = [b'z', 0xfe];
        let env_bag = b"_ENV";
        let env_key = b"APP_ENV";
        let env_value = b"test";
        let rows: [(&[u8], &[u8], &[u8]); 4] = [
            (first_bag, &first_key, &first_value),
            (second_bag, second_key, second_value),
            (empty_bag, empty_key, &empty_value),
            (env_bag, env_key, env_value),
        ];

        for (bag, key, value) in rows {
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_bytes(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value.as_ptr(),
                    value.len(),
                )
            });

            let presence = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(presence.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE);
            assert_eq!(presence.is_set, 1);
            assert!(presence.value.is_null());
            assert!(presence.array.is_null());

            let value_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(value_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
            assert_eq!(value_result.is_set, 1);
            assert_eq!(native_value_echo_bytes_for_test(value_result.value), value);
            assert!(value_result.array.is_null());
            unsafe { phpc_native_value_free(value_result.value) };

            let value_handle = unsafe {
                phpc_native_request_state_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                )
            };
            assert_eq!(native_value_echo_bytes_for_test(value_handle), value);
            unsafe { phpc_native_value_free(value_handle) };

            let string_handle = unsafe {
                phpc_native_request_state_superglobal_string(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                )
            };
            assert_eq!(native_string_bytes_for_test(string_handle), value);
            unsafe { phpc_native_string_free(string_handle) };

            let bag_presence = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                    bag,
                    None,
                )
            };
            assert_eq!(
                bag_presence.result_kind,
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE
            );
            assert_eq!(bag_presence.is_set, 1);
            assert!(bag_presence.value.is_null());
            assert!(bag_presence.array.is_null());
        }

        for (bag, key, value) in rows {
            let array_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                    bag,
                    None,
                )
            };
            assert_eq!(array_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
            assert_eq!(array_result.is_set, 1);
            assert!(array_result.value.is_null());
            assert!(!array_result.array.is_null());
            assert_eq!(unsafe { phpc_native_array_len(array_result.array) }, 1);

            let snapshot = unsafe {
                phpc_native_request_state_superglobal_array(request_state, bag.as_ptr(), bag.len())
            };
            let key_handle =
                unsafe { phpc_native_binary_string_from_bytes(key.as_ptr(), key.len()) };
            let operation_read =
                unsafe { phpc_native_array_read_string(array_result.array, key_handle) };
            assert_eq!(native_value_echo_bytes_for_test(operation_read), value);
            let read = unsafe { phpc_native_array_read_string(snapshot, key_handle) };
            assert_eq!(native_value_echo_bytes_for_test(read), value);
            unsafe { phpc_native_value_free(read) };
            unsafe { phpc_native_value_free(operation_read) };
            unsafe { phpc_native_string_free(key_handle) };
            unsafe { phpc_native_array_free(snapshot) };
            unsafe { phpc_native_array_free(array_result.array) };
        }

        let missing_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                first_bag,
                Some(b"missing"),
            )
        };
        assert_eq!(
            missing_presence.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE
        );
        assert_eq!(missing_presence.is_set, 0);

        let missing_value = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                first_bag,
                Some(b"missing"),
            )
        };
        assert_eq!(
            missing_value.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_VALUE
        );
        assert_eq!(missing_value.is_set, 0);
        assert_eq!(native_value_echo_bytes_for_test(missing_value.value), b"");
        unsafe { phpc_native_value_free(missing_value.value) };

        let missing_bag = b"_FILES";
        let missing_bag_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                missing_bag,
                None,
            )
        };
        assert_eq!(
            missing_bag_presence.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE
        );
        assert_eq!(missing_bag_presence.is_set, 1);
        assert!(missing_bag_presence.value.is_null());
        assert!(missing_bag_presence.array.is_null());

        let missing_bag_array = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                missing_bag,
                None,
            )
        };
        assert_eq!(
            missing_bag_array.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_ARRAY
        );
        assert_eq!(missing_bag_array.is_set, 1);
        assert!(missing_bag_array.value.is_null());
        assert!(!missing_bag_array.array.is_null());
        assert_eq!(unsafe { phpc_native_array_len(missing_bag_array.array) }, 0);
        unsafe { phpc_native_array_free(missing_bag_array.array) };

        let first_bag_empty_key_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                first_bag,
                Some(b""),
            )
        };
        let first_bag_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                first_bag,
                None,
            )
        };
        assert_eq!(first_bag_empty_key_presence.is_set, 0);
        assert_eq!(first_bag_presence.is_set, 1);

        let invalid_kind = unsafe {
            request_state_operation_for_test(
                request_state,
                99,
                first_bag,
                Some(first_key.as_slice()),
            )
        };
        assert_eq!(invalid_kind.result_kind, 0);
        assert_eq!(invalid_kind.is_set, 0);
        assert!(invalid_kind.value.is_null());
        assert!(invalid_kind.array.is_null());

        let invalid_bag = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                std::ptr::null(),
                1,
                std::ptr::null(),
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(invalid_bag.result_kind, 0);
        assert!(invalid_bag.array.is_null());

        let invalid_bag_presence = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                std::ptr::null(),
                1,
                std::ptr::null(),
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(invalid_bag_presence.result_kind, 0);
        assert_eq!(invalid_bag_presence.is_set, 0);

        let null_state = unsafe {
            request_state_operation_for_test(
                NativeRequestStateHandle::null(),
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                first_bag,
                Some(first_key.as_slice()),
            )
        };
        assert_eq!(null_state.result_kind, 0);
        assert_eq!(null_state.is_set, 0);

        let null_state_bag = unsafe {
            request_state_operation_for_test(
                NativeRequestStateHandle::null(),
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                first_bag,
                None,
            )
        };
        assert_eq!(null_state_bag.result_kind, 0);
        assert_eq!(null_state_bag.is_set, 0);

        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_operation_result_cleanup_and_bag_key_contract_are_shared() {
        let request_state = phpc_native_request_state_empty();
        let rows: [(&[u8], &[u8], &[u8]); 3] = [
            (b"_GET", b"preview", b"true"),
            (b"_POST", b"action", b"save"),
            (b"_COOKIE", &[0, b'k', 0xff], &[b'v', 0xfe]),
        ];

        for (bag, key, value) in rows {
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_bytes(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value.as_ptr(),
                    value.len(),
                )
            });

            let value_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(value_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
            assert_eq!(value_result.is_set, 1);
            assert_eq!(native_value_echo_bytes_for_test(value_result.value), value);
            assert!(value_result.array.is_null());
            unsafe { phpc_native_request_state_operation_result_free(value_result) };

            let array_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                    bag,
                    None,
                )
            };
            assert_eq!(array_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
            assert_eq!(array_result.is_set, 1);
            assert!(array_result.value.is_null());
            assert!(!array_result.array.is_null());
            assert_eq!(unsafe { phpc_native_array_len(array_result.array) }, 1);
            unsafe { phpc_native_request_state_operation_result_free(array_result) };

            let presence_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(
                presence_result.result_kind,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE
            );
            assert_eq!(presence_result.is_set, 1);
            unsafe { phpc_native_request_state_operation_result_free(presence_result) };

            for operation_kind in [
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
            ] {
                let keyed_bag_result = unsafe {
                    request_state_operation_for_test(request_state, operation_kind, bag, Some(key))
                };
                assert_eq!(keyed_bag_result.result_kind, 0);
                assert_eq!(keyed_bag_result.is_set, 0);
                assert!(keyed_bag_result.value.is_null());
                assert!(keyed_bag_result.array.is_null());
                unsafe { phpc_native_request_state_operation_result_free(keyed_bag_result) };
            }
        }

        unsafe {
            phpc_native_request_state_operation_result_free(
                NativeRequestStateOperationResult::null(),
            )
        };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_cli_seed_from_request_inputs_populates_scalar_bags() {
        let default_request_state = phpc_native_request_state_cli_seed();
        assert_request_state_value_for_test(
            default_request_state,
            b"_SERVER",
            b"SCRIPT_NAME",
            Some(b"/index.php"),
        );
        unsafe { phpc_native_request_state_free(default_request_state) };

        let request_body = b"action=save&space=hello+world&dup=post&items[]=skip".to_vec();
        let request_state = NativeRequestStateHandle {
            ptr: Box::into_raw(Box::new(NativeRequestState::cli_seed_from(
                NativeRequestSeed {
                    query_string: Some(
                        b"preview=true&name=PHP%20Core&encoded=a%2Bb&dup=old&dup=new".to_vec(),
                    ),
                    request_body: Some(request_body.clone()),
                    request_method: Some(b"POST".to_vec()),
                    content_type: Some(
                        b"application/x-www-form-urlencoded; charset=UTF-8".to_vec(),
                    ),
                    cookie_header: Some(b"test_cookie=Cookie+check; dotted.name=value".to_vec()),
                },
            ))),
        };

        assert_request_state_value_for_test(
            request_state,
            b"_SERVER",
            b"REQUEST_METHOD",
            Some(b"POST"),
        );
        assert_request_state_value_for_test(
            request_state,
            b"_SERVER",
            b"QUERY_STRING",
            Some(b"preview=true&name=PHP%20Core&encoded=a%2Bb&dup=old&dup=new"),
        );
        assert_request_state_value_for_test(
            request_state,
            b"_SERVER",
            b"CONTENT_TYPE",
            Some(b"application/x-www-form-urlencoded; charset=UTF-8"),
        );
        assert_request_state_value_for_test(
            request_state,
            b"_SERVER",
            b"CONTENT_LENGTH",
            Some(request_body.len().to_string().as_bytes()),
        );
        assert_request_state_value_for_test(
            request_state,
            b"_SERVER",
            b"HTTP_COOKIE",
            Some(b"test_cookie=Cookie+check; dotted.name=value"),
        );

        for (bag, key, expected) in [
            (
                b"_GET".as_slice(),
                b"preview".as_slice(),
                b"true".as_slice(),
            ),
            (
                b"_GET".as_slice(),
                b"name".as_slice(),
                b"PHP Core".as_slice(),
            ),
            (b"_GET".as_slice(), b"encoded".as_slice(), b"a+b".as_slice()),
            (b"_GET".as_slice(), b"dup".as_slice(), b"new".as_slice()),
            (
                b"_POST".as_slice(),
                b"action".as_slice(),
                b"save".as_slice(),
            ),
            (
                b"_POST".as_slice(),
                b"space".as_slice(),
                b"hello world".as_slice(),
            ),
            (b"_POST".as_slice(), b"dup".as_slice(), b"post".as_slice()),
            (
                b"_REQUEST".as_slice(),
                b"preview".as_slice(),
                b"true".as_slice(),
            ),
            (
                b"_REQUEST".as_slice(),
                b"action".as_slice(),
                b"save".as_slice(),
            ),
            (
                b"_REQUEST".as_slice(),
                b"dup".as_slice(),
                b"post".as_slice(),
            ),
            (
                b"_COOKIE".as_slice(),
                b"test_cookie".as_slice(),
                b"Cookie check".as_slice(),
            ),
            (
                b"_COOKIE".as_slice(),
                b"dotted_name".as_slice(),
                b"value".as_slice(),
            ),
        ] {
            assert_request_state_value_for_test(request_state, bag, key, Some(expected));
        }

        for (bag, key) in [
            (b"_GET".as_slice(), b"items".as_slice()),
            (b"_POST".as_slice(), b"items".as_slice()),
            (b"_REQUEST".as_slice(), b"test_cookie".as_slice()),
        ] {
            assert_request_state_value_for_test(request_state, bag, key, None);
        }

        let get_array = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_GET",
                None,
            )
        };
        assert_eq!(get_array.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
        assert_eq!(get_array.is_set, 1);
        assert!(unsafe { phpc_native_array_len(get_array.array) } > 0);
        let get_name_key =
            unsafe { phpc_native_binary_string_from_bytes(b"name".as_ptr(), b"name".len()) };
        let get_name = unsafe { phpc_native_array_read_string(get_array.array, get_name_key) };
        assert_eq!(native_value_echo_bytes_for_test(get_name), b"PHP Core");
        unsafe { phpc_native_value_free(get_name) };
        unsafe { phpc_native_string_free(get_name_key) };
        unsafe { phpc_native_array_free(get_array.array) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_operations_enforce_superglobal_bag_policy() {
        let mut seeded = NativeRequestState::cli_seed_from(NativeRequestSeed::default());
        seeded.insert_superglobal_value(NativeRequestStateBag::Get, b"preview", b"true".to_vec());
        seeded.insert_superglobal_value(
            NativeRequestStateBag::Files,
            b"async-upload",
            b"plugin.zip".to_vec(),
        );
        seeded.insert_superglobal_value(
            NativeRequestStateBag::Session,
            b"id",
            b"session-id".to_vec(),
        );
        seeded.insert_superglobal_value(NativeRequestStateBag::Env, b"APP_ENV", b"test".to_vec());
        let request_state = NativeRequestStateHandle {
            ptr: Box::into_raw(Box::new(seeded)),
        };

        let get_value = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(b"preview"),
            )
        };
        assert_eq!(get_value.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(get_value.is_set, 1);
        assert_eq!(native_value_echo_bytes_for_test(get_value.value), b"true");
        unsafe { phpc_native_value_free(get_value.value) };

        for (bag, key) in [
            (b"_FILES".as_slice(), b"async-upload".as_slice()),
            (b"_SESSION".as_slice(), b"id".as_slice()),
            (b"_UNKNOWN".as_slice(), b"slot".as_slice()),
        ] {
            let value = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(value.result_kind, 0);
            assert_eq!(value.is_set, 0);
            assert!(value.value.is_null());
            assert!(value.array.is_null());

            let presence = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                    bag,
                    Some(key),
                )
            };
            assert_eq!(presence.result_kind, 0);
            assert_eq!(presence.is_set, 0);
            assert!(presence.value.is_null());
            assert!(presence.array.is_null());
        }

        for (bag, key, expected) in [
            (
                b"_FILES".as_slice(),
                b"async-upload".as_slice(),
                b"plugin.zip".as_slice(),
            ),
            (
                b"_SESSION".as_slice(),
                b"id".as_slice(),
                b"session-id".as_slice(),
            ),
            (
                b"_ENV".as_slice(),
                b"APP_ENV".as_slice(),
                b"test".as_slice(),
            ),
        ] {
            let array_result = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                    bag,
                    None,
                )
            };
            assert_eq!(array_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
            assert_eq!(array_result.is_set, 1);
            assert!(!array_result.array.is_null());
            assert_eq!(unsafe { phpc_native_array_len(array_result.array) }, 1);
            let key_handle =
                unsafe { phpc_native_binary_string_from_bytes(key.as_ptr(), key.len()) };
            let value = unsafe { phpc_native_array_read_string(array_result.array, key_handle) };
            assert_eq!(native_value_echo_bytes_for_test(value), expected);
            unsafe { phpc_native_value_free(value) };
            unsafe { phpc_native_string_free(key_handle) };
            unsafe { phpc_native_array_free(array_result.array) };
        }

        for bag in [
            b"_SERVER".as_slice(),
            b"_GET".as_slice(),
            b"_POST".as_slice(),
            b"_COOKIE".as_slice(),
            b"_REQUEST".as_slice(),
            b"_FILES".as_slice(),
            b"_SESSION".as_slice(),
            b"_ENV".as_slice(),
        ] {
            let presence = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                    bag,
                    None,
                )
            };
            assert_eq!(
                presence.result_kind,
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE
            );
            assert_eq!(presence.is_set, 1);
            assert!(presence.value.is_null());
            assert!(presence.array.is_null());
        }

        let unknown_array = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_UNKNOWN",
                None,
            )
        };
        assert_eq!(unknown_array.result_kind, 0);
        assert!(unknown_array.array.is_null());

        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_object_class_metadata_handles_cover_null_free_and_name_smoke() {
        assert_eq!(
            std::mem::size_of::<NativeClassMetadataHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeObjectHandle>(),
            std::mem::size_of::<*mut ()>()
        );

        let null_class = phpc_native_class_metadata_null();
        assert!(null_class.is_null());
        assert!(phpc_native_class_metadata_is_null(null_class));
        assert_eq!(
            unsafe { phpc_native_class_metadata_name_len(null_class) },
            0
        );
        assert_eq!(
            native_byte_buffer_to_vec_for_test(unsafe {
                phpc_native_class_metadata_name_clone_bytes(null_class)
            }),
            b""
        );
        unsafe { phpc_native_class_metadata_free(null_class) };

        let name = b"Widget";
        let class = unsafe { phpc_native_class_metadata_from_name(name.as_ptr(), name.len()) };
        assert!(!class.is_null());
        assert!(!phpc_native_class_metadata_is_null(class));
        assert_eq!(
            unsafe { phpc_native_class_metadata_name_len(class) },
            name.len()
        );
        assert_eq!(
            native_byte_buffer_to_vec_for_test(unsafe {
                phpc_native_class_metadata_name_clone_bytes(class)
            }),
            name
        );

        assert!(unsafe { phpc_native_class_metadata_from_name(std::ptr::null(), 0) }.is_null());
        assert!(
            unsafe { phpc_native_class_metadata_from_name(std::ptr::null(), name.len()) }.is_null()
        );

        unsafe { phpc_native_class_metadata_free(class) };

        let string = unsafe { phpc_native_string_from_bytes(name.as_ptr(), name.len()) };
        let class = unsafe { phpc_native_class_metadata_from_string(string) };
        unsafe { phpc_native_string_free(string) };
        assert!(!class.is_null());
        assert_eq!(
            native_byte_buffer_to_vec_for_test(unsafe {
                phpc_native_class_metadata_name_clone_bytes(class)
            }),
            name
        );
        unsafe { phpc_native_class_metadata_free(class) };

        let empty = unsafe { phpc_native_string_from_bytes(std::ptr::null(), 0) };
        assert!(unsafe { phpc_native_class_metadata_from_string(empty) }.is_null());
        unsafe { phpc_native_string_free(empty) };

        let invalid = [0xff];
        let invalid_name =
            unsafe { phpc_native_string_from_bytes(invalid.as_ptr(), invalid.len()) };
        assert!(unsafe { phpc_native_class_metadata_from_string(invalid_name) }.is_null());
        unsafe { phpc_native_string_free(invalid_name) };

        assert!(
            unsafe { phpc_native_class_metadata_from_string(NativeStringHandle::null()) }.is_null()
        );
    }

