    #[test]
    fn native_array_clone_owns_independent_top_level_storage() {
        let source = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_write_int_scalar(source, 0, phpc_native_int(10)) });
        let clone = unsafe { phpc_native_array_clone(source) };
        assert!(!clone.is_null());

        assert!(unsafe { phpc_native_array_write_int_scalar(source, 0, phpc_native_int(20)) });
        assert!(unsafe { phpc_native_array_write_int_scalar(source, 1, phpc_native_int(30)) });
        assert!(unsafe { phpc_native_array_write_int_scalar(clone, 2, phpc_native_int(40)) });

        let source_zero = unsafe { phpc_native_array_read_int(source, 0) };
        let source_one = unsafe { phpc_native_array_read_int(source, 1) };
        let source_two = unsafe { phpc_native_array_read_int(source, 2) };
        let clone_zero = unsafe { phpc_native_array_read_int(clone, 0) };
        let clone_one = unsafe { phpc_native_array_read_int(clone, 1) };
        let clone_two = unsafe { phpc_native_array_read_int(clone, 2) };

        assert_eq!(native_value_echo_bytes_for_test(source_zero), b"20");
        assert_eq!(native_value_echo_bytes_for_test(source_one), b"30");
        assert!(source_two.is_null());
        assert_eq!(native_value_echo_bytes_for_test(clone_zero), b"10");
        assert!(clone_one.is_null());
        assert_eq!(native_value_echo_bytes_for_test(clone_two), b"40");

        unsafe { phpc_native_value_free(source_zero) };
        unsafe { phpc_native_value_free(source_one) };
        unsafe { phpc_native_value_free(source_two) };
        unsafe { phpc_native_value_free(clone_zero) };
        unsafe { phpc_native_value_free(clone_one) };
        unsafe { phpc_native_value_free(clone_two) };
        unsafe { phpc_native_array_free(source) };
        unsafe { phpc_native_array_free(clone) };
    }

    #[test]
    fn native_array_clone_detaches_nested_array_values_on_mutation() {
        let child = phpc_native_array_empty();
        let mut parent = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_write_int_scalar(child, 0, phpc_native_int(5)) });
        let nested_value = unsafe { phpc_native_value_from_array_clone(child) };
        assert!(unsafe { phpc_native_array_write_int_value(parent, 9, nested_value) });

        let clone = unsafe { phpc_native_array_clone(parent) };
        unsafe { phpc_native_value_free(nested_value) };
        unsafe { phpc_native_array_free(child) };

        let Some(parent_array) = (unsafe { parent.as_mut() }) else {
            panic!("parent array should be non-null");
        };
        let Some(parent_slot) = parent_array.value.get_slot_mut(9) else {
            panic!("parent should contain nested array slot");
        };
        let Value::Array(parent_nested) = parent_slot.value_mut() else {
            panic!("parent slot should contain a nested array");
        };
        parent_nested.insert(0, Value::Int(99));
        parent_nested.insert(1, Value::Int(100));

        let Some(clone_array) = (unsafe { clone.as_ref() }) else {
            panic!("clone array should be non-null");
        };
        let Some(Value::Array(clone_nested)) = clone_array.value.get(9) else {
            panic!("clone should contain nested array slot");
        };
        assert_eq!(clone_nested.get(0), Some(&Value::Int(5)));
        assert_eq!(clone_nested.get(1), None);

        let Some(Value::Array(parent_nested)) = parent_array.value.get(9) else {
            panic!("parent should still contain nested array slot");
        };
        assert_eq!(parent_nested.get(0), Some(&Value::Int(99)));
        assert_eq!(parent_nested.get(1), Some(&Value::Int(100)));

        unsafe { phpc_native_array_free(parent) };
        unsafe { phpc_native_array_free(clone) };
    }

