    #[test]
    fn native_array_int_key_unset_deletes_values_and_missing_keys_are_noops() {
        let array = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_write_int_scalar(array, 1, phpc_native_int(10)) });
        assert!(unsafe { phpc_native_array_write_int_scalar(array, 2, phpc_native_null()) });
        assert_eq!(unsafe { phpc_native_array_len(array) }, 2);

        assert!(unsafe { phpc_native_array_unset_int(array, 1) });
        assert!(!unsafe { phpc_native_array_key_exists_int(array, 1) });
        assert!(!unsafe { phpc_native_array_isset_int(array, 1) });
        assert!(unsafe { phpc_native_array_read_int(array, 1) }.is_null());
        assert_eq!(unsafe { phpc_native_array_len(array) }, 1);

        assert!(unsafe { phpc_native_array_key_exists_int(array, 2) });
        assert!(!unsafe { phpc_native_array_isset_int(array, 2) });
        assert!(unsafe { phpc_native_array_unset_int(array, 2) });
        assert!(!unsafe { phpc_native_array_key_exists_int(array, 2) });
        assert!(!unsafe { phpc_native_array_isset_int(array, 2) });
        assert!(unsafe { phpc_native_array_read_int(array, 2) }.is_null());

        assert!(unsafe { phpc_native_array_unset_int(array, 404) });
        assert_eq!(unsafe { phpc_native_array_len(array) }, 0);
        assert!(!unsafe { phpc_native_array_unset_int(NativeArrayHandle::null(), 1) });

        unsafe { phpc_native_array_free(array) };
    }

