    #[test]
    fn native_array_value_clone_owns_independent_array_snapshot() {
        let array = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_append_scalar(array, phpc_native_int(11)) });
        let value = unsafe { phpc_native_value_from_array_clone(array) };
        assert!(!value.is_null());

        assert!(unsafe { phpc_native_array_append_scalar(array, phpc_native_int(22)) });
        assert_eq!(unsafe { phpc_native_array_len(array) }, 2);

        let Some(Value::Array(cloned_array)) = (unsafe { value.as_ref() }) else {
            panic!("array clone should wrap a Value::Array");
        };
        assert_eq!(cloned_array.len(), 1);
        assert_eq!(cloned_array.get(0), Some(&Value::Int(11)));
        assert_eq!(native_value_echo_bytes_for_test(value), b"Array");

        unsafe { phpc_native_value_free(value) };
        unsafe { phpc_native_array_free(array) };
    }

    #[test]
    fn native_array_value_clone_survives_original_array_free() {
        let array = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_append_scalar(array, phpc_native_int(7)) });
        let value = unsafe { phpc_native_value_from_array_clone(array) };
        unsafe { phpc_native_array_free(array) };

        let Some(Value::Array(cloned_array)) = (unsafe { value.as_ref() }) else {
            panic!("array clone should remain owned by the value handle");
        };
        assert_eq!(cloned_array.get(0), Some(&Value::Int(7)));
        assert_eq!(native_value_echo_bytes_for_test(value), b"Array");

        unsafe { phpc_native_value_free(value) };
        unsafe { phpc_native_value_free(NativeValueHandle::null()) };
    }

    #[test]
    fn native_array_value_clone_can_be_read_after_append_by_clone() {
        let source = phpc_native_array_empty();
        let outer = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_append_scalar(source, phpc_native_int(5)) });
        let value = unsafe { phpc_native_value_from_array_clone(source) };

        assert!(unsafe { phpc_native_array_append_value(outer, value) });
        unsafe { phpc_native_value_free(value) };
        unsafe { phpc_native_array_free(source) };

        let read = unsafe { phpc_native_array_read_int(outer, 0) };
        assert_eq!(native_value_echo_bytes_for_test(read), b"Array");
        let Some(Value::Array(read_array)) = (unsafe { read.as_ref() }) else {
            panic!("read slot should be the cloned array value");
        };
        assert_eq!(read_array.get(0), Some(&Value::Int(5)));

        unsafe { phpc_native_value_free(read) };
        unsafe { phpc_native_array_free(outer) };
    }

