    #[test]
    fn native_value_truthy_diagnostic_boundary_matches_value_truthiness_families() {
        let empty_array = PhpArray::new();
        let mut filled_array = PhpArray::new();
        filled_array
            .append(Value::BinaryString(vec![b'v', 0xff]))
            .unwrap();

        let cases = [
            (
                "null",
                phpc_native_value_from_scalar(phpc_native_null()),
                false,
            ),
            (
                "false",
                phpc_native_value_from_scalar(phpc_native_bool(false)),
                false,
            ),
            (
                "true",
                phpc_native_value_from_scalar(phpc_native_bool(true)),
                true,
            ),
            (
                "int-zero",
                phpc_native_value_from_scalar(phpc_native_int(0)),
                false,
            ),
            (
                "int-nonzero",
                phpc_native_value_from_scalar(phpc_native_int(-3)),
                true,
            ),
            (
                "float-zero",
                phpc_native_value_from_scalar(phpc_native_float(0.0)),
                false,
            ),
            (
                "text-zero",
                NativeValueHandle::from_value(Value::String("0".to_string())),
                false,
            ),
            (
                "text-value",
                NativeValueHandle::from_value(Value::String("php".to_string())),
                true,
            ),
            (
                "binary-zero",
                NativeValueHandle::from_value(Value::BinaryString(b"0".to_vec())),
                false,
            ),
            (
                "binary-nul",
                NativeValueHandle::from_value(Value::BinaryString(vec![0])),
                true,
            ),
            (
                "empty-array",
                NativeValueHandle::from_value(Value::Array(empty_array)),
                false,
            ),
            (
                "filled-array",
                NativeValueHandle::from_value(Value::Array(filled_array)),
                true,
            ),
        ];

        for (label, handle, expected) in cases {
            let mut diagnostic = NativeDiagnosticHandle::null();
            assert_eq!(
                unsafe { phpc_native_value_truthy_with_diagnostic(handle, &mut diagnostic) },
                expected,
                "{label}"
            );
            assert!(diagnostic.is_null(), "{label}");
            assert_eq!(
                unsafe { phpc_native_value_truthy(handle) },
                expected,
                "{label}"
            );
            unsafe { phpc_native_value_free(handle) };
        }

        let mut null_diagnostic = NativeDiagnosticHandle::null();
        assert!(!unsafe {
            phpc_native_value_truthy_with_diagnostic(
                NativeValueHandle::null(),
                &mut null_diagnostic,
            )
        });
        assert_eq!(
            diagnostic_message_for_test(null_diagnostic),
            b"invalid string conversion: native truthiness conversion failed: value handle is null"
        );
        unsafe { phpc_native_diagnostic_free(null_diagnostic) };

        assert!(!unsafe {
            phpc_native_value_truthy_with_diagnostic(
                NativeValueHandle::null(),
                std::ptr::null_mut(),
            )
        });
    }

    #[test]
    fn native_value_int_conversion_boundary_covers_scalar_string_results_offsets_and_diagnostics() {
        let mut diagnostic = NativeDiagnosticHandle::null();

        let binary_number = NativeValueHandle::from_value(Value::BinaryString(b" 17 ".to_vec()));
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(binary_number, &mut diagnostic) },
            17
        );
        assert!(diagnostic.is_null());

        let text_number = NativeValueHandle::from_value(Value::String("2.9".to_string()));
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(text_number, &mut diagnostic) },
            2
        );
        assert!(diagnostic.is_null());

        let float_number = phpc_native_value_from_scalar(phpc_native_float(3.7));
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(float_number, &mut diagnostic) },
            3
        );
        assert!(diagnostic.is_null());

        let reversed_source = unsafe { phpc_native_binary_value_from_bytes(b"24".as_ptr(), 2) };
        let reversed = unsafe {
            phpc_native_value_string_result_operation_with_diagnostic(
                reversed_source,
                NativeValueHandle::null(),
                NativeValueHandle::null(),
                0,
                0,
                0,
                NativeStringResultOperation::Reverse as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(reversed, &mut diagnostic) },
            42
        );
        assert!(diagnostic.is_null());

        let offset_source =
            unsafe { phpc_native_binary_value_from_bytes(b"A7".as_ptr(), b"A7".len()) };
        let offset = phpc_native_value_from_scalar(phpc_native_int(1));
        let offset_read = unsafe {
            phpc_native_value_offset_operation_with_diagnostic(
                offset_source,
                offset,
                NativeStringOffsetOperation::Read as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(offset_read, &mut diagnostic) },
            7
        );
        assert!(diagnostic.is_null());

        let non_numeric = NativeValueHandle::from_value(Value::BinaryString(b"17x".to_vec()));
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(non_numeric, &mut diagnostic) },
            0
        );
        assert_eq!(
            diagnostic_message_for_test(diagnostic),
            b"invalid string conversion: native integer argument conversion failed: expected numeric string"
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        diagnostic = NativeDiagnosticHandle::null();

        let array = phpc_native_array_empty();
        let array_value = unsafe { phpc_native_value_from_array_clone(array) };
        assert_eq!(
            unsafe { phpc_native_value_to_int_with_diagnostic(array_value, &mut diagnostic) },
            0
        );
        assert_eq!(
            diagnostic_message_for_test(diagnostic),
            b"invalid string conversion: native integer argument conversion failed: expected numeric scalar, got array"
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let mut null_diagnostic = NativeDiagnosticHandle::null();
        assert_eq!(
            unsafe {
                phpc_native_value_to_int_with_diagnostic(
                    NativeValueHandle::null(),
                    &mut null_diagnostic,
                )
            },
            0
        );
        assert_eq!(
            diagnostic_message_for_test(null_diagnostic),
            b"invalid string conversion: native integer argument conversion failed: value handle is null"
        );
        unsafe { phpc_native_diagnostic_free(null_diagnostic) };

        unsafe { phpc_native_array_free(array) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(offset_read) };
        unsafe { phpc_native_value_free(offset) };
        unsafe { phpc_native_value_free(offset_source) };
        unsafe { phpc_native_value_free(non_numeric) };
        unsafe { phpc_native_value_free(reversed) };
        unsafe { phpc_native_value_free(reversed_source) };
        unsafe { phpc_native_value_free(float_number) };
        unsafe { phpc_native_value_free(text_number) };
        unsafe { phpc_native_value_free(binary_number) };
    }

    #[test]
    fn native_value_strict_identity_abi_uses_shared_php_value_semantics() {
        let int_value = phpc_native_value_from_scalar(phpc_native_int(7));
        let same_int = phpc_native_value_from_scalar(phpc_native_int(7));
        let float_value = phpc_native_value_from_scalar(phpc_native_float(7.0));
        let text_string = NativeValueHandle::from_value(Value::String("A".to_string()));
        let binary_string = NativeValueHandle::from_value(Value::BinaryString(b"A".to_vec()));

        assert!(unsafe { phpc_native_value_strict_identity(int_value, same_int) });
        assert!(unsafe { phpc_native_value_strict_identity_scalar(int_value, phpc_native_int(7)) });
        assert!(!unsafe { phpc_native_value_strict_identity(int_value, float_value) });
        assert!(!unsafe {
            phpc_native_value_strict_identity_scalar(int_value, phpc_native_float(7.0))
        });
        assert!(unsafe { phpc_native_value_strict_identity(text_string, binary_string) });
        assert!(unsafe {
            phpc_native_value_strict_identity_scalar(NativeValueHandle::null(), phpc_native_null())
        });

        unsafe { phpc_native_value_free(binary_string) };
        unsafe { phpc_native_value_free(text_string) };
        unsafe { phpc_native_value_free(float_value) };
        unsafe { phpc_native_value_free(same_int) };
        unsafe { phpc_native_value_free(int_value) };
    }

