    #[test]
    fn native_value_type_name_result_abi_materializes_type_names_and_family_blockers() {
        fn assert_type_name(handle: NativeValueHandle, kind: u8, expected: &[u8]) {
            let result = unsafe { phpc_native_value_type_name_result(handle, kind) };
            assert!(result.succeeded());
            assert_eq!(native_value_echo_bytes_for_test(result.value), expected);
            unsafe { phpc_native_array_lvalue_result_free(result) };
        }

        fn assert_type_name_diagnostic(handle: NativeValueHandle, kind: u8, expected: &[u8]) {
            let result = unsafe { phpc_native_value_type_name_result(handle, kind) };
            assert!(!result.succeeded());
            assert!(result.value.is_null());
            assert_eq!(diagnostic_message_for_test(result.diagnostic), expected);
            unsafe { phpc_native_array_lvalue_result_free(result) };
        }

        let bool_value = phpc_native_value_from_scalar(phpc_native_bool(false));
        let int_value = phpc_native_value_from_scalar(phpc_native_int(7));
        let float_value = phpc_native_value_from_scalar(phpc_native_float(2.5));
        let text_string = native_value_from_test_string(b"text");
        let binary_string = NativeValueHandle::from_value(Value::BinaryString(vec![0xff, b'A']));
        let array_value = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let closure_value =
            NativeValueHandle::from_value(Value::Closure(PhpClosure::new(7, false, Vec::new())));
        let resource_value = NativeValueHandle::from_value(Value::Resource(9));

        assert_type_name(
            NativeValueHandle::null(),
            NATIVE_VALUE_TYPE_NAME_GETTYPE,
            b"NULL",
        );
        assert_type_name(bool_value, NATIVE_VALUE_TYPE_NAME_GETTYPE, b"boolean");
        assert_type_name(int_value, NATIVE_VALUE_TYPE_NAME_DEBUG, b"int");
        assert_type_name(float_value, NATIVE_VALUE_TYPE_NAME_GETTYPE, b"double");
        assert_type_name(text_string, NATIVE_VALUE_TYPE_NAME_DEBUG, b"string");
        assert_type_name(binary_string, NATIVE_VALUE_TYPE_NAME_GETTYPE, b"string");
        assert_type_name(array_value, NATIVE_VALUE_TYPE_NAME_DEBUG, b"array");
        assert_type_name(closure_value, NATIVE_VALUE_TYPE_NAME_GETTYPE, b"object");

        assert_type_name_diagnostic(
            int_value,
            u8::MAX,
            b"native value type-name operation tag 255 is not supported",
        );
        assert_type_name_diagnostic(
            closure_value,
            NATIVE_VALUE_TYPE_NAME_DEBUG,
            b"native value get_debug_type rejects object debug names until native class metadata, closure names, object handles, copy-on-write/reference identity, cleanup ownership, and exact diagnostics exist",
        );
        assert_type_name_diagnostic(
            resource_value,
            NATIVE_VALUE_TYPE_NAME_DEBUG,
            b"native value get_debug_type rejects resource debug names until native resource type names, resource lifecycle state, cleanup ownership, and exact diagnostics exist",
        );

        unsafe { phpc_native_value_free(resource_value) };
        unsafe { phpc_native_value_free(closure_value) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(binary_string) };
        unsafe { phpc_native_value_free(text_string) };
        unsafe { phpc_native_value_free(float_value) };
        unsafe { phpc_native_value_free(int_value) };
        unsafe { phpc_native_value_free(bool_value) };
    }

