        assert_type_name(null_value, false, b"NULL");
        assert_type_name(bool_value, false, b"boolean");
        assert_type_name(int_value, true, b"int");
        assert_type_name(text_string, true, b"string");
        assert_type_name(binary_string, false, b"string");
