    #[test]
    fn native_termination_status_value_classifies_scalar_status_and_messages() {
        let integer_statuses = [(7, 7), (300, 300), (i64::from(i32::MAX) + 1, i32::MIN)];
        for (input, expected) in integer_statuses {
            let value = phpc_native_value_from_scalar(phpc_native_int(input));
            assert_eq!(
                unsafe { phpc_native_termination_status_value(value) },
                expected
            );
            unsafe { phpc_native_value_free(value) };
        }

        for scalar in [
            phpc_native_null(),
            phpc_native_bool(false),
            phpc_native_bool(true),
            phpc_native_float(1.5),
        ] {
            let value = phpc_native_value_from_scalar(scalar);
            assert_eq!(unsafe { phpc_native_termination_status_value(value) }, 0);
            unsafe { phpc_native_value_free(value) };
        }

        for bytes in [&b"native termination"[..], &[0xff, b'p', b'h', b'p'][..]] {
            let value = unsafe { phpc_native_binary_value_from_bytes(bytes.as_ptr(), bytes.len()) };
            assert_eq!(unsafe { phpc_native_termination_status_value(value) }, 0);
            assert_eq!(native_value_echo_bytes_for_test(value), bytes);
            unsafe { phpc_native_value_free(value) };
        }

        assert_eq!(
            unsafe { phpc_native_termination_status_value(NativeValueHandle::null()) },
            255
        );
    }

