    #[test]
    fn native_array_lvalue_owner_foreach_value_reference_result_aliases_owner_path_families() {
        fn assert_owner_read(
            owner: NativeArrayLvalueOwner,
            path: &[NativeArrayPathSegment],
            expected: &[u8],
        ) {
            let read = unsafe {
                phpc_native_array_lvalue_owner_read_result(owner, path.as_ptr(), path.len())
            };
            assert_eq!(read.tag, NATIVE_ARRAY_LVALUE_OK);
            assert_eq!(native_value_echo_bytes_for_test(read.value), expected);
            unsafe { phpc_native_array_lvalue_result_free(read) };
        }

        let array = phpc_native_array_empty();
        assert!(unsafe { phpc_native_array_write_int_scalar(array, 0, phpc_native_int(10)) });
        let array_owner = phpc_native_array_lvalue_owner_array(array);
        let array_reference = unsafe {
            phpc_native_array_lvalue_owner_foreach_value_reference_result(
                array_owner,
                std::ptr::null(),
                0,
                0,
            )
        };
        assert_eq!(array_reference.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(unsafe {
            phpc_native_reference_write_scalar(array_reference.reference, phpc_native_int(90))
        });
        let zero_key = phpc_native_value_from_scalar(phpc_native_int(0));
        let zero_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: zero_key,
        }];
        assert_owner_read(array_owner, &zero_path, b"90");
        unsafe { phpc_native_array_reference_result_free(array_reference) };

        let mut nested = PhpArray::new();
        nested.insert(ArrayKey::string("target"), Value::String("old".to_string()));
        let mut outer = PhpArray::new();
        outer.insert(ArrayKey::string("items"), Value::Array(nested));
        let mut slot = NativeValueHandle::from_value(Value::Array(outer));
        let items_key = native_value_from_test_string(b"items");
        let target_key = native_value_from_test_string(b"target");
        let items_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: items_key,
        }];
        let nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: items_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: target_key,
            },
        ];
        let slot_owner = phpc_native_array_lvalue_owner_value_slot(&mut slot);
        let slot_reference = unsafe {
            phpc_native_array_lvalue_owner_foreach_value_reference_result(
                slot_owner,
                items_path.as_ptr(),
                items_path.len(),
                0,
            )
        };
        assert_eq!(slot_reference.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(unsafe {
            phpc_native_reference_write_scalar(slot_reference.reference, phpc_native_int(44))
        });
        assert_owner_read(slot_owner, &nested_path, b"44");
        unsafe { phpc_native_array_reference_result_free(slot_reference) };

        let mut reference_array = PhpArray::new();
        reference_array.insert(ArrayKey::Int(3), Value::Int(3));
        let reference = NativeReferenceHandle::from_value(Value::Array(reference_array));
        let reference_owner = phpc_native_array_lvalue_owner_reference_slot(reference);
        let reference_result = unsafe {
            phpc_native_array_lvalue_owner_foreach_value_reference_result(
                reference_owner,
                std::ptr::null(),
                0,
                0,
            )
        };
        assert_eq!(reference_result.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(unsafe {
            phpc_native_reference_write_scalar(reference_result.reference, phpc_native_int(77))
        });
        let three_key = phpc_native_value_from_scalar(phpc_native_int(3));
        let three_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: three_key,
        }];
        assert_owner_read(reference_owner, &three_path, b"77");
        unsafe { phpc_native_array_reference_result_free(reference_result) };

        unsafe { phpc_native_value_free(three_key) };
        unsafe { phpc_native_reference_free(reference) };
        unsafe { phpc_native_value_free(target_key) };
        unsafe { phpc_native_value_free(items_key) };
        unsafe { phpc_native_value_free(slot) };
        unsafe { phpc_native_value_free(zero_key) };
        unsafe { phpc_native_array_free(array) };
    }

    #[test]
    fn native_array_lvalue_owner_foreach_value_reference_result_classifies_blockers() {
        let mut root_array = PhpArray::new();
        root_array.insert(ArrayKey::Int(0), Value::Int(1));
        let root_value = NativeValueHandle::from_value(Value::Array(root_array));
        let root_owner = phpc_native_array_lvalue_owner_value_root(root_value);
        let value_root_blocked = unsafe {
            phpc_native_array_lvalue_owner_foreach_value_reference_result(
                root_owner,
                std::ptr::null(),
                0,
                0,
            )
        };
        assert_eq!(
            value_root_blocked.tag,
            NATIVE_ARRAY_LVALUE_COW_REFERENCE_BLOCKED
        );
        assert_eq!(
            diagnostic_message_for_test(value_root_blocked.diagnostic),
            b"array lvalue by-reference foreach through a value root needs owner-slot materialization with copy-on-write and reference aliasing"
        );
        unsafe { phpc_native_array_reference_result_free(value_root_blocked) };

        let array = phpc_native_array_empty();
        let array_owner = phpc_native_array_lvalue_owner_array(array);
        let out_of_range = unsafe {
            phpc_native_array_lvalue_owner_foreach_value_reference_result(
                array_owner,
                std::ptr::null(),
                0,
                4,
            )
        };
        assert_eq!(out_of_range.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            diagnostic_message_for_test(out_of_range.diagnostic),
            b"array foreach reference index 4 is out of range"
        );
        unsafe { phpc_native_array_reference_result_free(out_of_range) };

        let append_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_APPEND,
            key: NativeValueHandle::null(),
        }];
        let append = unsafe {
            phpc_native_array_lvalue_owner_foreach_value_reference_result(
                array_owner,
                append_path.as_ptr(),
                append_path.len(),
                0,
            )
        };
        assert_eq!(append.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            diagnostic_message_for_test(append.diagnostic),
            b"array by-reference foreach iterable path cannot contain append segments"
        );
        unsafe { phpc_native_array_reference_result_free(append) };

        unsafe { phpc_native_array_free(array) };
        unsafe { phpc_native_value_free(root_value) };
    }

    #[test]
    fn native_array_lvalue_owner_foreach_iterable_result_classifies_blockers() {
        let scalar_root = phpc_native_value_from_scalar(phpc_native_int(7));
        let scalar_owner = phpc_native_array_lvalue_owner_value_root(scalar_root);
        let scalar = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                scalar_owner,
                std::ptr::null(),
                0,
            )
        };
        assert_eq!(scalar.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            diagnostic_message_for_test(scalar.diagnostic),
            b"invalid foreach: cannot iterate int array lvalue iterable"
        );
        unsafe { phpc_native_array_lvalue_result_free(scalar) };

        let mut slot = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let missing_key = native_value_from_test_string(b"missing");
        let missing_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: missing_key,
        }];
        let missing = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                phpc_native_array_lvalue_owner_value_slot(&mut slot),
                missing_path.as_ptr(),
                missing_path.len(),
            )
        };
        assert_eq!(missing.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            diagnostic_message_for_test(missing.diagnostic),
            b"invalid foreach: missing array lvalue iterable"
        );
        unsafe { phpc_native_array_lvalue_result_free(missing) };

        let append_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_APPEND,
            key: NativeValueHandle::null(),
        }];
        let append = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                phpc_native_array_lvalue_owner_value_slot(&mut slot),
                append_path.as_ptr(),
                append_path.len(),
            )
        };
        assert_eq!(append.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            diagnostic_message_for_test(append.diagnostic),
            b"array foreach iterable path cannot contain append segments"
        );
        unsafe { phpc_native_array_lvalue_result_free(append) };

        let non_array = phpc_native_value_from_scalar(phpc_native_int(1));
        let non_array_key = unsafe { phpc_native_array_foreach_iterable_key_result(non_array, 0) };
        assert_eq!(non_array_key.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            diagnostic_message_for_test(non_array_key.diagnostic),
            b"array foreach key read received a non-array iterable handle"
        );
        unsafe { phpc_native_array_lvalue_result_free(non_array_key) };

        unsafe { phpc_native_value_free(non_array) };
        unsafe { phpc_native_value_free(missing_key) };
        unsafe { phpc_native_value_free(slot) };
        unsafe { phpc_native_value_free(scalar_root) };
    }

    #[test]
    fn native_array_lvalue_owner_probe_results_reuse_read_boundary_for_isset_empty() {
        let key = native_value_from_test_string(b"slot");
        let binary_key_bytes = [b'b', 0, 0xff];
        let binary_key = unsafe {
            phpc_native_binary_value_from_bytes(binary_key_bytes.as_ptr(), binary_key_bytes.len())
        };
        let missing_key = native_value_from_test_string(b"missing");
        let invalid_key = phpc_native_value_from_scalar(phpc_native_float(1.5));
        let path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key,
        }];
        let binary_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: binary_key,
        }];
        let missing_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: missing_key,
        }];
        let invalid_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: invalid_key,
        }];

        let mut slot = phpc_native_value_from_scalar(phpc_native_null());
        let slot_owner = phpc_native_array_lvalue_owner_value_slot(&mut slot);
        let missing_isset = unsafe {
            phpc_native_array_lvalue_owner_isset_result(
                slot_owner,
                missing_path.as_ptr(),
                missing_path.len(),
            )
        };
        assert_eq!(missing_isset.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(!unsafe { phpc_native_value_truthy(missing_isset.value) });
        unsafe { phpc_native_array_lvalue_result_free(missing_isset) };

        let missing_empty = unsafe {
            phpc_native_array_lvalue_owner_empty_result(
                slot_owner,
                missing_path.as_ptr(),
                missing_path.len(),
            )
        };
        assert_eq!(missing_empty.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(unsafe { phpc_native_value_truthy(missing_empty.value) });
        unsafe { phpc_native_array_lvalue_result_free(missing_empty) };

        let zero = phpc_native_value_from_scalar(phpc_native_int(0));
        let assigned_zero = unsafe {
            phpc_native_array_lvalue_owner_assign_value_result(
                slot_owner,
                path.as_ptr(),
                path.len(),
                zero,
            )
        };
        assert_eq!(assigned_zero.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(assigned_zero) };

        let zero_isset = unsafe {
            phpc_native_array_lvalue_owner_isset_result(slot_owner, path.as_ptr(), path.len())
        };
        assert_eq!(zero_isset.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(unsafe { phpc_native_value_truthy(zero_isset.value) });
        unsafe { phpc_native_array_lvalue_result_free(zero_isset) };

        let zero_empty = unsafe {
            phpc_native_array_lvalue_owner_empty_result(slot_owner, path.as_ptr(), path.len())
        };
        assert_eq!(zero_empty.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(unsafe { phpc_native_value_truthy(zero_empty.value) });
        unsafe { phpc_native_array_lvalue_result_free(zero_empty) };

        let text = native_value_from_test_string(b"value");
        let assigned_text = unsafe {
            phpc_native_array_lvalue_owner_assign_value_result(
                slot_owner,
                binary_path.as_ptr(),
                binary_path.len(),
                text,
            )
        };
        assert_eq!(assigned_text.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(assigned_text) };

        let text_empty = unsafe {
            phpc_native_array_lvalue_owner_empty_result(
                slot_owner,
                binary_path.as_ptr(),
                binary_path.len(),
            )
        };
        assert_eq!(text_empty.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(!unsafe { phpc_native_value_truthy(text_empty.value) });
        unsafe { phpc_native_array_lvalue_result_free(text_empty) };

        let array_value = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let value_root_owner = phpc_native_array_lvalue_owner_value_root(array_value);
        let value_root_missing = unsafe {
            phpc_native_array_lvalue_owner_isset_result(
                value_root_owner,
                missing_path.as_ptr(),
                missing_path.len(),
            )
        };
        assert_eq!(value_root_missing.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(!unsafe { phpc_native_value_truthy(value_root_missing.value) });
        unsafe { phpc_native_array_lvalue_result_free(value_root_missing) };

        let bad_key = unsafe {
            phpc_native_array_lvalue_owner_empty_result(
                slot_owner,
                invalid_path.as_ptr(),
                invalid_path.len(),
            )
        };
        assert_eq!(bad_key.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            diagnostic_message_for_test(bad_key.diagnostic),
            b"invalid array key: lossy or non-finite float keys are not supported; only null, bool, int, string, and integral finite float keys are implemented"
        );
        unsafe { phpc_native_array_lvalue_result_free(bad_key) };

        let mut scalar_slot = phpc_native_value_from_scalar(phpc_native_int(7));
        let scalar_owner = phpc_native_array_lvalue_owner_value_slot(&mut scalar_slot);
        let scalar_blocked = unsafe {
            phpc_native_array_lvalue_owner_isset_result(scalar_owner, path.as_ptr(), path.len())
        };
        assert_eq!(scalar_blocked.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            diagnostic_message_for_test(scalar_blocked.diagnostic),
            b"cannot use int as array lvalue owner slot"
        );
        unsafe { phpc_native_array_lvalue_result_free(scalar_blocked) };

        unsafe { phpc_native_value_free(scalar_slot) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(text) };
        unsafe { phpc_native_value_free(zero) };
        unsafe { phpc_native_value_free(slot) };
        unsafe { phpc_native_value_free(invalid_key) };
        unsafe { phpc_native_value_free(missing_key) };
        unsafe { phpc_native_value_free(binary_key) };
        unsafe { phpc_native_value_free(key) };
    }

    #[test]
    fn native_array_lvalue_owner_reference_result_promotes_paths_and_preserves_aliases() {
        let key = native_value_from_test_string(b"slot");
        let nested = native_value_from_test_string(b"nested");
        let append_parent = native_value_from_test_string(b"refs");
        let leaf = native_value_from_test_string(b"leaf");
        let zero = phpc_native_value_from_scalar(phpc_native_int(0));
        let invalid_key = phpc_native_value_from_scalar(phpc_native_float(1.5));
        let path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key,
        }];
        let nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: nested,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf,
            },
        ];
        let append_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: append_parent,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf,
            },
        ];
        let appended_read_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: append_parent,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: zero,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf,
            },
        ];
        let invalid_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: invalid_key,
        }];

        let mut slot = phpc_native_value_from_scalar(phpc_native_null());
        let owner = phpc_native_array_lvalue_owner_value_slot(&mut slot);

        let promoted = unsafe {
            phpc_native_array_lvalue_owner_reference_result(owner, path.as_ptr(), path.len())
        };
        assert_eq!(promoted.tag, NATIVE_ARRAY_LVALUE_OK);
        let reference_value = native_value_from_test_string(b"from-reference");
        assert!(unsafe { phpc_native_reference_write_value(promoted.reference, reference_value) });
        unsafe { phpc_native_value_free(reference_value) };

        let read =
            unsafe { phpc_native_array_lvalue_owner_read_result(owner, path.as_ptr(), path.len()) };
        assert_eq!(read.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(read.value),
            b"from-reference"
        );
        unsafe { phpc_native_array_lvalue_result_free(read) };

        let write_value = native_value_from_test_string(b"from-lvalue");
        let assigned = unsafe {
            phpc_native_array_lvalue_owner_assign_value_result(
                owner,
                path.as_ptr(),
                path.len(),
                write_value,
            )
        };
        assert_eq!(assigned.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(assigned) };
        let reference_read = unsafe { phpc_native_reference_read_value(promoted.reference) };
        assert_eq!(
            native_value_echo_bytes_for_test(reference_read),
            b"from-lvalue"
        );
        unsafe { phpc_native_value_free(reference_read) };
        unsafe { phpc_native_value_free(write_value) };
        unsafe { phpc_native_array_reference_result_free(promoted) };

        let nested_promoted = unsafe {
            phpc_native_array_lvalue_owner_reference_result(
                owner,
                nested_path.as_ptr(),
                nested_path.len(),
            )
        };
        assert_eq!(nested_promoted.tag, NATIVE_ARRAY_LVALUE_OK);
        let nested_value = native_value_from_test_string(b"nested\0reference");
        assert!(unsafe {
            phpc_native_reference_write_value(nested_promoted.reference, nested_value)
        });
        unsafe { phpc_native_value_free(nested_value) };
        unsafe { phpc_native_array_reference_result_free(nested_promoted) };
        let nested_read = unsafe {
            phpc_native_array_lvalue_owner_read_result(
                owner,
                nested_path.as_ptr(),
                nested_path.len(),
            )
        };
        assert_eq!(nested_read.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(nested_read.value),
            b"nested\0reference"
        );
        unsafe { phpc_native_array_lvalue_result_free(nested_read) };

        let appended = unsafe {
            phpc_native_array_lvalue_owner_reference_result(
                owner,
                append_path.as_ptr(),
                append_path.len(),
            )
        };
        assert_eq!(appended.tag, NATIVE_ARRAY_LVALUE_OK);
        let appended_value = native_value_from_test_string(b"appended-reference");
        assert!(unsafe { phpc_native_reference_write_value(appended.reference, appended_value) });
        unsafe { phpc_native_value_free(appended_value) };
        unsafe { phpc_native_array_reference_result_free(appended) };
        let appended_read = unsafe {
            phpc_native_array_lvalue_owner_read_result(
                owner,
                appended_read_path.as_ptr(),
                appended_read_path.len(),
            )
        };
        assert_eq!(appended_read.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(appended_read.value),
            b"appended-reference"
        );
        unsafe { phpc_native_array_lvalue_result_free(appended_read) };

        let bad_key = unsafe {
            phpc_native_array_lvalue_owner_reference_result(
                owner,
                invalid_path.as_ptr(),
                invalid_path.len(),
            )
        };
        assert_eq!(bad_key.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            diagnostic_message_for_test(bad_key.diagnostic),
            b"invalid array key: lossy or non-finite float keys are not supported; only null, bool, int, string, and integral finite float keys are implemented"
        );
        unsafe { phpc_native_array_reference_result_free(bad_key) };

        let array_value = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let value_root_owner = phpc_native_array_lvalue_owner_value_root(array_value);
        let cow_blocked = unsafe {
            phpc_native_array_lvalue_owner_reference_result(
                value_root_owner,
                path.as_ptr(),
                path.len(),
            )
        };
        assert_eq!(cow_blocked.tag, NATIVE_ARRAY_LVALUE_COW_REFERENCE_BLOCKED);
        assert_eq!(
            diagnostic_message_for_test(cow_blocked.diagnostic),
            b"array lvalue reference through a value root needs owner-slot materialization with copy-on-write and reference aliasing"
        );
        unsafe { phpc_native_array_reference_result_free(cow_blocked) };

        let mut scalar_slot = phpc_native_value_from_scalar(phpc_native_int(7));
        let scalar_owner = phpc_native_array_lvalue_owner_value_slot(&mut scalar_slot);
        let scalar_blocked = unsafe {
            phpc_native_array_lvalue_owner_reference_result(scalar_owner, path.as_ptr(), path.len())
        };
        assert_eq!(scalar_blocked.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            diagnostic_message_for_test(scalar_blocked.diagnostic),
            b"cannot use int as array lvalue owner slot"
        );
        unsafe { phpc_native_array_reference_result_free(scalar_blocked) };

        unsafe { phpc_native_value_free(scalar_slot) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(slot) };
        unsafe { phpc_native_value_free(invalid_key) };
        unsafe { phpc_native_value_free(zero) };
        unsafe { phpc_native_value_free(leaf) };
        unsafe { phpc_native_value_free(append_parent) };
        unsafe { phpc_native_value_free(nested) };
        unsafe { phpc_native_value_free(key) };
    }

    #[test]
    fn native_array_lvalue_owner_bind_reference_result_binds_paths_and_classifies_blockers() {
        let key = native_value_from_test_string(b"slot");
        let nested = native_value_from_test_string(b"refs");
        let leaf = native_value_from_test_string(b"leaf");
        let zero = phpc_native_value_from_scalar(phpc_native_int(0));
        let invalid_key = phpc_native_value_from_scalar(phpc_native_float(1.5));
        let path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key,
        }];
        let append_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: nested,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf,
            },
        ];
        let appended_read_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: nested,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: zero,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf,
            },
        ];
        let invalid_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: invalid_key,
        }];

        let mut slot = phpc_native_value_from_scalar(phpc_native_null());
        let owner = phpc_native_array_lvalue_owner_value_slot(&mut slot);
        let source_value = native_value_from_test_string(b"source");
        let source_reference = unsafe { phpc_native_reference_from_value(source_value) };
        unsafe { phpc_native_value_free(source_value) };

        let bound = unsafe {
            phpc_native_array_lvalue_owner_bind_reference_result(
                owner,
                path.as_ptr(),
                path.len(),
                source_reference,
            )
        };
        assert_eq!(bound.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(bound) };

        let changed = native_value_from_test_string(b"changed-through-reference");
        assert!(unsafe { phpc_native_reference_write_value(source_reference, changed) });
        unsafe { phpc_native_value_free(changed) };
        let read =
            unsafe { phpc_native_array_lvalue_owner_read_result(owner, path.as_ptr(), path.len()) };
        assert_eq!(read.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(read.value),
            b"changed-through-reference"
        );
        unsafe { phpc_native_array_lvalue_result_free(read) };

        let write_value = native_value_from_test_string(b"changed-through-lvalue");
        let assigned = unsafe {
            phpc_native_array_lvalue_owner_assign_value_result(
                owner,
                path.as_ptr(),
                path.len(),
                write_value,
            )
        };
        assert_eq!(assigned.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(assigned) };
        let source_read = unsafe { phpc_native_reference_read_value(source_reference) };
        assert_eq!(
            native_value_echo_bytes_for_test(source_read),
            b"changed-through-lvalue"
        );
        unsafe { phpc_native_value_free(source_read) };
        unsafe { phpc_native_value_free(write_value) };

        let nested_value = native_value_from_test_string(b"nested-bind");
        assert!(unsafe { phpc_native_reference_write_value(source_reference, nested_value) });
        unsafe { phpc_native_value_free(nested_value) };
        let append_bound = unsafe {
            phpc_native_array_lvalue_owner_bind_reference_result(
                owner,
                append_path.as_ptr(),
                append_path.len(),
                source_reference,
            )
        };
        assert_eq!(append_bound.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(append_bound) };
        let append_read = unsafe {
            phpc_native_array_lvalue_owner_read_result(
                owner,
                appended_read_path.as_ptr(),
                appended_read_path.len(),
            )
        };
        assert_eq!(append_read.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(append_read.value),
            b"nested-bind"
        );
        unsafe { phpc_native_array_lvalue_result_free(append_read) };

        let null_reference = unsafe {
            phpc_native_array_lvalue_owner_bind_reference_result(
                owner,
                path.as_ptr(),
                path.len(),
                NativeReferenceHandle::null(),
            )
        };
        assert_eq!(null_reference.tag, NATIVE_ARRAY_LVALUE_UNSUPPORTED);
        assert_eq!(
            diagnostic_message_for_test(null_reference.diagnostic),
            b"array lvalue reference binding received a null reference handle"
        );
        unsafe { phpc_native_array_lvalue_result_free(null_reference) };

        let bad_key = unsafe {
            phpc_native_array_lvalue_owner_bind_reference_result(
                owner,
                invalid_path.as_ptr(),
                invalid_path.len(),
                source_reference,
            )
        };
        assert_eq!(bad_key.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            diagnostic_message_for_test(bad_key.diagnostic),
            b"invalid array key: lossy or non-finite float keys are not supported; only null, bool, int, string, and integral finite float keys are implemented"
        );
        unsafe { phpc_native_array_lvalue_result_free(bad_key) };

        let array_value = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let value_root_owner = phpc_native_array_lvalue_owner_value_root(array_value);
        let cow_reference = unsafe {
            phpc_native_array_lvalue_owner_reference_result(
                value_root_owner,
                path.as_ptr(),
                path.len(),
            )
        };
        assert_eq!(cow_reference.tag, NATIVE_ARRAY_LVALUE_COW_REFERENCE_BLOCKED);
        assert_eq!(
            diagnostic_message_for_test(cow_reference.diagnostic),
            b"array lvalue reference through a value root needs owner-slot materialization with copy-on-write and reference aliasing"
        );
        unsafe { phpc_native_array_reference_result_free(cow_reference) };
        let cow_bind = unsafe {
            phpc_native_array_lvalue_owner_bind_reference_result(
                value_root_owner,
                path.as_ptr(),
                path.len(),
                source_reference,
            )
        };
        assert_eq!(cow_bind.tag, NATIVE_ARRAY_LVALUE_COW_REFERENCE_BLOCKED);
        assert_eq!(
            diagnostic_message_for_test(cow_bind.diagnostic),
            b"array lvalue reference binding through a value root needs owner-slot materialization with copy-on-write and reference aliasing"
        );
        unsafe { phpc_native_array_lvalue_result_free(cow_bind) };

        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_reference_free(source_reference) };
        unsafe { phpc_native_value_free(slot) };
        unsafe { phpc_native_value_free(invalid_key) };
        unsafe { phpc_native_value_free(zero) };
        unsafe { phpc_native_value_free(leaf) };
        unsafe { phpc_native_value_free(nested) };
        unsafe { phpc_native_value_free(key) };
    }

    #[test]
    fn native_diagnostic_helpers_accept_null_handles() {
        let diagnostic = NativeDiagnosticHandle::null();

        assert_eq!(unsafe { phpc_native_diagnostic_message_len(diagnostic) }, 0);
        let message = unsafe { phpc_native_diagnostic_message_clone_bytes(diagnostic) };
        assert!(message.ptr().is_null());
        assert_eq!(message.len(), 0);
        assert_eq!(message.cap(), 0);
        assert_eq!(
            unsafe { phpc_native_diagnostic_message_stderr(diagnostic) },
            0
        );

        unsafe { phpc_native_byte_buffer_free(message) };
        unsafe { phpc_native_diagnostic_free(diagnostic) };
    }

    #[test]
    fn native_diagnostic_message_stderr_reports_message_length() {
        let string = unsafe { phpc_native_string_from_bytes(ptr::null(), 4) };
        let mut diagnostic = NativeDiagnosticHandle::null();
        let value =
            unsafe { phpc_native_value_from_string_with_diagnostic(string, &mut diagnostic) };

        assert!(value.is_null());
        assert_eq!(
            unsafe { phpc_native_diagnostic_message_stderr(diagnostic) },
            "native value conversion failed: string handle is null".len()
        );

        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(value) };
        unsafe { phpc_native_string_free(string) };
    }

